CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.role',true),'') $$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
CREATE TABLE public.audit_logs("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"user_id" uuid,"action" text NOT NULL,"table_name" text,"record_id" uuid,"old_data" jsonb,"new_data" jsonb,"reason" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.awards("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"player_id" uuid NOT NULL,"award_type" text NOT NULL,"period_type" text NOT NULL,"period_start" date NOT NULL,"period_end" date NOT NULL,"metric_value" numeric,"title" text NOT NULL,"note" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.fund_categories("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"name" text NOT NULL,"category_type" text NOT NULL,"is_active" boolean DEFAULT true NOT NULL);
CREATE TABLE public.fund_contributions("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"match_id" uuid,"player_id" uuid NOT NULL,"reason" text NOT NULL,"amount_due" numeric NOT NULL,"status" text DEFAULT 'CHUA_DONG'::text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"campaign_id" uuid,"due_date" date);
CREATE TABLE public.fund_obligation_campaigns("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"category" text NOT NULL,"title" text NOT NULL,"period_month" date,"amount_due" numeric NOT NULL,"due_date" date,"note" text,"status" text DEFAULT 'ACTIVE'::text NOT NULL,"created_by" uuid NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.fund_payments("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"contribution_id" uuid NOT NULL,"player_id" uuid NOT NULL,"amount" numeric NOT NULL,"paid_at" timestamp with time zone DEFAULT now() NOT NULL,"confirmed_by" uuid,"note" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.fund_rules("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"match_type" text NOT NULL,"amount_loss" numeric DEFAULT 0 NOT NULL,"amount_draw" numeric DEFAULT 0 NOT NULL,"amount_win" numeric DEFAULT 0 NOT NULL,"effective_from" date NOT NULL,"effective_to" date,"is_active" boolean DEFAULT true NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.fund_transactions("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"transaction_date" timestamp with time zone DEFAULT now() NOT NULL,"transaction_type" text NOT NULL,"amount" numeric NOT NULL,"description" text NOT NULL,"player_id" uuid,"match_id" uuid,"tournament_id" uuid,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"payment_id" uuid,"reversal_of_transaction_id" uuid);
CREATE TABLE public.leagues("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"name" text NOT NULL,"code" text NOT NULL,"start_date" date NOT NULL,"end_date" date NOT NULL,"status" text DEFAULT 'DU_KIEN'::text NOT NULL,"notes" text,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.match_players("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"match_id" uuid NOT NULL,"player_id" uuid NOT NULL,"team" text NOT NULL,"partner_player_id" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.matches("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"played_at" timestamp with time zone NOT NULL,"match_number" integer,"match_type" text DEFAULT 'CLUB_RATED'::text NOT NULL,"score_mode" text DEFAULT 'POINTS'::text NOT NULL,"team_a_score" integer DEFAULT 0 NOT NULL,"team_b_score" integer DEFAULT 0 NOT NULL,"status" text DEFAULT 'PENDING'::text NOT NULL,"invalid_reason" text,"tournament_id" uuid,"notes" text,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,"replaces_match_id" uuid,"league_id" uuid,"opponent_confirmed_by" uuid,"opponent_confirmed_at" timestamp with time zone,"opponent_rejected_by" uuid,"opponent_rejected_at" timestamp with time zone,"opponent_rejection_reason" text);
CREATE TABLE public.players("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"full_name" text NOT NULL,"player_type" text DEFAULT 'CLUB'::text NOT NULL,"phone" text,"email" text,"initial_rating" numeric(6,3) DEFAULT 4.000 NOT NULL,"current_rating" numeric(6,3) DEFAULT 4.000 NOT NULL,"status" text DEFAULT 'ACTIVE'::text NOT NULL,"joined_at" date,"notes" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,"date_of_birth" date);
CREATE TABLE public.profiles("id" uuid NOT NULL PRIMARY KEY,"full_name" text,"role" text DEFAULT 'MEMBER'::text NOT NULL,"is_active" boolean DEFAULT true NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL,"can_collect_tournament_fee" boolean DEFAULT false NOT NULL,"player_id" uuid,"login_name" text,"must_change_password" boolean DEFAULT false NOT NULL,"can_approve_matches" boolean DEFAULT false NOT NULL,"can_manage_tournaments" boolean DEFAULT false NOT NULL,"can_manage_fund" boolean DEFAULT false NOT NULL,"can_manage_members" boolean DEFAULT false NOT NULL,"can_adjust_rating" boolean DEFAULT false NOT NULL,"can_collect_fund" boolean DEFAULT false NOT NULL,"can_view_audit" boolean DEFAULT false NOT NULL,"membership_status" text DEFAULT 'PENDING'::text NOT NULL,"membership_reviewed_by" uuid,"membership_reviewed_at" timestamp with time zone,"can_manage_players" boolean DEFAULT false NOT NULL,"can_manage_player_lifecycle" boolean DEFAULT false NOT NULL);
CREATE TABLE public.rating_adjustment_events("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"adjustment_id" uuid NOT NULL,"player_id" uuid NOT NULL,"algorithm_version" text NOT NULL,"rating_before" numeric NOT NULL,"requested_amount" numeric NOT NULL,"applied_delta" numeric NOT NULL,"rating_after" numeric NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.rating_adjustments("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"player_id" uuid NOT NULL,"amount" numeric NOT NULL,"reason" text NOT NULL,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"effective_at" timestamp with time zone DEFAULT now() NOT NULL,"replay_order" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,"correction_of_adjustment_id" uuid,"request_id" uuid,"request_algorithm_version" text);
CREATE TABLE public.rating_events("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"match_id" uuid NOT NULL,"player_id" uuid NOT NULL,"algorithm_version" text NOT NULL,"rating_before" numeric(6,3) NOT NULL,"team_rating" numeric(6,3) NOT NULL,"opponent_team_rating" numeric(6,3) NOT NULL,"expected_share" numeric(8,5) NOT NULL,"actual_share" numeric(8,5) NOT NULL,"performance_gap" numeric(8,5) NOT NULL,"match_weight" numeric(6,3) NOT NULL,"recency_weight" numeric(6,3) NOT NULL,"provisional_factor" numeric(6,3) NOT NULL,"rating_delta" numeric(8,5) NOT NULL,"rating_after" numeric(6,3) NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.rating_match_weights("match_type" text NOT NULL,"weight" numeric NOT NULL,"description" text);
CREATE TABLE public.rating_settings("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,"algorithm_version" text DEFAULT 'V1.0'::text NOT NULL,"initial_rating" numeric DEFAULT 4.000 NOT NULL,"min_rating" numeric DEFAULT 2.000 NOT NULL,"max_rating" numeric DEFAULT 8.000 NOT NULL,"k_factor" numeric DEFAULT 0.550 NOT NULL,"expected_sensitivity" numeric DEFAULT 0.900 NOT NULL,"provisional_matches" integer DEFAULT 5 NOT NULL,"stable_matches" integer DEFAULT 10 NOT NULL,"recency_half_life_days" integer DEFAULT 60 NOT NULL,"recency_floor" numeric DEFAULT 0.350 NOT NULL,"rating_delta_cap" numeric DEFAULT 0.350 NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"is_active" boolean DEFAULT false NOT NULL);
CREATE TABLE public.tournament_expense_reversals("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"expense_id" uuid NOT NULL,"reversed_at" timestamp with time zone DEFAULT now() NOT NULL,"reason" text NOT NULL,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournament_expenses("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"tournament_id" uuid NOT NULL,"expense_date" date DEFAULT CURRENT_DATE NOT NULL,"category" text NOT NULL,"description" text NOT NULL,"amount" numeric NOT NULL,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournament_payment_refunds("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"payment_id" uuid NOT NULL,"amount" numeric NOT NULL,"refunded_at" timestamp with time zone DEFAULT now() NOT NULL,"reason" text NOT NULL,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournament_payments("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"registration_id" uuid NOT NULL,"player_id" uuid NOT NULL,"amount" numeric NOT NULL,"paid_at" timestamp with time zone DEFAULT now() NOT NULL,"confirmed_by" uuid,"note" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournament_registrations("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"tournament_id" uuid NOT NULL,"player_id" uuid NOT NULL,"event_name" text NOT NULL,"partner_player_id" uuid,"fee_due" numeric DEFAULT 0 NOT NULL,"status" text DEFAULT 'DANG_KY'::text NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournaments("id" uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,"name" text NOT NULL,"code" text,"start_date" date NOT NULL,"end_date" date,"location" text,"event_category" text,"format" text,"registration_fee" numeric DEFAULT 0 NOT NULL,"status" text DEFAULT 'DU_KIEN'::text NOT NULL,"notes" text,"created_by" uuid,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"updated_at" timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.rating_adjustments ADD UNIQUE(request_id);
