INSERT INTO public.rating_events("actual_share","algorithm_version","expected_share","id","match_id","match_weight","opponent_team_rating","performance_gap","player_id","provisional_factor","rating_after","rating_before","rating_delta","recency_weight","team_rating") SELECT r."actual_share",r."algorithm_version",r."expected_share",r."id",r."match_id",r."match_weight",r."opponent_team_rating",r."performance_gap",r."player_id",r."provisional_factor",r."rating_after",r."rating_before",r."rating_delta",r."recency_weight",r."team_rating" FROM json_populate_record(NULL::public.rating_events,'{"actual_share": 0, "algorithm_version": "V1.1", "expected_share": 0.87749, "id": "43d5b7fc-bf4b-4eb5-9f25-348bc144c14e", "match_id": "fbeddd53-0142-48f1-afa4-8c984b028c2b", "match_weight": 0.9, "opponent_team_rating": 3.556, "performance_gap": -0.87749, "player_id": "23c1639d-675f-4b9a-a331-3ce419306a6a", "provisional_factor": 1.1, "rating_after": 3.355, "rating_before": 3.705, "rating_delta": -0.35, "recency_weight": 0.776, "team_rating": 5.328}'::json) r;
INSERT INTO public.rating_events("actual_share","algorithm_version","expected_share","id","match_id","match_weight","opponent_team_rating","performance_gap","player_id","provisional_factor","rating_after","rating_before","rating_delta","recency_weight","team_rating") SELECT r."actual_share",r."algorithm_version",r."expected_share",r."id",r."match_id",r."match_weight",r."opponent_team_rating",r."performance_gap",r."player_id",r."provisional_factor",r."rating_after",r."rating_before",r."rating_delta",r."recency_weight",r."team_rating" FROM json_populate_record(NULL::public.rating_events,'{"actual_share": 1, "algorithm_version": "V1.1", "expected_share": 0.12251, "id": "9d450122-da91-4d6f-87b9-e1e676fa0314", "match_id": "fbeddd53-0142-48f1-afa4-8c984b028c2b", "match_weight": 0.9, "opponent_team_rating": 5.328, "performance_gap": 0.87749, "player_id": "b5146cb1-84e0-4690-a7ae-d6256b33586c", "provisional_factor": 1.25, "rating_after": 3.448, "rating_before": 3.098, "rating_delta": 0.35, "recency_weight": 0.776, "team_rating": 3.556}'::json) r;
CREATE OR REPLACE FUNCTION public._approve_match_internal(p_match_id uuid, p_algorithm_version text, p_actor_user_id uuid, p_opponent_confirmed_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_match public.matches%rowtype;\r\n  v_player_count integer;\r\n  v_team_a_count integer;\r\n  v_team_b_count integer;\r\n  v_league_club_count integer;\r\n  v_rule_count integer;\r\n  v_rating_result jsonb;\r\n  v_fund_result jsonb;\r\n  v_audit_action text;\r\nbegin\r\n  perform pg_advisory_xact_lock(726184501);\r\n\r\n  if p_actor_user_id is null then\r\n    raise exception ''APPROVAL_ACTOR_REQUIRED'';\r\n  end if;\r\n  if p_match_id is null then\r\n    raise exception ''match_id không được NULL'';\r\n  end if;\r\n  if p_algorithm_version is null or btrim(p_algorithm_version) = '''' then\r\n    raise exception ''algorithm_version không được để trống'';\r\n  end if;\r\n\r\n  select * into v_match\r\n  from public.matches\r\n  where id = p_match_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception ''Không tìm thấy trận đấu: %'', p_match_id;\r\n  end if;\r\n  if v_match.status <> ''PENDING'' then\r\n    raise exception\r\n      ''Không thể duyệt trận %. Trạng thái hiện tại: %. Chỉ trận PENDING mới được APPROVED'',\r\n      p_match_id, v_match.status;\r\n  end if;\r\n  if v_match.match_type = ''SELF_REPORTED'' then\r\n    raise exception ''SELF_REPORTED_HISTORICAL_ONLY'';\r\n  end if;\r\n\r\n  if v_match.match_type = ''TOURNAMENT'' then\r\n    if v_match.tournament_id is null or v_match.league_id is not null then\r\n      raise exception ''TOURNAMENT_REQUIRES_TOURNAMENT_ID_ONLY'';\r\n    end if;\r\n  elsif v_match.match_type = ''LEAGUE'' then\r\n    if v_match.league_id is null or v_match.tournament_id is not null then\r\n      raise exception ''LEAGUE_REQUIRES_LEAGUE_ID_ONLY'';\r\n    end if;\r\n  elsif v_match.match_type in (''CLUB_RATED'',''FRIENDLY_RATED'',''TRAINING'') then\r\n    if v_match.tournament_id is not null or v_match.league_id is not null then\r\n      raise exception ''STANDARD_MATCH_CANNOT_HAVE_COMPETITION_ID'';\r\n    end if;\r\n  else\r\n    raise exception ''MATCH_TYPE_NOT_APPROVABLE: %'', v_match.match_type;\r\n  end if;\r\n\r\n  select count(*),\r\n         count(*) filter (where team = ''A''),\r\n         count(*) filter (where team = ''B'')\r\n  into v_player_count, v_team_a_count, v_team_b_count\r\n  from public.match_players\r\n  where match_id = p_match_id;\r\n\r\n  if v_player_count <> 4 or v_team_a_count <> 2 or v_team_b_count <> 2 then\r\n    raise exception\r\n      ''Trận % không hợp lệ. Yêu cầu đúng 4 VĐV, Team A = 2, Team B = 2. Hiện tại: total=%, A=%, B=%'',\r\n      p_match_id, v_player_count, v_team_a_count, v_team_b_count;\r\n  end if;\r\n\r\n  if v_match.match_type = ''LEAGUE'' then\r\n    select count(*) into v_league_club_count\r\n    from public.match_players mp\r\n    join public.players p on p.id = mp.player_id\r\n    where mp.match_id = p_match_id\r\n      and p.player_type = ''CLUB''\r\n      and p.status = ''ACTIVE'';\r\n    if v_league_club_count <> 4 then\r\n      raise exception ''LEAGUE_REQUIRES_FOUR_ACTIVE_CLUB_PLAYERS'';\r\n    end if;\r\n  end if;\r\n\r\n  if v_match.team_a_score is null or v_match.team_b_score is null then\r\n    raise exception ''Trận % chưa có đầy đủ tỷ số'', p_match_id;\r\n  end if;\r\n  if v_match.team_a_score < 0 or v_match.team_b_score < 0 then\r\n    raise exception ''Tỷ số trận % không được âm'', p_match_id;\r\n  end if;\r\n  if v_match.score_mode not in (''POINTS'',''RESULT'') then\r\n    raise exception ''score_mode "%" không được hỗ trợ'', v_match.score_mode;\r\n  end if;\r\n  if v_match.score_mode = ''POINTS''\r\n     and (v_match.team_a_score + v_match.team_b_score) <= 0 then\r\n    raise exception ''Trận POINTS phải có tổng điểm lớn hơn 0'';\r\n  end if;\r\n  if v_match.score_mode = ''RESULT'' then\r\n    if v_match.team_a_score not in (0,1)\r\n       or v_match.team_b_score not in (0,1) then\r\n      raise exception ''Trận RESULT chỉ chấp nhận score 0 hoặc 1'';\r\n    end if;\r\n    if v_match.team_a_score = 0 and v_match.team_b_score = 0 then\r\n      raise exception\r\n        ''Trận RESULT 0-0 chưa có kết quả hoàn chỉnh và không thể APPROVE'';\r\n    end if;\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1 from public.rating_settings rs\r\n    where rs.algorithm_version = p_algorithm_version\r\n  ) then\r\n    raise exception ''Không tồn tại Rating algorithm version: %'', p_algorithm_version;\r\n  end if;\r\n\r\n  select count(*) into v_rule_count\r\n  from public.fund_rules fr\r\n  where fr.match_type = v_match.match_type\r\n    and fr.is_active = true\r\n    and fr.effective_from <= v_match.played_at::date\r\n    and (fr.effective_to is null or fr.effective_to >= v_match.played_at::date);\r\n  if v_rule_count > 1 then\r\n    raise exception\r\n      ''Có % Fund Rules bị chồng lấn cho match_type % tại ngày %. Không thể duyệt trận'',\r\n      v_rule_count, v_match.match_type, v_match.played_at::date;\r\n  end if;\r\n\r\n  perform set_config(''app.match_workflow'', ''APPROVE_MATCH'', true);\r\n  update public.matches\r\n  set status = ''APPROVED'',\r\n      invalid_reason = null,\r\n      opponent_confirmed_by = p_opponent_confirmed_by,\r\n      opponent_confirmed_at = case\r\n        when p_opponent_confirmed_by is null then null\r\n        else now()\r\n      end,\r\n      updated_at = now()\r\n  where id = p_match_id;\r\n  perform set_config(''app.match_workflow'', '''', true);\r\n\r\n  v_rating_result := public._rebuild_ratings_internal(\r\n    p_algorithm_version, p_actor_user_id\r\n  );\r\n  v_fund_result := public._generate_match_fund_internal(\r\n    p_match_id, p_actor_user_id\r\n  );\r\n  v_audit_action := case\r\n    when p_opponent_confirmed_by is null then ''APPROVE_MATCH''\r\n    else ''CONFIRM_MATCH_BY_OPPONENT''\r\n  end;\r\n\r\n  insert into public.audit_logs (\r\n    user_id, action, table_name, record_id,\r\n    old_data, new_data, reason, created_at\r\n  ) values (\r\n    p_actor_user_id,\r\n    v_audit_action,\r\n    ''matches'',\r\n    p_match_id,\r\n    jsonb_build_object(''status'', v_match.status),\r\n    jsonb_build_object(\r\n      ''status'', ''APPROVED'',\r\n      ''match_type'', v_match.match_type,\r\n      ''tournament_id'', v_match.tournament_id,\r\n      ''league_id'', v_match.league_id,\r\n      ''algorithm_version'', p_algorithm_version,\r\n      ''opponent_confirmed_by'', p_opponent_confirmed_by,\r\n      ''rating_result'', v_rating_result,\r\n      ''fund_result'', v_fund_result,\r\n      ''engine'', ''MATCH_APPROVAL_P1_2''\r\n    ),\r\n    case\r\n      when p_opponent_confirmed_by is null\r\n        then ''Duyệt trận theo Match Business Matrix P1 và xử lý Rating + Quỹ CLB''\r\n      else ''Đối thủ xác nhận kết quả và xử lý Rating + Quỹ CLB''\r\n    end,\r\n    now()\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    ''success'', true,\r\n    ''match_id'', p_match_id,\r\n    ''status_before'', v_match.status,\r\n    ''status_after'', ''APPROVED'',\r\n    ''match_type'', v_match.match_type,\r\n    ''tournament_id'', v_match.tournament_id,\r\n    ''league_id'', v_match.league_id,\r\n    ''algorithm_version'', p_algorithm_version,\r\n    ''opponent_confirmed_by'', p_opponent_confirmed_by,\r\n    ''rating'', v_rating_result,\r\n    ''fund'', v_fund_result\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public._generate_match_fund_internal(p_match_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    r_match record;\r\n    r_player record;\r\n\r\n    v_rule_id uuid;\r\n    v_rule_count integer;\r\n\r\n    v_amount_loss numeric;\r\n    v_amount_draw numeric;\r\n    v_amount_win numeric;\r\n\r\n    v_player_result text;\r\n    v_amount_due numeric;\r\n    v_reason text;\r\n\r\n    v_total_players integer;\r\n    v_team_a_players integer;\r\n    v_team_b_players integer;\r\n\r\n    v_created_count integer := 0;\r\n    v_existing_count integer := 0;\r\nbegin\r\n\r\n    -- =====================================================\r\n    -- 1. VALIDATE MATCH ID\r\n    -- =====================================================\r\n\r\n    if p_match_id is null then\r\n        raise exception\r\n            ''match_id không được để trống.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 2. LOAD MATCH\r\n    -- =====================================================\r\n\r\n    select\r\n        m.id,\r\n        m.played_at,\r\n        m.match_number,\r\n        m.match_type,\r\n        m.score_mode,\r\n        m.team_a_score,\r\n        m.team_b_score,\r\n        m.status\r\n    into r_match\r\n    from public.matches m\r\n    where m.id = p_match_id;\r\n\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy match %.'',\r\n            p_match_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 3. CHỈ APPROVED MATCH MỚI ĐƯỢC XỬ LÝ QUỸ\r\n    -- =====================================================\r\n\r\n    if r_match.status <> ''APPROVED'' then\r\n        raise exception\r\n            ''Match % chưa APPROVED. Status hiện tại: %.'',\r\n            p_match_id,\r\n            r_match.status;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 4. VALIDATE SCORE\r\n    -- =====================================================\r\n\r\n    if r_match.team_a_score is null\r\n       or r_match.team_b_score is null then\r\n        raise exception\r\n            ''Match % chưa có đầy đủ tỷ số.'',\r\n            p_match_id;\r\n    end if;\r\n\r\n\r\n    if r_match.team_a_score < 0\r\n       or r_match.team_b_score < 0 then\r\n        raise exception\r\n            ''Match % có tỷ số âm.'',\r\n            p_match_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 5. VALIDATE DOUBLES: ĐÚNG 4 NGƯỜI, 2 VS 2\r\n    -- =====================================================\r\n\r\n    select\r\n        count(*),\r\n        count(*) filter (where team = ''A''),\r\n        count(*) filter (where team = ''B'')\r\n    into\r\n        v_total_players,\r\n        v_team_a_players,\r\n        v_team_b_players\r\n    from public.match_players\r\n    where match_id = p_match_id;\r\n\r\n\r\n    if v_total_players <> 4\r\n       or v_team_a_players <> 2\r\n       or v_team_b_players <> 2 then\r\n        raise exception\r\n            ''Match % không hợp lệ: cần đúng 4 VĐV, Team A = 2, Team B = 2.'',\r\n            p_match_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 6. TÌM FUND RULE ÁP DỤNG\r\n    --\r\n    -- SEMANTICS:\r\n    -- 0 rule  = trận không phát sinh nghĩa vụ Quỹ\r\n    -- 1 rule  = áp dụng rule\r\n    -- >1 rule = lỗi cấu hình / rule chồng lấn\r\n    -- =====================================================\r\n\r\n    select count(*)\r\n    into v_rule_count\r\n    from public.fund_rules fr\r\n    where fr.match_type = r_match.match_type\r\n      and fr.is_active = true\r\n      and fr.effective_from <= r_match.played_at::date\r\n      and (\r\n            fr.effective_to is null\r\n            or fr.effective_to >= r_match.played_at::date\r\n          );\r\n\r\n\r\n    -- =====================================================\r\n    -- 7. KHÔNG CÓ FUND RULE\r\n    --\r\n    -- Đây KHÔNG phải lỗi.\r\n    -- Match vẫn hợp lệ và có thể APPROVED.\r\n    -- Không tạo fund_contributions.\r\n    -- =====================================================\r\n\r\n    if v_rule_count = 0 then\r\n\r\n        insert into public.audit_logs (\r\n            user_id,\r\n            action,\r\n            table_name,\r\n            record_id,\r\n            old_data,\r\n            new_data,\r\n            reason,\r\n            created_at\r\n        )\r\n        values (\r\n            p_actor_user_id,\r\n            ''GENERATE_MATCH_FUND'',\r\n            ''fund_contributions'',\r\n            p_match_id,\r\n            null,\r\n            jsonb_build_object(\r\n                ''match_id'', p_match_id,\r\n                ''match_type'', r_match.match_type,\r\n                ''fund_rule_id'', null,\r\n                ''fund_rule_found'', false,\r\n                ''fund_skipped'', true,\r\n                ''created_contributions'', 0,\r\n                ''existing_contributions'', 0,\r\n                ''engine'', ''FUND_V1_1''\r\n            ),\r\n            ''Trận đấu không có Fund Rule áp dụng; không phát sinh nghĩa vụ Quỹ CLB'',\r\n            now()\r\n        );\r\n\r\n\r\n        return jsonb_build_object(\r\n            ''success'', true,\r\n            ''match_id'', p_match_id,\r\n            ''fund_rule_id'', null,\r\n            ''fund_rule_found'', false,\r\n            ''fund_skipped'', true,\r\n            ''created_contributions'', 0,\r\n            ''existing_contributions'', 0\r\n        );\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 8. NHIỀU FUND RULE CÙNG HIỆU LỰC\r\n    -- =====================================================\r\n\r\n    if v_rule_count > 1 then\r\n        raise exception\r\n            ''Có % Fund Rules cùng hiệu lực cho match_type % tại ngày %. Cần xử lý rule bị chồng lấn.'',\r\n            v_rule_count,\r\n            r_match.match_type,\r\n            r_match.played_at::date;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 9. LOAD RULE DUY NHẤT\r\n    -- =====================================================\r\n\r\n    select\r\n        fr.id,\r\n        fr.amount_loss,\r\n        fr.amount_draw,\r\n        fr.amount_win\r\n    into\r\n        v_rule_id,\r\n        v_amount_loss,\r\n        v_amount_draw,\r\n        v_amount_win\r\n    from public.fund_rules fr\r\n    where fr.match_type = r_match.match_type\r\n      and fr.is_active = true\r\n      and fr.effective_from <= r_match.played_at::date\r\n      and (\r\n            fr.effective_to is null\r\n            or fr.effective_to >= r_match.played_at::date\r\n          );\r\n\r\n\r\n    -- =====================================================\r\n    -- 10. VALIDATE FUND AMOUNTS\r\n    -- =====================================================\r\n\r\n    if v_amount_loss is null\r\n       or v_amount_draw is null\r\n       or v_amount_win is null then\r\n        raise exception\r\n            ''Fund Rule % có amount NULL.'',\r\n            v_rule_id;\r\n    end if;\r\n\r\n\r\n    if v_amount_loss < 0\r\n       or v_amount_draw < 0\r\n       or v_amount_win < 0 then\r\n        raise exception\r\n            ''Fund Rule % có amount âm.'',\r\n            v_rule_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 11. XỬ LÝ TỪNG PLAYER\r\n    -- =====================================================\r\n\r\n    for r_player in\r\n        select\r\n            mp.player_id,\r\n            mp.team\r\n        from public.match_players mp\r\n        where mp.match_id = p_match_id\r\n        order by\r\n            mp.team,\r\n            mp.player_id\r\n    loop\r\n\r\n        -- DRAW\r\n        if r_match.team_a_score = r_match.team_b_score then\r\n\r\n            v_player_result := ''DRAW'';\r\n            v_amount_due := v_amount_draw;\r\n            v_reason := ''HOA'';\r\n\r\n        -- TEAM A\r\n        elsif r_player.team = ''A'' then\r\n\r\n            if r_match.team_a_score > r_match.team_b_score then\r\n                v_player_result := ''WIN'';\r\n                v_amount_due := v_amount_win;\r\n                v_reason := ''THANG'';\r\n            else\r\n                v_player_result := ''LOSS'';\r\n                v_amount_due := v_amount_loss;\r\n                v_reason := ''THUA'';\r\n            end if;\r\n\r\n        -- TEAM B\r\n        elsif r_player.team = ''B'' then\r\n\r\n            if r_match.team_b_score > r_match.team_a_score then\r\n                v_player_result := ''WIN'';\r\n                v_amount_due := v_amount_win;\r\n                v_reason := ''THANG'';\r\n            else\r\n                v_player_result := ''LOSS'';\r\n                v_amount_due := v_amount_loss;\r\n                v_reason := ''THUA'';\r\n            end if;\r\n\r\n        else\r\n\r\n            raise exception\r\n                ''Player % có team không hợp lệ trong match %.'',\r\n                r_player.player_id,\r\n                p_match_id;\r\n\r\n        end if;\r\n\r\n\r\n        -- =================================================\r\n        -- CHỈ TẠO NGHĨA VỤ KHI AMOUNT > 0\r\n        -- =================================================\r\n\r\n        if v_amount_due > 0 then\r\n\r\n            -- Giữ nguyên historical snapshot nếu đã có.\r\n            if exists (\r\n                select 1\r\n                from public.fund_contributions fc\r\n                where fc.match_id = p_match_id\r\n                  and fc.player_id = r_player.player_id\r\n            ) then\r\n\r\n                v_existing_count :=\r\n                    v_existing_count + 1;\r\n\r\n            else\r\n\r\n                insert into public.fund_contributions (\r\n                    match_id,\r\n                    player_id,\r\n                    reason,\r\n                    amount_due,\r\n                    status,\r\n                    created_at\r\n                )\r\n                values (\r\n                    p_match_id,\r\n                    r_player.player_id,\r\n                    v_reason,\r\n                    v_amount_due,\r\n                    ''CHUA_DONG'',\r\n                    now()\r\n                );\r\n\r\n                v_created_count :=\r\n                    v_created_count + 1;\r\n\r\n            end if;\r\n\r\n        end if;\r\n\r\n    end loop;\r\n\r\n\r\n    -- =====================================================\r\n    -- 12. AUDIT\r\n    -- =====================================================\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        p_actor_user_id,\r\n        ''GENERATE_MATCH_FUND'',\r\n        ''fund_contributions'',\r\n        p_match_id,\r\n        null,\r\n        jsonb_build_object(\r\n            ''match_id'', p_match_id,\r\n            ''match_type'', r_match.match_type,\r\n            ''fund_rule_id'', v_rule_id,\r\n            ''fund_rule_found'', true,\r\n            ''fund_skipped'', false,\r\n            ''amount_loss'', v_amount_loss,\r\n            ''amount_draw'', v_amount_draw,\r\n            ''amount_win'', v_amount_win,\r\n            ''created_contributions'', v_created_count,\r\n            ''existing_contributions'', v_existing_count,\r\n            ''engine'', ''FUND_V1_1''\r\n        ),\r\n        ''Sinh nghĩa vụ đóng Quỹ CLB từ trận đấu'',\r\n        now()\r\n    );\r\n\r\n\r\n    -- =====================================================\r\n    -- 13. RETURN\r\n    -- =====================================================\r\n\r\n    return jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', p_match_id,\r\n        ''fund_rule_id'', v_rule_id,\r\n        ''fund_rule_found'', true,\r\n        ''fund_skipped'', false,\r\n        ''created_contributions'', v_created_count,\r\n        ''existing_contributions'', v_existing_count\r\n    );\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public._get_active_rating_version()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_version text;\r\nbegin\r\n    select rs.algorithm_version\r\n    into v_version\r\n    from public.rating_settings rs\r\n    where rs.is_active = true\r\n    order by rs.id desc\r\n    limit 1;\r\n\r\n    if v_version is null then\r\n        raise exception ''ACTIVE_RATING_VERSION_NOT_CONFIGURED'';\r\n    end if;\r\n\r\n    return v_version;\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public._rebuild_ratings_internal(p_algorithm_version text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_initial_rating numeric;\r\n    v_min_rating numeric;\r\n    v_max_rating numeric;\r\n    v_k_factor numeric;\r\n    v_expected_sensitivity numeric;\r\n    v_provisional_matches integer;\r\n    v_stable_matches integer;\r\n    v_recency_half_life_days numeric;\r\n    v_recency_floor numeric;\r\n    v_delta_cap numeric;\r\n\r\n    v_latest_match_date date;\r\n\r\n    v_match_count integer := 0;\r\n    v_event_count integer := 0;\r\n    v_adjustment_count integer := 0;\r\n    v_adjustment_event_count integer := 0;\r\n\r\n    r_timeline record;\r\n\r\n    v_count_total integer;\r\n    v_count_a integer;\r\n    v_count_b integer;\r\n\r\n    v_team_a_rating numeric;\r\n    v_team_b_rating numeric;\r\n\r\n    v_match_weight numeric;\r\n    v_recency_weight numeric;\r\n    v_actual_a numeric;\r\n    v_actual_b numeric;\r\n\r\n    r_player record;\r\n\r\n    v_rating_before numeric;\r\n    v_team_rating numeric;\r\n    v_opponent_team_rating numeric;\r\n    v_expected_share numeric;\r\n    v_actual_share numeric;\r\n    v_performance_gap numeric;\r\n    v_previous_matches integer;\r\n    v_provisional_factor numeric;\r\n    v_rating_delta numeric;\r\n    v_rating_after numeric;\r\n\r\n    v_adjustment_applied_delta numeric;\r\n\r\nbegin\r\n\r\n    -- =====================================================\r\n    -- 1. CONCURRENCY PROTECTION\r\n    -- =====================================================\r\n\r\n    perform pg_advisory_xact_lock(726184501);\r\n\r\n\r\n    -- =====================================================\r\n    -- 2. VALIDATE ALGORITHM VERSION\r\n    -- =====================================================\r\n\r\n    if p_algorithm_version is null\r\n       or btrim(p_algorithm_version) = '''' then\r\n\r\n        raise exception\r\n            ''algorithm_version không được để trống.'';\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 3. LOAD SETTINGS\r\n    -- =====================================================\r\n\r\n    select\r\n        rs.initial_rating,\r\n        rs.min_rating,\r\n        rs.max_rating,\r\n        rs.k_factor,\r\n        rs.expected_sensitivity,\r\n        rs.provisional_matches,\r\n        rs.stable_matches,\r\n        rs.recency_half_life_days,\r\n        rs.recency_floor,\r\n        rs.rating_delta_cap\r\n    into\r\n        v_initial_rating,\r\n        v_min_rating,\r\n        v_max_rating,\r\n        v_k_factor,\r\n        v_expected_sensitivity,\r\n        v_provisional_matches,\r\n        v_stable_matches,\r\n        v_recency_half_life_days,\r\n        v_recency_floor,\r\n        v_delta_cap\r\n    from public.rating_settings rs\r\n    where rs.algorithm_version = p_algorithm_version\r\n    order by rs.id desc\r\n    limit 1;\r\n\r\n\r\n    if not found then\r\n\r\n        raise exception\r\n            ''Không tìm thấy rating_settings cho algorithm_version %.'',\r\n            p_algorithm_version;\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 4. VALIDATE SETTINGS\r\n    -- =====================================================\r\n\r\n    if v_initial_rating is null then\r\n        raise exception ''initial_rating không được NULL.'';\r\n    end if;\r\n\r\n\r\n    if v_min_rating is null\r\n       or v_max_rating is null\r\n       or v_min_rating >= v_max_rating then\r\n\r\n        raise exception\r\n            ''Cấu hình min_rating/max_rating không hợp lệ.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_initial_rating < v_min_rating\r\n       or v_initial_rating > v_max_rating then\r\n\r\n        raise exception\r\n            ''initial_rating phải nằm trong khoảng min_rating đến max_rating.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_k_factor is null\r\n       or v_k_factor <= 0 then\r\n\r\n        raise exception ''k_factor phải lớn hơn 0.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_expected_sensitivity is null\r\n       or v_expected_sensitivity <= 0 then\r\n\r\n        raise exception\r\n            ''expected_sensitivity phải lớn hơn 0.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_provisional_matches is null\r\n       or v_provisional_matches < 0 then\r\n\r\n        raise exception\r\n            ''provisional_matches không hợp lệ.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_stable_matches is null\r\n       or v_stable_matches < v_provisional_matches then\r\n\r\n        raise exception\r\n            ''stable_matches phải lớn hơn hoặc bằng provisional_matches.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_recency_half_life_days is null\r\n       or v_recency_half_life_days <= 0 then\r\n\r\n        raise exception\r\n            ''recency_half_life_days phải lớn hơn 0.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_recency_floor is null\r\n       or v_recency_floor < 0\r\n       or v_recency_floor > 1 then\r\n\r\n        raise exception\r\n            ''recency_floor phải nằm trong khoảng 0 đến 1.'';\r\n\r\n    end if;\r\n\r\n\r\n    if v_delta_cap is null\r\n       or v_delta_cap <= 0 then\r\n\r\n        raise exception\r\n            ''rating_delta_cap phải lớn hơn 0.'';\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 5. VALIDATE PLAYER INITIAL RATINGS\r\n    -- =====================================================\r\n\r\n    if exists (\r\n        select 1\r\n        from public.players p\r\n        where p.initial_rating < v_min_rating\r\n           or p.initial_rating > v_max_rating\r\n    ) then\r\n\r\n        raise exception\r\n            ''Có player.initial_rating nằm ngoài min/max của algorithm_version %. Rebuild bị hủy.'',\r\n            p_algorithm_version;\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 6. FIND LATEST RATED MATCH DATE\r\n    -- =====================================================\r\n\r\n    select max(m.played_at::date)\r\n    into v_latest_match_date\r\n    from public.matches m\r\n    join public.rating_match_weights mw\r\n        on mw.match_type = m.match_type\r\n    where m.status = ''APPROVED''\r\n      and mw.weight > 0;\r\n\r\n\r\n    -- =====================================================\r\n    -- 7. RESET PLAYERS\r\n    -- =====================================================\r\n\r\n    update public.players\r\n    set\r\n        current_rating = initial_rating,\r\n        updated_at = now()\r\n    where current_rating is distinct from initial_rating;\r\n\r\n\r\n    -- =====================================================\r\n    -- 8. DELETE DERIVED EVENTS FOR THIS VERSION\r\n    -- =====================================================\r\n    --\r\n    -- Chỉ xóa dữ liệu có thể rebuild.\r\n    -- KHÔNG xóa rating_adjustments source ledger.\r\n    --\r\n\r\n    delete from public.rating_events\r\n    where algorithm_version = p_algorithm_version;\r\n\r\n\r\n    delete from public.rating_adjustment_events\r\n    where algorithm_version = p_algorithm_version;\r\n\r\n\r\n    -- =====================================================\r\n    -- 9. REPLAY UNIFIED TIMELINE\r\n    -- =====================================================\r\n\r\n    for r_timeline in\r\n\r\n        select *\r\n        from (\r\n\r\n            -- MATCH\r\n            select\r\n                ''MATCH''::text as event_type,\r\n                m.played_at as event_time,\r\n                1::integer as event_type_order,\r\n\r\n                m.id as event_id,\r\n\r\n                m.id as match_id,\r\n                m.match_number as match_number,\r\n                m.match_type as match_type,\r\n                m.score_mode as score_mode,\r\n                m.team_a_score as team_a_score,\r\n                m.team_b_score as team_b_score,\r\n                mw.weight as configured_match_weight,\r\n\r\n                null::uuid as adjustment_id,\r\n                null::uuid as adjustment_player_id,\r\n                null::numeric as adjustment_amount,\r\n                null::bigint as replay_order\r\n\r\n            from public.matches m\r\n\r\n            join public.rating_match_weights mw\r\n                on mw.match_type = m.match_type\r\n\r\n            where m.status = ''APPROVED''\r\n              and mw.weight > 0\r\n\r\n\r\n            union all\r\n\r\n\r\n            -- ADJUSTMENT\r\n            select\r\n                ''ADJUSTMENT''::text as event_type,\r\n                ra.effective_at as event_time,\r\n                2::integer as event_type_order,\r\n\r\n                ra.id as event_id,\r\n\r\n                null::uuid as match_id,\r\n                null::integer as match_number,\r\n                null::text as match_type,\r\n                null::text as score_mode,\r\n                null::integer as team_a_score,\r\n                null::integer as team_b_score,\r\n                null::numeric as configured_match_weight,\r\n\r\n                ra.id as adjustment_id,\r\n                ra.player_id as adjustment_player_id,\r\n                ra.amount as adjustment_amount,\r\n                ra.replay_order as replay_order\r\n\r\n            from public.rating_adjustments ra\r\n\r\n        ) timeline\r\n\r\n        order by\r\n            event_time asc,\r\n            event_type_order asc,\r\n            match_number asc nulls last,\r\n            replay_order asc nulls last,\r\n            event_id asc\r\n\r\n    loop\r\n\r\n\r\n        -- =================================================\r\n        -- 9A. MATCH\r\n        -- =================================================\r\n\r\n        if r_timeline.event_type = ''MATCH'' then\r\n\r\n            v_match_weight :=\r\n                r_timeline.configured_match_weight;\r\n\r\n\r\n            if v_match_weight is null\r\n               or v_match_weight <= 0 then\r\n\r\n                raise exception\r\n                    ''Match % có match weight không hợp lệ.'',\r\n                    r_timeline.match_id;\r\n\r\n            end if;\r\n\r\n\r\n            -- Validate 4 players / 2 vs 2\r\n\r\n            select count(*)\r\n            into v_count_total\r\n            from public.match_players\r\n            where match_id = r_timeline.match_id;\r\n\r\n\r\n            select count(*)\r\n            into v_count_a\r\n            from public.match_players\r\n            where match_id = r_timeline.match_id\r\n              and team = ''A'';\r\n\r\n\r\n            select count(*)\r\n            into v_count_b\r\n            from public.match_players\r\n            where match_id = r_timeline.match_id\r\n              and team = ''B'';\r\n\r\n\r\n            if v_count_total <> 4\r\n               or v_count_a <> 2\r\n               or v_count_b <> 2 then\r\n\r\n                raise exception\r\n                    ''Match % không hợp lệ: cần đúng 4 VĐV, Team A = 2, Team B = 2.'',\r\n                    r_timeline.match_id;\r\n\r\n            end if;\r\n\r\n\r\n            -- Team A snapshot BEFORE\r\n\r\n            select avg(p.current_rating)\r\n            into v_team_a_rating\r\n            from public.match_players mp\r\n            join public.players p\r\n                on p.id = mp.player_id\r\n            where mp.match_id = r_timeline.match_id\r\n              and mp.team = ''A'';\r\n\r\n\r\n            -- Team B snapshot BEFORE\r\n\r\n            select avg(p.current_rating)\r\n            into v_team_b_rating\r\n            from public.match_players mp\r\n            join public.players p\r\n                on p.id = mp.player_id\r\n            where mp.match_id = r_timeline.match_id\r\n              and mp.team = ''B'';\r\n\r\n\r\n            if v_team_a_rating is null\r\n               or v_team_b_rating is null then\r\n\r\n                raise exception\r\n                    ''Không tính được Team Rating cho match %.'',\r\n                    r_timeline.match_id;\r\n\r\n            end if;\r\n\r\n\r\n            -- Recency\r\n\r\n            if v_latest_match_date is null then\r\n\r\n                v_recency_weight := 1.0;\r\n\r\n            else\r\n\r\n                v_recency_weight :=\r\n                    greatest(\r\n                        v_recency_floor,\r\n                        power(\r\n                            0.5,\r\n                            (\r\n                                greatest(\r\n                                    0,\r\n                                    v_latest_match_date\r\n                                    - r_timeline.event_time::date\r\n                                )::numeric\r\n                                /\r\n                                v_recency_half_life_days\r\n                            )\r\n                        )\r\n                    );\r\n\r\n            end if;\r\n\r\n\r\n            -- Actual performance\r\n\r\n            if r_timeline.score_mode = ''POINTS'' then\r\n\r\n                if r_timeline.team_a_score is null\r\n                   or r_timeline.team_b_score is null then\r\n\r\n                    raise exception\r\n                        ''Match % dùng POINTS nhưng score bị NULL.'',\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                if r_timeline.team_a_score < 0\r\n                   or r_timeline.team_b_score < 0 then\r\n\r\n                    raise exception\r\n                        ''Match % có score âm.'',\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                if (\r\n                    r_timeline.team_a_score\r\n                    +\r\n                    r_timeline.team_b_score\r\n                ) <= 0 then\r\n\r\n                    raise exception\r\n                        ''Match % dùng POINTS nhưng tổng điểm <= 0.'',\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                v_actual_a :=\r\n                    r_timeline.team_a_score::numeric\r\n                    /\r\n                    (\r\n                        r_timeline.team_a_score\r\n                        +\r\n                        r_timeline.team_b_score\r\n                    )::numeric;\r\n\r\n\r\n                v_actual_b :=\r\n                    r_timeline.team_b_score::numeric\r\n                    /\r\n                    (\r\n                        r_timeline.team_a_score\r\n                        +\r\n                        r_timeline.team_b_score\r\n                    )::numeric;\r\n\r\n\r\n            elsif r_timeline.score_mode = ''RESULT'' then\r\n\r\n                if r_timeline.team_a_score is null\r\n                   or r_timeline.team_b_score is null then\r\n\r\n                    raise exception\r\n                        ''Match % dùng RESULT nhưng score bị NULL.'',\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                if r_timeline.team_a_score < 0\r\n                   or r_timeline.team_b_score < 0 then\r\n\r\n                    raise exception\r\n                        ''Match % có score âm.'',\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                if r_timeline.team_a_score\r\n                   > r_timeline.team_b_score then\r\n\r\n                    v_actual_a := 1.0;\r\n                    v_actual_b := 0.0;\r\n\r\n                elsif r_timeline.team_a_score\r\n                      < r_timeline.team_b_score then\r\n\r\n                    v_actual_a := 0.0;\r\n                    v_actual_b := 1.0;\r\n\r\n                else\r\n\r\n                    v_actual_a := 0.5;\r\n                    v_actual_b := 0.5;\r\n\r\n                end if;\r\n\r\n\r\n            else\r\n\r\n                raise exception\r\n                    ''score_mode không hợp lệ tại match %: %'',\r\n                    r_timeline.match_id,\r\n                    r_timeline.score_mode;\r\n\r\n            end if;\r\n\r\n\r\n            -- Calculate all 4 players.\r\n            -- Không update current_rating cho tới khi cả\r\n            -- bốn rating_events đã được tạo.\r\n\r\n            for r_player in\r\n\r\n                select\r\n                    mp.player_id,\r\n                    mp.team,\r\n                    p.current_rating\r\n\r\n                from public.match_players mp\r\n\r\n                join public.players p\r\n                    on p.id = mp.player_id\r\n\r\n                where mp.match_id = r_timeline.match_id\r\n\r\n                order by\r\n                    mp.team asc,\r\n                    mp.player_id asc\r\n\r\n            loop\r\n\r\n                v_rating_before :=\r\n                    r_player.current_rating;\r\n\r\n\r\n                if r_player.team = ''A'' then\r\n\r\n                    v_team_rating :=\r\n                        v_team_a_rating;\r\n\r\n                    v_opponent_team_rating :=\r\n                        v_team_b_rating;\r\n\r\n                    v_actual_share :=\r\n                        v_actual_a;\r\n\r\n\r\n                elsif r_player.team = ''B'' then\r\n\r\n                    v_team_rating :=\r\n                        v_team_b_rating;\r\n\r\n                    v_opponent_team_rating :=\r\n                        v_team_a_rating;\r\n\r\n                    v_actual_share :=\r\n                        v_actual_b;\r\n\r\n\r\n                else\r\n\r\n                    raise exception\r\n                        ''Player % trong match % có team không hợp lệ.'',\r\n                        r_player.player_id,\r\n                        r_timeline.match_id;\r\n\r\n                end if;\r\n\r\n\r\n                v_expected_share :=\r\n                    1.0\r\n                    /\r\n                    (\r\n                        1.0\r\n                        +\r\n                        exp(\r\n                            (\r\n                                v_opponent_team_rating\r\n                                -\r\n                                v_team_rating\r\n                            )\r\n                            /\r\n                            v_expected_sensitivity\r\n                        )\r\n                    );\r\n\r\n\r\n                v_performance_gap :=\r\n                    v_actual_share\r\n                    -\r\n                    v_expected_share;\r\n\r\n\r\n                -- Chỉ MATCH events được tính vào provisional.\r\n\r\n                select count(*)\r\n                into v_previous_matches\r\n                from public.rating_events re\r\n                where re.player_id = r_player.player_id\r\n                  and re.algorithm_version =\r\n                      p_algorithm_version;\r\n\r\n\r\n                if v_previous_matches\r\n                   < v_provisional_matches then\r\n\r\n                    v_provisional_factor := 1.25;\r\n\r\n                elsif v_previous_matches\r\n                      < v_stable_matches then\r\n\r\n                    v_provisional_factor := 1.10;\r\n\r\n                else\r\n\r\n                    v_provisional_factor := 1.00;\r\n\r\n                end if;\r\n\r\n\r\n                v_rating_delta :=\r\n                    v_performance_gap\r\n                    *\r\n                    v_k_factor\r\n                    *\r\n                    v_match_weight\r\n                    *\r\n                    v_recency_weight\r\n                    *\r\n                    v_provisional_factor;\r\n\r\n\r\n                -- Match delta cap\r\n\r\n                v_rating_delta :=\r\n                    greatest(\r\n                        -v_delta_cap,\r\n                        least(\r\n                            v_delta_cap,\r\n                            v_rating_delta\r\n                        )\r\n                    );\r\n\r\n\r\n                v_rating_after :=\r\n                    greatest(\r\n                        v_min_rating,\r\n                        least(\r\n                            v_max_rating,\r\n                            v_rating_before\r\n                            +\r\n                            v_rating_delta\r\n                        )\r\n                    );\r\n\r\n\r\n                insert into public.rating_events (\r\n                    match_id,\r\n                    player_id,\r\n                    algorithm_version,\r\n                    rating_before,\r\n                    team_rating,\r\n                    opponent_team_rating,\r\n                    expected_share,\r\n                    actual_share,\r\n                    performance_gap,\r\n                    match_weight,\r\n                    recency_weight,\r\n                    provisional_factor,\r\n                    rating_delta,\r\n                    rating_after\r\n                )\r\n                values (\r\n                    r_timeline.match_id,\r\n                    r_player.player_id,\r\n                    p_algorithm_version,\r\n                    v_rating_before,\r\n                    v_team_rating,\r\n                    v_opponent_team_rating,\r\n                    v_expected_share,\r\n                    v_actual_share,\r\n                    v_performance_gap,\r\n                    v_match_weight,\r\n                    v_recency_weight,\r\n                    v_provisional_factor,\r\n                    v_rating_delta,\r\n                    v_rating_after\r\n                );\r\n\r\n\r\n                v_event_count :=\r\n                    v_event_count + 1;\r\n\r\n            end loop;\r\n\r\n\r\n            -- Sau khi đủ 4 events mới update players.\r\n\r\n            update public.players p\r\n            set\r\n                current_rating = re.rating_after,\r\n                updated_at = now()\r\n            from public.rating_events re\r\n            where re.match_id = r_timeline.match_id\r\n              and re.algorithm_version =\r\n                  p_algorithm_version\r\n              and re.player_id = p.id;\r\n\r\n\r\n            v_match_count :=\r\n                v_match_count + 1;\r\n\r\n\r\n        -- =================================================\r\n        -- 9B. ADJUSTMENT\r\n        -- =================================================\r\n\r\n        elsif r_timeline.event_type = ''ADJUSTMENT'' then\r\n\r\n\r\n            if r_timeline.adjustment_id is null then\r\n\r\n                raise exception\r\n                    ''Adjustment timeline có adjustment_id NULL.'';\r\n\r\n            end if;\r\n\r\n\r\n            if r_timeline.adjustment_player_id is null then\r\n\r\n                raise exception\r\n                    ''Adjustment % có player_id NULL.'',\r\n                    r_timeline.adjustment_id;\r\n\r\n            end if;\r\n\r\n\r\n            if r_timeline.adjustment_amount is null\r\n               or r_timeline.adjustment_amount = 0 then\r\n\r\n                raise exception\r\n                    ''Adjustment % có amount không hợp lệ.'',\r\n                    r_timeline.adjustment_id;\r\n\r\n            end if;\r\n\r\n\r\n            if r_timeline.replay_order is null then\r\n\r\n                raise exception\r\n                    ''Adjustment % không có replay_order.'',\r\n                    r_timeline.adjustment_id;\r\n\r\n            end if;\r\n\r\n\r\n            -- Rating tại đúng vị trí lịch sử của Adjustment.\r\n\r\n            select p.current_rating\r\n            into v_rating_before\r\n            from public.players p\r\n            where p.id =\r\n                r_timeline.adjustment_player_id;\r\n\r\n\r\n            if not found then\r\n\r\n                raise exception\r\n                    ''Không tìm thấy player % của adjustment %.'',\r\n                    r_timeline.adjustment_player_id,\r\n                    r_timeline.adjustment_id;\r\n\r\n            end if;\r\n\r\n\r\n            -- Requested amount có thể lớn hơn phần thực tế\r\n            -- áp dụng vì min/max clamp.\r\n\r\n            v_rating_after :=\r\n                greatest(\r\n                    v_min_rating,\r\n                    least(\r\n                        v_max_rating,\r\n                        v_rating_before\r\n                        +\r\n                        r_timeline.adjustment_amount\r\n                    )\r\n                );\r\n\r\n\r\n            -- Applied delta là thay đổi THỰC TẾ sau clamp.\r\n\r\n            v_adjustment_applied_delta :=\r\n                v_rating_after\r\n                -\r\n                v_rating_before;\r\n\r\n\r\n            -- Derived Adjustment Event.\r\n            --\r\n            -- Source rating_adjustments không bị sửa/xóa.\r\n\r\n            insert into public.rating_adjustment_events (\r\n                adjustment_id,\r\n                player_id,\r\n                algorithm_version,\r\n                rating_before,\r\n                requested_amount,\r\n                applied_delta,\r\n                rating_after\r\n            )\r\n            values (\r\n                r_timeline.adjustment_id,\r\n                r_timeline.adjustment_player_id,\r\n                p_algorithm_version,\r\n                v_rating_before,\r\n                r_timeline.adjustment_amount,\r\n                v_adjustment_applied_delta,\r\n                v_rating_after\r\n            );\r\n\r\n\r\n            -- Sau khi derived event được ghi thành công\r\n            -- mới cập nhật current projection.\r\n\r\n            update public.players\r\n            set\r\n                current_rating = v_rating_after,\r\n                updated_at = now()\r\n            where id =\r\n                r_timeline.adjustment_player_id;\r\n\r\n\r\n            v_adjustment_count :=\r\n                v_adjustment_count + 1;\r\n\r\n            v_adjustment_event_count :=\r\n                v_adjustment_event_count + 1;\r\n\r\n\r\n        else\r\n\r\n            raise exception\r\n                ''event_type không hợp lệ trong Rating timeline: %'',\r\n                r_timeline.event_type;\r\n\r\n        end if;\r\n\r\n    end loop;\r\n\r\n\r\n    -- =====================================================\r\n    -- 10. AUDIT REBUILD\r\n    -- =====================================================\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        p_actor_user_id,\r\n        ''REBUILD_RATINGS'',\r\n        ''rating_events'',\r\n        null,\r\n        null,\r\n        jsonb_build_object(\r\n            ''algorithm_version'',\r\n                p_algorithm_version,\r\n\r\n            ''matches_processed'',\r\n                v_match_count,\r\n\r\n            ''rating_events_created'',\r\n                v_event_count,\r\n\r\n            ''adjustments_processed'',\r\n                v_adjustment_count,\r\n\r\n            ''rating_adjustment_events_created'',\r\n                v_adjustment_event_count,\r\n\r\n            ''timeline_order'',\r\n                ''event_time ASC, MATCH before ADJUSTMENT, business order, id'',\r\n\r\n            ''engine'',\r\n                ''V1.1_INTERNAL_ADJUSTMENT_EVENTS''\r\n        ),\r\n        ''Rebuild toàn bộ Club Rating gồm Match và Rating Adjustment'',\r\n        now()\r\n    );\r\n\r\n\r\n    -- =====================================================\r\n    -- 11. RETURN\r\n    -- =====================================================\r\n\r\n    return jsonb_build_object(\r\n        ''success'',\r\n            true,\r\n\r\n        ''algorithm_version'',\r\n            p_algorithm_version,\r\n\r\n        ''matches_processed'',\r\n            v_match_count,\r\n\r\n        ''rating_events_created'',\r\n            v_event_count,\r\n\r\n        ''adjustments_processed'',\r\n            v_adjustment_count,\r\n\r\n        ''rating_adjustment_events_created'',\r\n            v_adjustment_event_count\r\n    );\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.confirm_match_by_opponent(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_actor uuid;\r\n  v_actor_player_id uuid;\r\n  v_match public.matches%rowtype;\r\n  v_creator_player_id uuid;\r\n  v_creator_team text;\r\n  v_actor_team text;\r\n  v_result jsonb;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  perform pg_advisory_xact_lock(726184501);\r\n\r\n  v_actor := auth.uid();\r\n\r\n  if v_actor is null then\r\n    raise exception ''AUTH_REQUIRED'';\r\n  end if;\r\n\r\n  select pr.player_id\r\n  into v_actor_player_id\r\n  from public.profiles pr\r\n  join public.players p\r\n    on p.id = pr.player_id\r\n  where pr.id = v_actor\r\n    and pr.role = ''MEMBER''\r\n    and pr.is_active = true\r\n    and p.player_type = ''CLUB''\r\n    and p.status = ''ACTIVE'';\r\n\r\n  if not found\r\n     or v_actor_player_id is null then\r\n    raise exception ''ACTIVE_MEMBER_PLAYER_REQUIRED'';\r\n  end if;\r\n\r\n  if p_match_id is null then\r\n    raise exception ''MATCH_ID_REQUIRED'';\r\n  end if;\r\n\r\n  select *\r\n  into v_match\r\n  from public.matches\r\n  where id = p_match_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception ''MATCH_NOT_FOUND'';\r\n  end if;\r\n\r\n  if v_match.status <> ''PENDING'' then\r\n    raise exception ''MATCH_NOT_PENDING'';\r\n  end if;\r\n\r\n  -- P1.2b hardening:\r\n  -- Once rejected, creator must edit/resubmit first.\r\n  if v_match.opponent_rejected_by is not null then\r\n    raise exception\r\n      ''MATCH_REJECTED_WAITING_CREATOR_RESUBMIT'';\r\n  end if;\r\n\r\n  if v_match.match_type not in (\r\n    ''CLUB_RATED'',\r\n    ''FRIENDLY_RATED''\r\n  ) then\r\n    raise exception\r\n      ''OPPONENT_CONFIRMATION_NOT_ALLOWED_FOR_MATCH_TYPE'';\r\n  end if;\r\n\r\n  if v_match.tournament_id is not null\r\n     or v_match.league_id is not null then\r\n    raise exception\r\n      ''OPPONENT_CONFIRMATION_REQUIRES_STANDARD_MATCH'';\r\n  end if;\r\n\r\n  if v_match.created_by = v_actor then\r\n    raise exception ''CREATOR_CANNOT_CONFIRM'';\r\n  end if;\r\n\r\n  select\r\n    (al.new_data ->> ''member_player_id'')::uuid\r\n  into v_creator_player_id\r\n  from public.audit_logs al\r\n  where al.record_id = p_match_id\r\n    and al.table_name = ''matches''\r\n    and al.action = ''CREATE_MY_PENDING_MATCH''\r\n    and al.user_id = v_match.created_by\r\n  order by al.created_at asc\r\n  limit 1;\r\n\r\n  if not found\r\n     or v_creator_player_id is null then\r\n    raise exception ''MEMBER_CREATED_MATCH_REQUIRED'';\r\n  end if;\r\n\r\n  select mp.team\r\n  into v_creator_team\r\n  from public.match_players mp\r\n  where mp.match_id = p_match_id\r\n    and mp.player_id = v_creator_player_id;\r\n\r\n  if not found then\r\n    raise exception ''CREATOR_PLAYER_NOT_IN_MATCH'';\r\n  end if;\r\n\r\n  select mp.team\r\n  into v_actor_team\r\n  from public.match_players mp\r\n  where mp.match_id = p_match_id\r\n    and mp.player_id = v_actor_player_id;\r\n\r\n  if not found then\r\n    raise exception ''CONFIRMER_NOT_IN_MATCH'';\r\n  end if;\r\n\r\n  if v_actor_team = v_creator_team then\r\n    raise exception ''CREATOR_TEAM_CANNOT_CONFIRM'';\r\n  end if;\r\n\r\n  v_result :=\r\n    public._approve_match_internal(\r\n      p_match_id,\r\n      public._get_active_rating_version(),\r\n      v_actor,\r\n      v_actor\r\n    );\r\n\r\n  return\r\n    v_result ||\r\n    jsonb_build_object(\r\n      ''confirmed_at'',\r\n      (\r\n        select opponent_confirmed_at\r\n        from public.matches\r\n        where id = p_match_id\r\n      )\r\n    );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.correct_rating_adjustment(p_adjustment_id uuid, p_reason text, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_actor_user_id uuid;\r\n\r\n    v_original_player_id uuid;\r\n    v_original_player_name text;\r\n    v_original_amount numeric;\r\n    v_original_reason text;\r\n    v_original_effective_at timestamptz;\r\n    v_original_replay_order bigint;\r\n\r\n    v_correction_id uuid;\r\n    v_correction_replay_order bigint;\r\n    v_correction_amount numeric;\r\n\r\n    v_rebuild_result jsonb;\r\n\r\n    v_rating_before numeric;\r\n    v_requested_amount numeric;\r\n    v_applied_delta numeric;\r\n    v_rating_after numeric;\r\n\r\nbegin\r\n\r\n    -- =====================================================\r\n    -- 1. AUTHENTICATION\r\n    -- =====================================================\r\n\r\n    v_actor_user_id := auth.uid();\r\n\r\n    if v_actor_user_id is null then\r\n        raise exception\r\n            ''Bạn chưa đăng nhập.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 2. AUTHORIZATION\r\n    -- ACTIVE ADMIN ONLY\r\n    -- =====================================================\r\n\r\n    if not exists (\r\n        select 1\r\n        from public.profiles pr\r\n        where pr.id = v_actor_user_id\r\n          and (pr.role = ''ADMIN'' OR (pr.role = ''MEMBER'' AND pr.can_adjust_rating IS TRUE))\r\n          and pr.is_active = true\r\n          and public.current_user_business_access_active()\r\n    ) then\r\n        raise exception\r\n            ''Bạn không có quyền correction Rating Adjustment.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 3. VALIDATE INPUT\r\n    -- =====================================================\r\n\r\n    if p_adjustment_id is null then\r\n        raise exception\r\n            ''adjustment_id không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_reason is null\r\n       or btrim(p_reason) = '''' then\r\n        raise exception\r\n            ''Lý do correction không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_algorithm_version is null\r\n       or btrim(p_algorithm_version) = '''' then\r\n        raise exception\r\n            ''algorithm_version không được để trống.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 4. SERIALIZE ALL RATING WRITES\r\n    -- =====================================================\r\n\r\n    perform pg_advisory_xact_lock(726184501);\r\n\r\n\r\n    -- =====================================================\r\n    -- 5. VALIDATE ALGORITHM VERSION\r\n    -- =====================================================\r\n\r\n    if not exists (\r\n        select 1\r\n        from public.rating_settings rs\r\n        where rs.algorithm_version = p_algorithm_version\r\n    ) then\r\n        raise exception\r\n            ''Không tồn tại algorithm_version %.'',\r\n            p_algorithm_version;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 6. LOAD + LOCK ORIGINAL ADJUSTMENT\r\n    -- =====================================================\r\n\r\n    select\r\n        ra.player_id,\r\n        p.full_name,\r\n        ra.amount,\r\n        ra.reason,\r\n        ra.effective_at,\r\n        ra.replay_order\r\n    into\r\n        v_original_player_id,\r\n        v_original_player_name,\r\n        v_original_amount,\r\n        v_original_reason,\r\n        v_original_effective_at,\r\n        v_original_replay_order\r\n\r\n    from public.rating_adjustments ra\r\n\r\n    join public.players p\r\n        on p.id = ra.player_id\r\n\r\n    where ra.id = p_adjustment_id\r\n\r\n    for update of ra;\r\n\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy Rating Adjustment %.'',\r\n            p_adjustment_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 7. PREVENT DUPLICATE DIRECT CORRECTION\r\n    -- =====================================================\r\n\r\n    if exists (\r\n        select 1\r\n        from public.rating_adjustments ra\r\n        where ra.correction_of_adjustment_id =\r\n            p_adjustment_id\r\n    ) then\r\n        raise exception\r\n            ''Rating Adjustment % đã có correction trực tiếp.'',\r\n            p_adjustment_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 8. CALCULATE REVERSAL AMOUNT\r\n    -- =====================================================\r\n\r\n    v_correction_amount :=\r\n        -v_original_amount;\r\n\r\n\r\n    if v_correction_amount = 0 then\r\n        raise exception\r\n            ''Correction amount không hợp lệ.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 9. INSERT APPEND-ONLY CORRECTION\r\n    -- =====================================================\r\n    --\r\n    -- effective_at GIỐNG adjustment gốc.\r\n    --\r\n    -- replay_order mới sẽ lớn hơn adjustment gốc,\r\n    -- nên trong unified timeline:\r\n    --\r\n    -- Original → Correction → các Match sau đó.\r\n    --\r\n    -- Không UPDATE/DELETE source ledger.\r\n    -- =====================================================\r\n\r\n    insert into public.rating_adjustments (\r\n        player_id,\r\n        amount,\r\n        reason,\r\n        created_by,\r\n        effective_at,\r\n        correction_of_adjustment_id\r\n    )\r\n    values (\r\n        v_original_player_id,\r\n        v_correction_amount,\r\n        btrim(p_reason),\r\n        v_actor_user_id,\r\n        v_original_effective_at,\r\n        p_adjustment_id\r\n    )\r\n    returning\r\n        id,\r\n        replay_order\r\n    into\r\n        v_correction_id,\r\n        v_correction_replay_order;\r\n\r\n\r\n    -- =====================================================\r\n    -- 10. DEFENSIVE ORDER CHECK\r\n    -- =====================================================\r\n\r\n    if v_correction_replay_order\r\n       <= v_original_replay_order then\r\n\r\n        raise exception\r\n            ''Correction replay_order phải lớn hơn original replay_order.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 11. REBUILD FULL HISTORICAL TIMELINE\r\n    -- =====================================================\r\n    --\r\n    -- Nếu rebuild lỗi:\r\n    -- INSERT correction cũng rollback.\r\n    -- =====================================================\r\n\r\n    v_rebuild_result :=\r\n        public._rebuild_ratings_internal(\r\n            p_algorithm_version,\r\n            v_actor_user_id\r\n        );\r\n\r\n\r\n    if coalesce(\r\n        (v_rebuild_result ->> ''success'')::boolean,\r\n        false\r\n    ) is not true then\r\n\r\n        raise exception\r\n            ''Rating rebuild sau correction không thành công.'';\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 12. READ DERIVED CORRECTION EVENT\r\n    -- =====================================================\r\n\r\n    select\r\n        rae.rating_before,\r\n        rae.requested_amount,\r\n        rae.applied_delta,\r\n        rae.rating_after\r\n    into\r\n        v_rating_before,\r\n        v_requested_amount,\r\n        v_applied_delta,\r\n        v_rating_after\r\n\r\n    from public.rating_adjustment_events rae\r\n\r\n    where rae.adjustment_id =\r\n            v_correction_id\r\n\r\n      and rae.algorithm_version =\r\n            p_algorithm_version;\r\n\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy derived event của correction sau rebuild.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 13. AUDIT BUSINESS ACTION\r\n    -- =====================================================\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        v_actor_user_id,\r\n\r\n        ''CORRECT_RATING_ADJUSTMENT'',\r\n\r\n        ''rating_adjustments'',\r\n\r\n        v_correction_id,\r\n\r\n        jsonb_build_object(\r\n            ''original_adjustment_id'',\r\n                p_adjustment_id,\r\n\r\n            ''player_id'',\r\n                v_original_player_id,\r\n\r\n            ''player_name'',\r\n                v_original_player_name,\r\n\r\n            ''original_amount'',\r\n                v_original_amount,\r\n\r\n            ''original_reason'',\r\n                v_original_reason,\r\n\r\n            ''original_effective_at'',\r\n                v_original_effective_at,\r\n\r\n            ''original_replay_order'',\r\n                v_original_replay_order\r\n        ),\r\n\r\n        jsonb_build_object(\r\n            ''correction_adjustment_id'',\r\n                v_correction_id,\r\n\r\n            ''correction_of_adjustment_id'',\r\n                p_adjustment_id,\r\n\r\n            ''player_id'',\r\n                v_original_player_id,\r\n\r\n            ''player_name'',\r\n                v_original_player_name,\r\n\r\n            ''requested_amount'',\r\n                v_requested_amount,\r\n\r\n            ''applied_delta'',\r\n                v_applied_delta,\r\n\r\n            ''rating_before'',\r\n                v_rating_before,\r\n\r\n            ''rating_after'',\r\n                v_rating_after,\r\n\r\n            ''effective_at'',\r\n                v_original_effective_at,\r\n\r\n            ''replay_order'',\r\n                v_correction_replay_order,\r\n\r\n            ''algorithm_version'',\r\n                p_algorithm_version\r\n        ),\r\n\r\n        btrim(p_reason),\r\n\r\n        now()\r\n    );\r\n\r\n\r\n    -- =====================================================\r\n    -- 14. RETURN\r\n    -- =====================================================\r\n\r\n    return jsonb_build_object(\r\n        ''success'',\r\n            true,\r\n\r\n        ''original_adjustment_id'',\r\n            p_adjustment_id,\r\n\r\n        ''correction_adjustment_id'',\r\n            v_correction_id,\r\n\r\n        ''correction_of_adjustment_id'',\r\n            p_adjustment_id,\r\n\r\n        ''player_id'',\r\n            v_original_player_id,\r\n\r\n        ''player_name'',\r\n            v_original_player_name,\r\n\r\n        ''original_amount'',\r\n            v_original_amount,\r\n\r\n        ''correction_amount'',\r\n            v_requested_amount,\r\n\r\n        ''effective_at'',\r\n            v_original_effective_at,\r\n\r\n        ''original_replay_order'',\r\n            v_original_replay_order,\r\n\r\n        ''correction_replay_order'',\r\n            v_correction_replay_order,\r\n\r\n        ''rating_before_correction'',\r\n            v_rating_before,\r\n\r\n        ''applied_delta'',\r\n            v_applied_delta,\r\n\r\n        ''rating_after_correction'',\r\n            v_rating_after,\r\n\r\n        ''reason'',\r\n            btrim(p_reason),\r\n\r\n        ''algorithm_version'',\r\n            p_algorithm_version,\r\n\r\n        ''rebuild'',\r\n            v_rebuild_result\r\n    );\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.create_my_pending_match(p_played_at timestamp with time zone, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_team_a_player_1 uuid, p_team_a_player_2 uuid, p_team_b_player_1 uuid, p_team_b_player_2 uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\nDECLARE\r\n    v_actor uuid;\r\n    v_profile_role text;\r\n    v_profile_active boolean;\r\n    v_my_player_id uuid;\r\n\r\n    v_match_id uuid;\r\n    v_match_number integer;\r\n\r\n    v_found_count integer;\r\n    v_active_count integer;\r\n    v_distinct_count integer;\r\nBEGIN\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n    PERFORM pg_advisory_xact_lock(726184501);\r\n\r\n    v_actor := auth.uid();\r\n\r\n    IF v_actor IS NULL THEN\r\n        RAISE EXCEPTION ''AUTH_REQUIRED'';\r\n    END IF;\r\n\r\n    SELECT\r\n        p.role,\r\n        p.is_active,\r\n        p.player_id\r\n    INTO\r\n        v_profile_role,\r\n        v_profile_active,\r\n        v_my_player_id\r\n    FROM public.profiles p\r\n    WHERE p.id = v_actor;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION ''PROFILE_NOT_FOUND'';\r\n    END IF;\r\n\r\n    IF coalesce(v_profile_active, false) = false THEN\r\n        RAISE EXCEPTION ''ACCOUNT_INACTIVE'';\r\n    END IF;\r\n\r\n    IF upper(coalesce(v_profile_role, '''')) <> ''MEMBER'' THEN\r\n        RAISE EXCEPTION ''MEMBER_ROLE_REQUIRED'';\r\n    END IF;\r\n\r\n    IF v_my_player_id IS NULL THEN\r\n        RAISE EXCEPTION ''PLAYER_LINK_REQUIRED'';\r\n    END IF;\r\n\r\n    IF NOT EXISTS (\r\n        SELECT 1\r\n        FROM public.players p\r\n        WHERE p.id = v_my_player_id\r\n          AND p.status = ''ACTIVE''\r\n          AND p.player_type = ''CLUB''\r\n    ) THEN\r\n        RAISE EXCEPTION ''MEMBER_PLAYER_INVALID'';\r\n    END IF;\r\n\r\n    IF p_played_at IS NULL THEN\r\n        RAISE EXCEPTION ''PLAYED_AT_REQUIRED'';\r\n    END IF;\r\n\r\n    IF p_match_type IS NULL\r\n       OR btrim(p_match_type) = '''' THEN\r\n        RAISE EXCEPTION ''MATCH_TYPE_REQUIRED'';\r\n    END IF;\r\n\r\n    -- P1: MEMBER không được tạo Competition / SELF_REPORTED.\r\n    IF p_match_type NOT IN (\r\n        ''CLUB_RATED'',\r\n        ''FRIENDLY_RATED'',\r\n        ''TRAINING''\r\n    ) THEN\r\n        RAISE EXCEPTION\r\n            ''MEMBER_MATCH_TYPE_NOT_ALLOWED: %'',\r\n            p_match_type;\r\n    END IF;\r\n\r\n    IF p_score_mode NOT IN (\r\n        ''POINTS'',\r\n        ''RESULT''\r\n    ) THEN\r\n        RAISE EXCEPTION\r\n            ''INVALID_SCORE_MODE: %'',\r\n            p_score_mode;\r\n    END IF;\r\n\r\n    IF p_team_a_score IS NULL\r\n       OR p_team_b_score IS NULL THEN\r\n        RAISE EXCEPTION ''SCORE_REQUIRED'';\r\n    END IF;\r\n\r\n    IF p_team_a_score < 0\r\n       OR p_team_b_score < 0 THEN\r\n        RAISE EXCEPTION ''NEGATIVE_SCORE_NOT_ALLOWED'';\r\n    END IF;\r\n\r\n    IF p_score_mode = ''POINTS''\r\n       AND (p_team_a_score + p_team_b_score) <= 0 THEN\r\n        RAISE EXCEPTION ''POINTS_SCORE_MUST_HAVE_RESULT'';\r\n    END IF;\r\n\r\n    IF p_score_mode = ''RESULT''\r\n       AND p_team_a_score = 0\r\n       AND p_team_b_score = 0 THEN\r\n        RAISE EXCEPTION ''RESULT_SCORE_MUST_HAVE_WINNER'';\r\n    END IF;\r\n\r\n    IF p_score_mode = ''RESULT''\r\n       AND (\r\n            p_team_a_score NOT IN (0, 1)\r\n            OR p_team_b_score NOT IN (0, 1)\r\n       ) THEN\r\n        RAISE EXCEPTION ''RESULT_SCORE_MUST_BE_0_OR_1'';\r\n    END IF;\r\n\r\n    IF p_team_a_player_1 IS NULL\r\n       OR p_team_a_player_2 IS NULL\r\n       OR p_team_b_player_1 IS NULL\r\n       OR p_team_b_player_2 IS NULL THEN\r\n        RAISE EXCEPTION ''FOUR_PLAYERS_REQUIRED'';\r\n    END IF;\r\n\r\n    SELECT count(DISTINCT x)\r\n    INTO v_distinct_count\r\n    FROM unnest(\r\n        ARRAY[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    ) AS t(x);\r\n\r\n    IF v_distinct_count <> 4 THEN\r\n        RAISE EXCEPTION ''PLAYERS_MUST_BE_DISTINCT'';\r\n    END IF;\r\n\r\n    IF NOT (\r\n        v_my_player_id = p_team_a_player_1\r\n        OR v_my_player_id = p_team_a_player_2\r\n        OR v_my_player_id = p_team_b_player_1\r\n        OR v_my_player_id = p_team_b_player_2\r\n    ) THEN\r\n        RAISE EXCEPTION ''MEMBER_MUST_PARTICIPATE'';\r\n    END IF;\r\n\r\n    SELECT count(*)\r\n    INTO v_found_count\r\n    FROM public.players p\r\n    WHERE p.id = ANY(\r\n        ARRAY[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    );\r\n\r\n    IF v_found_count <> 4 THEN\r\n        RAISE EXCEPTION ''PLAYER_NOT_FOUND'';\r\n    END IF;\r\n\r\n    SELECT count(*)\r\n    INTO v_active_count\r\n    FROM public.players p\r\n    WHERE p.id = ANY(\r\n        ARRAY[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    )\r\n      AND p.status = ''ACTIVE'';\r\n\r\n    IF v_active_count <> 4 THEN\r\n        RAISE EXCEPTION ''ALL_PLAYERS_MUST_BE_ACTIVE'';\r\n    END IF;\r\n\r\n    SELECT coalesce(max(m.match_number), 0) + 1\r\n    INTO v_match_number\r\n    FROM public.matches m\r\n    WHERE m.match_number IS NOT NULL;\r\n\r\n    INSERT INTO public.matches (\r\n        played_at,\r\n        match_number,\r\n        match_type,\r\n        score_mode,\r\n        team_a_score,\r\n        team_b_score,\r\n        status,\r\n        invalid_reason,\r\n        tournament_id,\r\n        league_id,\r\n        notes,\r\n        created_by,\r\n        created_at,\r\n        updated_at,\r\n        replaces_match_id\r\n    )\r\n    VALUES (\r\n        p_played_at,\r\n        v_match_number,\r\n        p_match_type,\r\n        p_score_mode,\r\n        p_team_a_score,\r\n        p_team_b_score,\r\n        ''PENDING'',\r\n        NULL,\r\n        NULL,\r\n        NULL,\r\n        nullif(btrim(p_notes), ''''),\r\n        v_actor,\r\n        now(),\r\n        now(),\r\n        NULL\r\n    )\r\n    RETURNING id\r\n    INTO v_match_id;\r\n\r\n    INSERT INTO public.match_players (\r\n        match_id,\r\n        player_id,\r\n        team,\r\n        partner_player_id,\r\n        created_at\r\n    )\r\n    VALUES\r\n    (\r\n        v_match_id,\r\n        p_team_a_player_1,\r\n        ''A'',\r\n        p_team_a_player_2,\r\n        now()\r\n    ),\r\n    (\r\n        v_match_id,\r\n        p_team_a_player_2,\r\n        ''A'',\r\n        p_team_a_player_1,\r\n        now()\r\n    ),\r\n    (\r\n        v_match_id,\r\n        p_team_b_player_1,\r\n        ''B'',\r\n        p_team_b_player_2,\r\n        now()\r\n    ),\r\n    (\r\n        v_match_id,\r\n        p_team_b_player_2,\r\n        ''B'',\r\n        p_team_b_player_1,\r\n        now()\r\n    );\r\n\r\n    INSERT INTO public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    VALUES (\r\n        v_actor,\r\n        ''CREATE_MY_PENDING_MATCH'',\r\n        ''matches'',\r\n        v_match_id,\r\n        NULL,\r\n        jsonb_build_object(\r\n            ''match_number'', v_match_number,\r\n            ''played_at'', p_played_at,\r\n            ''match_type'', p_match_type,\r\n            ''score_mode'', p_score_mode,\r\n            ''team_a_score'', p_team_a_score,\r\n            ''team_b_score'', p_team_b_score,\r\n            ''team_a'', jsonb_build_array(\r\n                p_team_a_player_1,\r\n                p_team_a_player_2\r\n            ),\r\n            ''team_b'', jsonb_build_array(\r\n                p_team_b_player_1,\r\n                p_team_b_player_2\r\n            ),\r\n            ''member_player_id'', v_my_player_id,\r\n            ''status'', ''PENDING'',\r\n            ''engine'', ''MEMBER_PENDING_MATCH_V1_P1''\r\n        ),\r\n        ''Thành viên tạo trận và gửi chờ duyệt'',\r\n        now()\r\n    );\r\n\r\n    RETURN jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', v_match_id,\r\n        ''match_number'', v_match_number,\r\n        ''status'', ''PENDING'',\r\n        ''created_by'', v_actor,\r\n        ''member_player_id'', v_my_player_id,\r\n        ''players_set'', 4\r\n    );\r\nEND;\r\n'
;
CREATE OR REPLACE FUNCTION public.create_pending_match(p_played_at timestamp with time zone, p_match_number integer DEFAULT NULL::integer, p_match_type text DEFAULT 'CLUB_RATED'::text, p_score_mode text DEFAULT 'POINTS'::text, p_team_a_score integer DEFAULT 0, p_team_b_score integer DEFAULT 0, p_tournament_id uuid DEFAULT NULL::uuid, p_league_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\nDECLARE\r\n    v_user_id uuid;\r\n    v_role text;\r\n    v_is_active boolean;\r\n\r\n    v_match_id uuid;\r\n    v_match_number integer;\r\n\r\n    v_tournament_status text;\r\n    v_league_status text;\r\nBEGIN\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n    PERFORM pg_advisory_xact_lock(726184501);\r\n\r\n    IF p_played_at IS NULL THEN\r\n        RAISE EXCEPTION ''played_at không được NULL'';\r\n    END IF;\r\n\r\n    IF p_match_type IS NULL\r\n       OR btrim(p_match_type) = '''' THEN\r\n        RAISE EXCEPTION ''match_type không được để trống'';\r\n    END IF;\r\n\r\n    IF p_score_mode IS NULL\r\n       OR btrim(p_score_mode) = '''' THEN\r\n        RAISE EXCEPTION ''score_mode không được để trống'';\r\n    END IF;\r\n\r\n    IF p_team_a_score IS NULL\r\n       OR p_team_b_score IS NULL THEN\r\n        RAISE EXCEPTION ''Tỷ số không được NULL'';\r\n    END IF;\r\n\r\n    IF p_team_a_score < 0\r\n       OR p_team_b_score < 0 THEN\r\n        RAISE EXCEPTION ''Tỷ số không được âm'';\r\n    END IF;\r\n\r\n    IF p_match_number IS NOT NULL\r\n       AND p_match_number <= 0 THEN\r\n        RAISE EXCEPTION ''Số trận phải lớn hơn 0'';\r\n    END IF;\r\n\r\n    v_user_id := auth.uid();\r\n\r\n    IF v_user_id IS NULL THEN\r\n        RAISE EXCEPTION\r\n            ''Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ'';\r\n    END IF;\r\n\r\n    SELECT role, is_active\r\n    INTO v_role, v_is_active\r\n    FROM public.profiles\r\n    WHERE id = v_user_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION ''Không tìm thấy hồ sơ người dùng'';\r\n    END IF;\r\n\r\n    IF coalesce(v_is_active, false) = false THEN\r\n        RAISE EXCEPTION ''Tài khoản đã bị vô hiệu hóa'';\r\n    END IF;\r\n\r\n    IF v_role <> ''ADMIN'' THEN\r\n        RAISE EXCEPTION ''Chỉ ADMIN mới được tạo trận đấu'';\r\n    END IF;\r\n\r\n    IF p_match_type NOT IN (\r\n        ''TOURNAMENT'',\r\n        ''LEAGUE'',\r\n        ''CLUB_RATED'',\r\n        ''FRIENDLY_RATED'',\r\n        ''TRAINING''\r\n    ) THEN\r\n        RAISE EXCEPTION\r\n            ''match_type không được phép tạo mới: %'',\r\n            p_match_type;\r\n    END IF;\r\n\r\n    IF p_score_mode NOT IN (''POINTS'', ''RESULT'') THEN\r\n        RAISE EXCEPTION\r\n            ''score_mode không hợp lệ: %'',\r\n            p_score_mode;\r\n    END IF;\r\n\r\n    IF p_score_mode = ''RESULT''\r\n       AND (\r\n            p_team_a_score NOT IN (0, 1)\r\n            OR p_team_b_score NOT IN (0, 1)\r\n       ) THEN\r\n        RAISE EXCEPTION\r\n            ''Trận RESULT chỉ chấp nhận score 0 hoặc 1'';\r\n    END IF;\r\n\r\n    IF p_match_type = ''TOURNAMENT'' THEN\r\n\r\n        IF p_tournament_id IS NULL\r\n           OR p_league_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''TOURNAMENT_REQUIRES_TOURNAMENT_ID_ONLY'';\r\n        END IF;\r\n\r\n        SELECT t.status\r\n        INTO v_tournament_status\r\n        FROM public.tournaments t\r\n        WHERE t.id = p_tournament_id\r\n        FOR SHARE;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION\r\n                ''Không tìm thấy giải đấu: %'',\r\n                p_tournament_id;\r\n        END IF;\r\n\r\n        IF v_tournament_status NOT IN (\r\n            ''DU_KIEN'',\r\n            ''MO_DANG_KY'',\r\n            ''DANG_DIEN_RA''\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                ''Không thể gắn trận mới vào giải có trạng thái %'',\r\n                v_tournament_status;\r\n        END IF;\r\n\r\n    ELSIF p_match_type = ''LEAGUE'' THEN\r\n\r\n        IF p_league_id IS NULL\r\n           OR p_tournament_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_REQUIRES_LEAGUE_ID_ONLY'';\r\n        END IF;\r\n\r\n        SELECT l.status\r\n        INTO v_league_status\r\n        FROM public.leagues l\r\n        WHERE l.id = p_league_id\r\n        FOR SHARE;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_NOT_FOUND: %'',\r\n                p_league_id;\r\n        END IF;\r\n\r\n        IF v_league_status NOT IN (\r\n            ''DU_KIEN'',\r\n            ''DANG_DIEN_RA''\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_STATUS_NOT_ATTACHABLE: %'',\r\n                v_league_status;\r\n        END IF;\r\n\r\n    ELSE\r\n\r\n        IF p_tournament_id IS NOT NULL\r\n           OR p_league_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''STANDARD_MATCH_CANNOT_HAVE_COMPETITION_ID'';\r\n        END IF;\r\n\r\n    END IF;\r\n\r\n    IF p_match_number IS NULL THEN\r\n        SELECT coalesce(max(m.match_number), 0) + 1\r\n        INTO v_match_number\r\n        FROM public.matches m\r\n        WHERE m.match_number IS NOT NULL;\r\n    ELSE\r\n        v_match_number := p_match_number;\r\n    END IF;\r\n\r\n    INSERT INTO public.matches (\r\n        played_at,\r\n        match_number,\r\n        match_type,\r\n        score_mode,\r\n        team_a_score,\r\n        team_b_score,\r\n        status,\r\n        invalid_reason,\r\n        tournament_id,\r\n        league_id,\r\n        notes,\r\n        created_by,\r\n        created_at,\r\n        updated_at,\r\n        replaces_match_id\r\n    )\r\n    VALUES (\r\n        p_played_at,\r\n        v_match_number,\r\n        p_match_type,\r\n        p_score_mode,\r\n        p_team_a_score,\r\n        p_team_b_score,\r\n        ''PENDING'',\r\n        NULL,\r\n        p_tournament_id,\r\n        p_league_id,\r\n        nullif(btrim(p_notes), ''''),\r\n        v_user_id,\r\n        now(),\r\n        now(),\r\n        NULL\r\n    )\r\n    RETURNING id INTO v_match_id;\r\n\r\n    INSERT INTO public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    VALUES (\r\n        v_user_id,\r\n        ''CREATE_PENDING_MATCH'',\r\n        ''matches'',\r\n        v_match_id,\r\n        NULL,\r\n        jsonb_build_object(\r\n            ''played_at'', p_played_at,\r\n            ''match_number'', v_match_number,\r\n            ''match_type'', p_match_type,\r\n            ''score_mode'', p_score_mode,\r\n            ''team_a_score'', p_team_a_score,\r\n            ''team_b_score'', p_team_b_score,\r\n            ''status'', ''PENDING'',\r\n            ''tournament_id'', p_tournament_id,\r\n            ''league_id'', p_league_id,\r\n            ''notes'', nullif(btrim(p_notes), ''''),\r\n            ''created_by'', v_user_id,\r\n            ''engine'', ''CREATE_PENDING_MATCH_P1''\r\n        ),\r\n        ''Tạo trận PENDING mới'',\r\n        now()\r\n    );\r\n\r\n    RETURN jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', v_match_id,\r\n        ''status'', ''PENDING'',\r\n        ''played_at'', p_played_at,\r\n        ''match_number'', v_match_number,\r\n        ''match_type'', p_match_type,\r\n        ''score_mode'', p_score_mode,\r\n        ''team_a_score'', p_team_a_score,\r\n        ''team_b_score'', p_team_b_score,\r\n        ''tournament_id'', p_tournament_id,\r\n        ''league_id'', p_league_id,\r\n        ''notes'', nullif(btrim(p_notes), '''')\r\n    );\r\nEND;\r\n'
;
CREATE OR REPLACE FUNCTION public.current_user_business_access_active()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\n    SELECT EXISTS (\r\n        SELECT 1\r\n        FROM public.profiles p\r\n        WHERE p.id = auth.uid()\r\n          AND p.is_active IS TRUE\r\n          AND p.membership_status = ''APPROVED''\r\n          AND p.must_change_password IS NOT TRUE\r\n    );\r\n'
;
CREATE OR REPLACE FUNCTION public.guard_match_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_workflow text;\r\nbegin\r\n  v_workflow := current_setting(''app.match_workflow'', true);\r\n\r\n  if tg_op = ''INSERT'' then\r\n    if new.status <> ''PENDING'' then\r\n      raise exception ''Match mới bắt buộc phải ở trạng thái PENDING'';\r\n    end if;\r\n    if new.invalid_reason is not null then\r\n      raise exception ''Match PENDING mới không được có invalid_reason'';\r\n    end if;\r\n    if new.opponent_confirmed_by is not null\r\n       or new.opponent_confirmed_at is not null then\r\n      raise exception ''Match PENDING mới không được có opponent confirmation'';\r\n    end if;\r\n    return new;\r\n  end if;\r\n\r\n  if tg_op = ''DELETE'' then\r\n    if old.status <> ''PENDING'' then\r\n      raise exception\r\n        ''Không được xóa match có trạng thái %. Chỉ PENDING mới được xóa'',\r\n        old.status;\r\n    end if;\r\n    return old;\r\n  end if;\r\n\r\n  if old.status = ''PENDING'' then\r\n    if new.id is distinct from old.id then\r\n      raise exception ''Không được thay đổi id của match PENDING'';\r\n    end if;\r\n    if new.created_by is distinct from old.created_by then\r\n      raise exception ''Không được thay đổi created_by của match PENDING'';\r\n    end if;\r\n    if new.created_at is distinct from old.created_at then\r\n      raise exception ''Không được thay đổi created_at của match PENDING'';\r\n    end if;\r\n    if new.replaces_match_id is distinct from old.replaces_match_id then\r\n      raise exception ''Không được thay đổi replaces_match_id của match PENDING'';\r\n    end if;\r\n\r\n    if new.status = ''PENDING'' then\r\n      if new.invalid_reason is distinct from old.invalid_reason then\r\n        raise exception\r\n          ''Không được thay đổi invalid_reason trực tiếp khi match đang PENDING'';\r\n      end if;\r\n      if new.opponent_confirmed_by is distinct from old.opponent_confirmed_by\r\n         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then\r\n        raise exception\r\n          ''Không được ghi opponent confirmation khi match vẫn PENDING'';\r\n      end if;\r\n      return new;\r\n    end if;\r\n\r\n    if new.status = ''APPROVED''\r\n       and v_workflow = ''APPROVE_MATCH'' then\r\n      if new.id is distinct from old.id\r\n         or new.played_at is distinct from old.played_at\r\n         or new.match_number is distinct from old.match_number\r\n         or new.match_type is distinct from old.match_type\r\n         or new.score_mode is distinct from old.score_mode\r\n         or new.team_a_score is distinct from old.team_a_score\r\n         or new.team_b_score is distinct from old.team_b_score\r\n         or new.tournament_id is distinct from old.tournament_id\r\n         or new.league_id is distinct from old.league_id\r\n         or new.notes is distinct from old.notes\r\n         or new.created_by is distinct from old.created_by\r\n         or new.created_at is distinct from old.created_at\r\n         or new.replaces_match_id is distinct from old.replaces_match_id then\r\n        raise exception\r\n          ''APPROVE không được đồng thời thay đổi dữ liệu nguồn của match PENDING'';\r\n      end if;\r\n      return new;\r\n    end if;\r\n\r\n    if new.status = ''INVALID''\r\n       and v_workflow = ''REJECT_MATCH'' then\r\n      if new.id is distinct from old.id\r\n         or new.played_at is distinct from old.played_at\r\n         or new.match_number is distinct from old.match_number\r\n         or new.match_type is distinct from old.match_type\r\n         or new.score_mode is distinct from old.score_mode\r\n         or new.team_a_score is distinct from old.team_a_score\r\n         or new.team_b_score is distinct from old.team_b_score\r\n         or new.tournament_id is distinct from old.tournament_id\r\n         or new.league_id is distinct from old.league_id\r\n         or new.notes is distinct from old.notes\r\n         or new.created_by is distinct from old.created_by\r\n         or new.created_at is distinct from old.created_at\r\n         or new.replaces_match_id is distinct from old.replaces_match_id\r\n         or new.opponent_confirmed_by is distinct from old.opponent_confirmed_by\r\n         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then\r\n        raise exception\r\n          ''REJECT không được đồng thời thay đổi dữ liệu nguồn của match PENDING'';\r\n      end if;\r\n      if new.invalid_reason is null or btrim(new.invalid_reason) = '''' then\r\n        raise exception ''REJECT bắt buộc phải có lý do'';\r\n      end if;\r\n      return new;\r\n    end if;\r\n\r\n    raise exception\r\n      ''Không được chuyển match từ PENDING sang % bằng UPDATE trực tiếp'',\r\n      new.status;\r\n  end if;\r\n\r\n  if old.status = ''APPROVED'' then\r\n    if new.status = ''VOIDED''\r\n       and v_workflow = ''VOID_MATCH'' then\r\n      if new.id is distinct from old.id\r\n         or new.played_at is distinct from old.played_at\r\n         or new.match_number is distinct from old.match_number\r\n         or new.match_type is distinct from old.match_type\r\n         or new.score_mode is distinct from old.score_mode\r\n         or new.team_a_score is distinct from old.team_a_score\r\n         or new.team_b_score is distinct from old.team_b_score\r\n         or new.tournament_id is distinct from old.tournament_id\r\n         or new.league_id is distinct from old.league_id\r\n         or new.notes is distinct from old.notes\r\n         or new.created_by is distinct from old.created_by\r\n         or new.created_at is distinct from old.created_at\r\n         or new.replaces_match_id is distinct from old.replaces_match_id\r\n         or new.opponent_confirmed_by is distinct from old.opponent_confirmed_by\r\n         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then\r\n        raise exception\r\n          ''VOID không được thay đổi dữ liệu nguồn của match APPROVED'';\r\n      end if;\r\n      return new;\r\n    end if;\r\n    raise exception\r\n      ''Match APPROVED là bất biến. Hãy VOID rồi tạo replacement'';\r\n  end if;\r\n\r\n  if old.status = ''VOIDED'' then\r\n    raise exception\r\n      ''Match VOIDED là lịch sử bất biến và không được sửa trực tiếp'';\r\n  end if;\r\n  if old.status = ''INVALID'' then\r\n    raise exception\r\n      ''Match INVALID là lịch sử bất biến và không được sửa trực tiếp'';\r\n  end if;\r\n  raise exception ''Trạng thái match không được hỗ trợ: %'', old.status;\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.guard_match_player_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_match_id uuid;\r\n    v_status text;\r\nbegin\r\n\r\n    if tg_op = ''DELETE'' then\r\n        v_match_id := old.match_id;\r\n    else\r\n        v_match_id := new.match_id;\r\n    end if;\r\n\r\n\r\n    if v_match_id is null then\r\n        raise exception\r\n            ''match_id không được NULL'';\r\n    end if;\r\n\r\n\r\n    select m.status\r\n    into v_status\r\n    from public.matches m\r\n    where m.id = v_match_id;\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy match %'',\r\n            v_match_id;\r\n    end if;\r\n\r\n\r\n    if v_status <> ''PENDING'' then\r\n        raise exception\r\n            ''Không được thay đổi match_players khi match đang ở trạng thái %. Chỉ PENDING được chỉnh sửa'',\r\n            v_status;\r\n    end if;\r\n\r\n\r\n    -- Không cho UPDATE chuyển một match_player\r\n    -- từ match này sang match khác.\r\n    if tg_op = ''UPDATE''\r\n       and new.match_id is distinct from old.match_id then\r\n\r\n        raise exception\r\n            ''Không được chuyển match_player sang match khác bằng UPDATE'';\r\n\r\n    end if;\r\n\r\n\r\n    if tg_op = ''DELETE'' then\r\n        return old;\r\n    end if;\r\n\r\n    return new;\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.record_rating_adjustment(p_request_id uuid, p_player_id uuid, p_amount numeric, p_reason text, p_effective_at timestamp with time zone, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n\r\n    v_actor_user_id uuid;\r\n\r\n    v_player_name text;\r\n    v_player_status text;\r\n\r\n    v_adjustment_id uuid;\r\n    v_replay_order bigint;\r\n\r\n    v_existing_player_id uuid;\r\n    v_existing_amount numeric;\r\n    v_existing_reason text;\r\n    v_existing_effective_at timestamptz;\r\n    v_existing_created_by uuid;\r\n    v_existing_algorithm_version text;\r\n    v_existing_correction_of uuid;\r\n\r\n    v_rebuild_result jsonb;\r\n\r\n    v_rating_before numeric;\r\n    v_requested_amount numeric;\r\n    v_applied_delta numeric;\r\n    v_rating_after numeric;\r\n\r\nbegin\r\n\r\n    -- =====================================================\r\n    -- 1. AUTHENTICATION\r\n    -- =====================================================\r\n\r\n    v_actor_user_id := auth.uid();\r\n\r\n    if v_actor_user_id is null then\r\n        raise exception\r\n            ''Bạn chưa đăng nhập.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 2. AUTHORIZATION: ACTIVE ADMIN ONLY\r\n    -- =====================================================\r\n\r\n    if not exists (\r\n        select 1\r\n        from public.profiles pr\r\n        where pr.id = v_actor_user_id\r\n          and (pr.role = ''ADMIN'' OR (pr.role = ''MEMBER'' AND pr.can_adjust_rating IS TRUE))\r\n          and pr.is_active = true\r\n          and public.current_user_business_access_active()\r\n    ) then\r\n        raise exception\r\n            ''Bạn không có quyền thực hiện Rating Adjustment.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 3. VALIDATE INPUT\r\n    -- =====================================================\r\n\r\n    if p_request_id is null then\r\n        raise exception\r\n            ''request_id không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_player_id is null then\r\n        raise exception\r\n            ''player_id không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_amount is null\r\n       or p_amount = 0\r\n       or p_amount::text IN (''NaN'',''Infinity'',''-Infinity'') then\r\n        raise exception\r\n            ''Adjustment amount phải khác 0.'';\r\n    end if;\r\n\r\n\r\n    if p_reason is null\r\n       or btrim(p_reason) = '''' then\r\n        raise exception\r\n            ''Lý do Adjustment không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_effective_at is null then\r\n        raise exception\r\n            ''effective_at không được để trống.'';\r\n    end if;\r\n\r\n\r\n    if p_algorithm_version is null\r\n       or btrim(p_algorithm_version) = '''' then\r\n        raise exception\r\n            ''algorithm_version không được để trống.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 4. SERIALIZE RATING WRITES\r\n    -- =====================================================\r\n\r\n    perform pg_advisory_xact_lock(726184501);\r\n\r\n\r\n    -- =====================================================\r\n    -- 5. IDEMPOTENCY LOOKUP\r\n    -- =====================================================\r\n    --\r\n    -- Cùng request_id:\r\n    --\r\n    --   Payload giống hệt\r\n    --       -> trả lại Adjustment đã tồn tại\r\n    --       -> KHÔNG INSERT\r\n    --       -> KHÔNG REBUILD\r\n    --\r\n    --   Payload khác\r\n    --       -> reject IDP_KEY_REUSE\r\n    --\r\n    -- Advisory lock + UNIQUE(request_id) là hai lớp bảo vệ.\r\n    -- =====================================================\r\n\r\n    select\r\n        ra.id,\r\n        ra.replay_order,\r\n        ra.player_id,\r\n        ra.amount,\r\n        ra.reason,\r\n        ra.effective_at,\r\n        ra.created_by,\r\n        ra.request_algorithm_version,\r\n        ra.correction_of_adjustment_id\r\n    into\r\n        v_adjustment_id,\r\n        v_replay_order,\r\n        v_existing_player_id,\r\n        v_existing_amount,\r\n        v_existing_reason,\r\n        v_existing_effective_at,\r\n        v_existing_created_by,\r\n        v_existing_algorithm_version,\r\n        v_existing_correction_of\r\n    from public.rating_adjustments ra\r\n    where ra.request_id = p_request_id;\r\n\r\n\r\n    if found then\r\n\r\n        -- -------------------------------------------------\r\n        -- request_id này phải thuộc đúng ADMIN đã tạo request\r\n        -- -------------------------------------------------\r\n\r\n        if v_existing_created_by is distinct from v_actor_user_id then\r\n            raise exception\r\n                ''IDP_KEY_REUSE: request_id đã được sử dụng bởi một user khác.'';\r\n        end if;\r\n\r\n\r\n        -- -------------------------------------------------\r\n        -- record_rating_adjustment() chỉ tạo Adjustment gốc,\r\n        -- không được trỏ đến correction row.\r\n        -- -------------------------------------------------\r\n\r\n        if v_existing_correction_of is not null then\r\n            raise exception\r\n                ''IDP_KEY_REUSE: request_id đang trỏ đến một Correction Adjustment.'';\r\n        end if;\r\n\r\n\r\n        -- -------------------------------------------------\r\n        -- Validate exact logical payload\r\n        -- -------------------------------------------------\r\n\r\n        if v_existing_player_id is distinct from p_player_id\r\n           or v_existing_amount is distinct from p_amount\r\n           or v_existing_reason is distinct from btrim(p_reason)\r\n           or v_existing_effective_at is distinct from p_effective_at\r\n           or v_existing_algorithm_version is distinct from btrim(p_algorithm_version)\r\n        then\r\n            raise exception\r\n                ''IDP_KEY_REUSE: cùng request_id nhưng payload khác request ban đầu.'';\r\n        end if;\r\n\r\n\r\n        -- -------------------------------------------------\r\n        -- Read current derived event.\r\n        --\r\n        -- Không rebuild.\r\n        -- Không tạo source adjustment mới.\r\n        -- -------------------------------------------------\r\n\r\n        select\r\n            rae.rating_before,\r\n            rae.requested_amount,\r\n            rae.applied_delta,\r\n            rae.rating_after\r\n        into\r\n            v_rating_before,\r\n            v_requested_amount,\r\n            v_applied_delta,\r\n            v_rating_after\r\n        from public.rating_adjustment_events rae\r\n        where rae.adjustment_id = v_adjustment_id\r\n          and rae.algorithm_version = v_existing_algorithm_version;\r\n\r\n\r\n        if not found then\r\n            raise exception\r\n                ''IDEMPOTENCY_STATE_ERROR: Adjustment tồn tại nhưng không tìm thấy derived Rating Adjustment Event.'';\r\n        end if;\r\n\r\n\r\n        select\r\n            p.full_name,\r\n            p.status\r\n        into\r\n            v_player_name,\r\n            v_player_status\r\n        from public.players p\r\n        where p.id = v_existing_player_id;\r\n\r\n\r\n        if not found then\r\n            raise exception\r\n                ''IDEMPOTENCY_STATE_ERROR: Không tìm thấy VĐV của Adjustment đã tồn tại.'';\r\n        end if;\r\n\r\n\r\n        return jsonb_build_object(\r\n            ''success'',\r\n                true,\r\n\r\n            ''idempotent_replay'',\r\n                true,\r\n\r\n            ''request_id'',\r\n                p_request_id,\r\n\r\n            ''adjustment_id'',\r\n                v_adjustment_id,\r\n\r\n            ''replay_order'',\r\n                v_replay_order,\r\n\r\n            ''player_id'',\r\n                v_existing_player_id,\r\n\r\n            ''player_name'',\r\n                v_player_name,\r\n\r\n            ''player_status'',\r\n                v_player_status,\r\n\r\n            ''effective_at'',\r\n                v_existing_effective_at,\r\n\r\n            ''reason'',\r\n                v_existing_reason,\r\n\r\n            ''algorithm_version'',\r\n                v_existing_algorithm_version,\r\n\r\n            ''rating_before'',\r\n                v_rating_before,\r\n\r\n            ''requested_amount'',\r\n                v_requested_amount,\r\n\r\n            ''applied_delta'',\r\n                v_applied_delta,\r\n\r\n            ''rating_after'',\r\n                v_rating_after,\r\n\r\n            ''rebuild'',\r\n                jsonb_build_object(\r\n                    ''skipped'',\r\n                        true,\r\n\r\n                    ''reason'',\r\n                        ''IDEMPOTENT_REPLAY''\r\n                )\r\n        );\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 6. VALIDATE ALGORITHM VERSION FOR NEW REQUEST\r\n    -- =====================================================\r\n\r\n    if not exists (\r\n        select 1\r\n        from public.rating_settings rs\r\n        where rs.algorithm_version = btrim(p_algorithm_version)\r\n    ) then\r\n        raise exception\r\n            ''Không tồn tại algorithm_version %.'',\r\n            p_algorithm_version;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 7. VALIDATE PLAYER\r\n    -- =====================================================\r\n    --\r\n    -- Không bắt buộc ACTIVE.\r\n    -- Adjustment backdated cho player INACTIVE vẫn có thể\r\n    -- là một correction lịch sử hợp lệ.\r\n    -- =====================================================\r\n\r\n    select\r\n        p.full_name,\r\n        p.status\r\n    into\r\n        v_player_name,\r\n        v_player_status\r\n    from public.players p\r\n    where p.id = p_player_id;\r\n\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy VĐV %.'',\r\n            p_player_id;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 8. INSERT IMMUTABLE SOURCE ADJUSTMENT\r\n    -- =====================================================\r\n\r\n    insert into public.rating_adjustments (\r\n        player_id,\r\n        amount,\r\n        reason,\r\n        created_by,\r\n        effective_at,\r\n        request_id,\r\n        request_algorithm_version\r\n    )\r\n    values (\r\n        p_player_id,\r\n        p_amount,\r\n        btrim(p_reason),\r\n        v_actor_user_id,\r\n        p_effective_at,\r\n        p_request_id,\r\n        btrim(p_algorithm_version)\r\n    )\r\n    returning\r\n        id,\r\n        replay_order\r\n    into\r\n        v_adjustment_id,\r\n        v_replay_order;\r\n\r\n\r\n    -- =====================================================\r\n    -- 9. REBUILD FULL TIMELINE\r\n    -- =====================================================\r\n    --\r\n    -- Nếu rebuild lỗi:\r\n    -- toàn bộ transaction rollback,\r\n    -- bao gồm Adjustment vừa INSERT.\r\n    -- =====================================================\r\n\r\n    v_rebuild_result :=\r\n        public._rebuild_ratings_internal(\r\n            btrim(p_algorithm_version),\r\n            v_actor_user_id\r\n        );\r\n\r\n\r\n    if coalesce(\r\n        (v_rebuild_result ->> ''success'')::boolean,\r\n        false\r\n    ) is not true then\r\n        raise exception\r\n            ''Rating rebuild không thành công.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 10. READ DERIVED ADJUSTMENT EVENT\r\n    -- =====================================================\r\n\r\n    select\r\n        rae.rating_before,\r\n        rae.requested_amount,\r\n        rae.applied_delta,\r\n        rae.rating_after\r\n    into\r\n        v_rating_before,\r\n        v_requested_amount,\r\n        v_applied_delta,\r\n        v_rating_after\r\n    from public.rating_adjustment_events rae\r\n    where rae.adjustment_id = v_adjustment_id\r\n      and rae.algorithm_version = btrim(p_algorithm_version);\r\n\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy derived Rating Adjustment Event sau rebuild.'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 11. AUDIT BUSINESS ACTION\r\n    -- =====================================================\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        v_actor_user_id,\r\n        ''RECORD_RATING_ADJUSTMENT'',\r\n        ''rating_adjustments'',\r\n        v_adjustment_id,\r\n        null,\r\n        jsonb_build_object(\r\n            ''request_id'',\r\n                p_request_id,\r\n\r\n            ''player_id'',\r\n                p_player_id,\r\n\r\n            ''player_name'',\r\n                v_player_name,\r\n\r\n            ''player_status'',\r\n                v_player_status,\r\n\r\n            ''amount_requested'',\r\n                v_requested_amount,\r\n\r\n            ''amount_applied'',\r\n                v_applied_delta,\r\n\r\n            ''rating_before'',\r\n                v_rating_before,\r\n\r\n            ''rating_after'',\r\n                v_rating_after,\r\n\r\n            ''effective_at'',\r\n                p_effective_at,\r\n\r\n            ''replay_order'',\r\n                v_replay_order,\r\n\r\n            ''algorithm_version'',\r\n                btrim(p_algorithm_version),\r\n\r\n            ''idempotent_replay'',\r\n                false\r\n        ),\r\n        btrim(p_reason),\r\n        now()\r\n    );\r\n\r\n\r\n    -- =====================================================\r\n    -- 12. RETURN NEW REQUEST RESULT\r\n    -- =====================================================\r\n\r\n    return jsonb_build_object(\r\n        ''success'',\r\n            true,\r\n\r\n        ''idempotent_replay'',\r\n            false,\r\n\r\n        ''request_id'',\r\n            p_request_id,\r\n\r\n        ''adjustment_id'',\r\n            v_adjustment_id,\r\n\r\n        ''replay_order'',\r\n            v_replay_order,\r\n\r\n        ''player_id'',\r\n            p_player_id,\r\n\r\n        ''player_name'',\r\n            v_player_name,\r\n\r\n        ''player_status'',\r\n            v_player_status,\r\n\r\n        ''effective_at'',\r\n            p_effective_at,\r\n\r\n        ''reason'',\r\n            btrim(p_reason),\r\n\r\n        ''algorithm_version'',\r\n            btrim(p_algorithm_version),\r\n\r\n        ''rating_before'',\r\n            v_rating_before,\r\n\r\n        ''requested_amount'',\r\n            v_requested_amount,\r\n\r\n        ''applied_delta'',\r\n            v_applied_delta,\r\n\r\n        ''rating_after'',\r\n            v_rating_after,\r\n\r\n        ''rebuild'',\r\n            v_rebuild_result\r\n    );\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.record_rating_adjustment_active(p_request_id uuid, p_player_id uuid, p_amount numeric, p_reason text, p_effective_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  return public.record_rating_adjustment(\r\n    p_request_id,\r\n    p_player_id,\r\n    p_amount,\r\n    p_reason,\r\n    p_effective_at,\r\n    public._get_active_rating_version()\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.reject_match_by_opponent(p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_actor uuid;\r\n  v_actor_player_id uuid;\r\n\r\n  v_match public.matches%rowtype;\r\n\r\n  v_creator_player_id uuid;\r\n  v_creator_team text;\r\n  v_actor_team text;\r\n\r\n  v_reason text;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  perform pg_advisory_xact_lock(726184501);\r\n\r\n  v_actor := auth.uid();\r\n\r\n  if v_actor is null then\r\n    raise exception ''AUTH_REQUIRED'';\r\n  end if;\r\n\r\n  if p_match_id is null then\r\n    raise exception ''MATCH_ID_REQUIRED'';\r\n  end if;\r\n\r\n  v_reason := nullif(btrim(p_reason), '''');\r\n\r\n  if v_reason is null then\r\n    raise exception ''REJECTION_REASON_REQUIRED'';\r\n  end if;\r\n\r\n  if char_length(v_reason) < 3 then\r\n    raise exception ''REJECTION_REASON_TOO_SHORT'';\r\n  end if;\r\n\r\n  if char_length(v_reason) > 1000 then\r\n    raise exception ''REJECTION_REASON_TOO_LONG'';\r\n  end if;\r\n\r\n  select pr.player_id\r\n  into v_actor_player_id\r\n  from public.profiles pr\r\n  join public.players p\r\n    on p.id = pr.player_id\r\n  where pr.id = v_actor\r\n    and pr.role = ''MEMBER''\r\n    and pr.is_active = true\r\n    and p.player_type = ''CLUB''\r\n    and p.status = ''ACTIVE'';\r\n\r\n  if not found\r\n     or v_actor_player_id is null then\r\n    raise exception ''ACTIVE_MEMBER_PLAYER_REQUIRED'';\r\n  end if;\r\n\r\n  select *\r\n  into v_match\r\n  from public.matches\r\n  where id = p_match_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception ''MATCH_NOT_FOUND'';\r\n  end if;\r\n\r\n  if v_match.status <> ''PENDING'' then\r\n    raise exception ''MATCH_NOT_PENDING'';\r\n  end if;\r\n\r\n  if v_match.match_type not in (\r\n    ''CLUB_RATED'',\r\n    ''FRIENDLY_RATED''\r\n  ) then\r\n    raise exception\r\n      ''OPPONENT_CONFIRMATION_NOT_ALLOWED_FOR_MATCH_TYPE'';\r\n  end if;\r\n\r\n  if v_match.tournament_id is not null\r\n     or v_match.league_id is not null then\r\n    raise exception\r\n      ''OPPONENT_CONFIRMATION_REQUIRES_STANDARD_MATCH'';\r\n  end if;\r\n\r\n  if v_match.created_by = v_actor then\r\n    raise exception ''CREATOR_CANNOT_REJECT'';\r\n  end if;\r\n\r\n  if v_match.opponent_rejected_by is not null then\r\n    raise exception ''MATCH_ALREADY_REJECTED'';\r\n  end if;\r\n\r\n  select\r\n    (al.new_data ->> ''member_player_id'')::uuid\r\n  into v_creator_player_id\r\n  from public.audit_logs al\r\n  where al.record_id = p_match_id\r\n    and al.table_name = ''matches''\r\n    and al.action = ''CREATE_MY_PENDING_MATCH''\r\n    and al.user_id = v_match.created_by\r\n  order by al.created_at asc\r\n  limit 1;\r\n\r\n  if not found\r\n     or v_creator_player_id is null then\r\n    raise exception ''MEMBER_CREATED_MATCH_REQUIRED'';\r\n  end if;\r\n\r\n  select mp.team\r\n  into v_creator_team\r\n  from public.match_players mp\r\n  where mp.match_id = p_match_id\r\n    and mp.player_id = v_creator_player_id;\r\n\r\n  if not found then\r\n    raise exception ''CREATOR_PLAYER_NOT_IN_MATCH'';\r\n  end if;\r\n\r\n  select mp.team\r\n  into v_actor_team\r\n  from public.match_players mp\r\n  where mp.match_id = p_match_id\r\n    and mp.player_id = v_actor_player_id;\r\n\r\n  if not found then\r\n    raise exception ''REJECTOR_NOT_IN_MATCH'';\r\n  end if;\r\n\r\n  if v_actor_team = v_creator_team then\r\n    raise exception ''CREATOR_TEAM_CANNOT_REJECT'';\r\n  end if;\r\n\r\n  update public.matches\r\n  set\r\n    opponent_rejected_by = v_actor,\r\n    opponent_rejected_at = now(),\r\n    opponent_rejection_reason = v_reason,\r\n\r\n    -- defensive reset\r\n    opponent_confirmed_by = null,\r\n    opponent_confirmed_at = null,\r\n\r\n    updated_at = now()\r\n  where id = p_match_id;\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    table_name,\r\n    record_id,\r\n    old_data,\r\n    new_data,\r\n    reason,\r\n    created_at\r\n  )\r\n  values (\r\n    v_actor,\r\n    ''REJECT_MATCH_BY_OPPONENT'',\r\n    ''matches'',\r\n    p_match_id,\r\n\r\n    jsonb_build_object(\r\n      ''status'',\r\n      v_match.status,\r\n      ''opponent_rejected_by'',\r\n      v_match.opponent_rejected_by,\r\n      ''opponent_rejected_at'',\r\n      v_match.opponent_rejected_at,\r\n      ''opponent_rejection_reason'',\r\n      v_match.opponent_rejection_reason\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      ''status'',\r\n      ''PENDING'',\r\n      ''opponent_rejected_by'',\r\n      v_actor,\r\n      ''opponent_rejected_at'',\r\n      now(),\r\n      ''engine'',\r\n      ''MATCH_OPPONENT_REJECTION_P1_2B''\r\n    ),\r\n\r\n    v_reason,\r\n    now()\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    ''success'',\r\n    true,\r\n    ''match_id'',\r\n    p_match_id,\r\n    ''status'',\r\n    ''PENDING'',\r\n    ''opponent_rejected_by'',\r\n    v_actor,\r\n    ''rejection_reason'',\r\n    v_reason\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.resubmit_my_rejected_match(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_actor uuid;\r\n  v_match public.matches%rowtype;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  perform pg_advisory_xact_lock(726184501);\r\n\r\n  v_actor := auth.uid();\r\n\r\n  if v_actor is null then\r\n    raise exception ''AUTH_REQUIRED'';\r\n  end if;\r\n\r\n  if p_match_id is null then\r\n    raise exception ''MATCH_ID_REQUIRED'';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles pr\r\n    where pr.id = v_actor\r\n      and pr.role = ''MEMBER''\r\n      and pr.is_active = true\r\n  ) then\r\n    raise exception ''ACTIVE_MEMBER_REQUIRED'';\r\n  end if;\r\n\r\n  select *\r\n  into v_match\r\n  from public.matches\r\n  where id = p_match_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception ''MATCH_NOT_FOUND'';\r\n  end if;\r\n\r\n  if v_match.status <> ''PENDING'' then\r\n    raise exception ''MATCH_NOT_PENDING'';\r\n  end if;\r\n\r\n  if v_match.created_by <> v_actor then\r\n    raise exception ''ONLY_CREATOR_CAN_RESUBMIT'';\r\n  end if;\r\n\r\n  if v_match.opponent_rejected_by is null then\r\n    raise exception ''MATCH_NOT_REJECTED'';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.audit_logs al\r\n    where al.record_id = p_match_id\r\n      and al.table_name = ''matches''\r\n      and al.action = ''CREATE_MY_PENDING_MATCH''\r\n      and al.user_id = v_actor\r\n  ) then\r\n    raise exception ''MEMBER_CREATED_MATCH_REQUIRED'';\r\n  end if;\r\n\r\n  update public.matches\r\n  set\r\n    opponent_rejected_by = null,\r\n    opponent_rejected_at = null,\r\n    opponent_rejection_reason = null,\r\n    opponent_confirmed_by = null,\r\n    opponent_confirmed_at = null,\r\n    updated_at = now()\r\n  where id = p_match_id;\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    table_name,\r\n    record_id,\r\n    old_data,\r\n    new_data,\r\n    reason,\r\n    created_at\r\n  )\r\n  values (\r\n    v_actor,\r\n    ''RESUBMIT_MATCH_BY_CREATOR'',\r\n    ''matches'',\r\n    p_match_id,\r\n\r\n    jsonb_build_object(\r\n      ''status'',\r\n      v_match.status,\r\n      ''opponent_rejected_by'',\r\n      v_match.opponent_rejected_by,\r\n      ''opponent_rejected_at'',\r\n      v_match.opponent_rejected_at,\r\n      ''opponent_rejection_reason'',\r\n      v_match.opponent_rejection_reason\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      ''status'',\r\n      ''PENDING'',\r\n      ''opponent_rejected_by'',\r\n      null,\r\n      ''opponent_rejected_at'',\r\n      null,\r\n      ''engine'',\r\n      ''MATCH_OPPONENT_RESUBMIT_P1_2B''\r\n    ),\r\n\r\n    ''Creator chỉnh sửa và gửi lại trận để đối thủ xác nhận'',\r\n    now()\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    ''success'',\r\n    true,\r\n    ''match_id'',\r\n    p_match_id,\r\n    ''status'',\r\n    ''PENDING'',\r\n    ''resubmitted'',\r\n    true\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.set_pending_match_players(p_match_id uuid, p_team_a_player_1 uuid, p_team_a_player_2 uuid, p_team_b_player_1 uuid, p_team_b_player_2 uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_user_id uuid;\r\n    v_role text;\r\n    v_is_active boolean;\r\n\r\n    v_match public.matches%rowtype;\r\n\r\n    v_existing_players jsonb;\r\n    v_new_players jsonb;\r\n\r\n    v_found_count integer;\r\n    v_active_count integer;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n\r\n    perform pg_advisory_xact_lock(726184501);\r\n\r\n\r\n    -- =====================================================\r\n    -- 1. VALIDATE INPUT\r\n    -- =====================================================\r\n\r\n    if p_match_id is null then\r\n        raise exception\r\n            ''match_id không được NULL'';\r\n    end if;\r\n\r\n\r\n    if p_team_a_player_1 is null\r\n       or p_team_a_player_2 is null\r\n       or p_team_b_player_1 is null\r\n       or p_team_b_player_2 is null then\r\n\r\n        raise exception\r\n            ''Phải cung cấp đầy đủ đúng 4 VĐV'';\r\n\r\n    end if;\r\n\r\n\r\n    if cardinality(\r\n        array[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    ) <> 4 then\r\n\r\n        raise exception\r\n            ''Danh sách VĐV không hợp lệ'';\r\n\r\n    end if;\r\n\r\n\r\n    if (\r\n        select count(distinct x)\r\n        from unnest(\r\n            array[\r\n                p_team_a_player_1,\r\n                p_team_a_player_2,\r\n                p_team_b_player_1,\r\n                p_team_b_player_2\r\n            ]::uuid[]\r\n        ) as t(x)\r\n    ) <> 4 then\r\n\r\n        raise exception\r\n            ''Một VĐV không được xuất hiện nhiều hơn một lần trong cùng trận'';\r\n\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 2. AUTHENTICATION\r\n    -- =====================================================\r\n\r\n    v_user_id := auth.uid();\r\n\r\n    if v_user_id is null then\r\n        raise exception\r\n            ''Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 3. AUTHORIZATION\r\n    -- =====================================================\r\n\r\n    select\r\n        role,\r\n        is_active\r\n    into\r\n        v_role,\r\n        v_is_active\r\n    from public.profiles\r\n    where id = v_user_id;\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy hồ sơ người dùng'';\r\n    end if;\r\n\r\n\r\n    if coalesce(v_is_active, false) = false then\r\n        raise exception\r\n            ''Tài khoản đã bị vô hiệu hóa'';\r\n    end if;\r\n\r\n\r\n    if v_role <> ''ADMIN'' then\r\n        raise exception\r\n            ''Chỉ ADMIN mới được thay đổi VĐV của trận PENDING'';\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 4. LOCK MATCH\r\n    -- =====================================================\r\n\r\n    select *\r\n    into v_match\r\n    from public.matches\r\n    where id = p_match_id\r\n    for update;\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy trận đấu: %'',\r\n            p_match_id;\r\n    end if;\r\n\r\n\r\n    if v_match.status <> ''PENDING'' then\r\n        raise exception\r\n            ''Chỉ được thay đổi VĐV của trận PENDING. Trạng thái hiện tại: %'',\r\n            v_match.status;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 5. VALIDATE PLAYERS EXIST\r\n    -- =====================================================\r\n\r\n    select count(*)\r\n    into v_found_count\r\n    from public.players p\r\n    where p.id = any(\r\n        array[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    );\r\n\r\n\r\n    if v_found_count <> 4 then\r\n        raise exception\r\n            ''Có VĐV không tồn tại trong hệ thống. Tìm thấy %/4 VĐV'',\r\n            v_found_count;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 6. VALIDATE PLAYERS ACTIVE\r\n    -- =====================================================\r\n\r\n    select count(*)\r\n    into v_active_count\r\n    from public.players p\r\n    where p.id = any(\r\n        array[\r\n            p_team_a_player_1,\r\n            p_team_a_player_2,\r\n            p_team_b_player_1,\r\n            p_team_b_player_2\r\n        ]::uuid[]\r\n    )\r\n      and p.status = ''ACTIVE'';\r\n\r\n\r\n    if v_active_count <> 4 then\r\n        raise exception\r\n            ''Tất cả 4 VĐV phải đang ACTIVE. Hiện có %/4 VĐV ACTIVE'',\r\n            v_active_count;\r\n    end if;\r\n\r\n\r\n    -- =====================================================\r\n    -- 7. SNAPSHOT OLD PLAYERS FOR AUDIT\r\n    -- =====================================================\r\n\r\n    select coalesce(\r\n        jsonb_agg(\r\n            jsonb_build_object(\r\n                ''player_id'', mp.player_id,\r\n                ''team'', mp.team,\r\n                ''partner_player_id'', mp.partner_player_id\r\n            )\r\n            order by mp.team, mp.player_id\r\n        ),\r\n        ''[]''::jsonb\r\n    )\r\n    into v_existing_players\r\n    from public.match_players mp\r\n    where mp.match_id = p_match_id;\r\n\r\n\r\n    -- =====================================================\r\n    -- 8. REPLACE CURRENT PENDING PLAYER SET\r\n    -- =====================================================\r\n\r\n    delete from public.match_players\r\n    where match_id = p_match_id;\r\n\r\n\r\n    insert into public.match_players (\r\n        match_id,\r\n        player_id,\r\n        team,\r\n        partner_player_id,\r\n        created_at\r\n    )\r\n    values\r\n\r\n        (\r\n            p_match_id,\r\n            p_team_a_player_1,\r\n            ''A'',\r\n            p_team_a_player_2,\r\n            now()\r\n        ),\r\n\r\n        (\r\n            p_match_id,\r\n            p_team_a_player_2,\r\n            ''A'',\r\n            p_team_a_player_1,\r\n            now()\r\n        ),\r\n\r\n        (\r\n            p_match_id,\r\n            p_team_b_player_1,\r\n            ''B'',\r\n            p_team_b_player_2,\r\n            now()\r\n        ),\r\n\r\n        (\r\n            p_match_id,\r\n            p_team_b_player_2,\r\n            ''B'',\r\n            p_team_b_player_1,\r\n            now()\r\n        );\r\n\r\n\r\n    -- =====================================================\r\n    -- 9. SNAPSHOT NEW PLAYERS FOR AUDIT\r\n    -- =====================================================\r\n\r\n    select jsonb_agg(\r\n        jsonb_build_object(\r\n            ''player_id'', mp.player_id,\r\n            ''team'', mp.team,\r\n            ''partner_player_id'', mp.partner_player_id\r\n        )\r\n        order by mp.team, mp.player_id\r\n    )\r\n    into v_new_players\r\n    from public.match_players mp\r\n    where mp.match_id = p_match_id;\r\n\r\n\r\n    -- =====================================================\r\n    -- 10. AUDIT\r\n    -- =====================================================\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        v_user_id,\r\n        ''SET_PENDING_MATCH_PLAYERS'',\r\n        ''match_players'',\r\n        p_match_id,\r\n\r\n        jsonb_build_object(\r\n            ''players'', v_existing_players\r\n        ),\r\n\r\n        jsonb_build_object(\r\n            ''players'', v_new_players,\r\n            ''player_count'', 4,\r\n            ''team_a_count'', 2,\r\n            ''team_b_count'', 2,\r\n            ''partner_assignment'', ''SERVER_MANAGED'',\r\n            ''engine'', ''PENDING_MATCH_PLAYERS_V1''\r\n        ),\r\n\r\n        ''Cập nhật 4 VĐV và đội của trận PENDING'',\r\n\r\n        now()\r\n    );\r\n\r\n\r\n    -- =====================================================\r\n    -- 11. RESULT\r\n    -- =====================================================\r\n\r\n    return jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', p_match_id,\r\n        ''status'', ''PENDING'',\r\n\r\n        ''team_a'', jsonb_build_array(\r\n            jsonb_build_object(\r\n                ''player_id'', p_team_a_player_1,\r\n                ''partner_player_id'', p_team_a_player_2\r\n            ),\r\n            jsonb_build_object(\r\n                ''player_id'', p_team_a_player_2,\r\n                ''partner_player_id'', p_team_a_player_1\r\n            )\r\n        ),\r\n\r\n        ''team_b'', jsonb_build_array(\r\n            jsonb_build_object(\r\n                ''player_id'', p_team_b_player_1,\r\n                ''partner_player_id'', p_team_b_player_2\r\n            ),\r\n            jsonb_build_object(\r\n                ''player_id'', p_team_b_player_2,\r\n                ''partner_player_id'', p_team_b_player_1\r\n            )\r\n        ),\r\n\r\n        ''players_set'', 4\r\n    );\r\n\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.update_my_rejected_pending_match(p_match_id uuid, p_played_at timestamp with time zone, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_team_a_player_1 uuid, p_team_a_player_2 uuid, p_team_b_player_1 uuid, p_team_b_player_2 uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_actor uuid;\r\n  v_my_player_id uuid;\r\n  v_match public.matches%rowtype;\r\n\r\n  v_distinct_count integer;\r\n  v_found_count integer;\r\n  v_active_count integer;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  perform pg_advisory_xact_lock(726184501);\r\n\r\n  v_actor := auth.uid();\r\n\r\n  if v_actor is null then\r\n    raise exception ''AUTH_REQUIRED'';\r\n  end if;\r\n\r\n  select pr.player_id\r\n  into v_my_player_id\r\n  from public.profiles pr\r\n  join public.players p\r\n    on p.id = pr.player_id\r\n  where pr.id = v_actor\r\n    and pr.role = ''MEMBER''\r\n    and pr.is_active = true\r\n    and p.player_type = ''CLUB''\r\n    and p.status = ''ACTIVE'';\r\n\r\n  if not found\r\n     or v_my_player_id is null then\r\n    raise exception ''ACTIVE_MEMBER_PLAYER_REQUIRED'';\r\n  end if;\r\n\r\n  if p_match_id is null then\r\n    raise exception ''MATCH_ID_REQUIRED'';\r\n  end if;\r\n\r\n  select *\r\n  into v_match\r\n  from public.matches\r\n  where id = p_match_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception ''MATCH_NOT_FOUND'';\r\n  end if;\r\n\r\n  if v_match.status <> ''PENDING'' then\r\n    raise exception ''MATCH_NOT_PENDING'';\r\n  end if;\r\n\r\n  if v_match.created_by <> v_actor then\r\n    raise exception ''ONLY_CREATOR_CAN_EDIT'';\r\n  end if;\r\n\r\n  if v_match.opponent_rejected_by is null then\r\n    raise exception ''MATCH_NOT_REJECTED'';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.audit_logs al\r\n    where al.record_id = p_match_id\r\n      and al.table_name = ''matches''\r\n      and al.action = ''CREATE_MY_PENDING_MATCH''\r\n      and al.user_id = v_actor\r\n  ) then\r\n    raise exception ''MEMBER_CREATED_MATCH_REQUIRED'';\r\n  end if;\r\n\r\n  if p_match_type not in (\r\n    ''CLUB_RATED'',\r\n    ''FRIENDLY_RATED'',\r\n    ''TRAINING''\r\n  ) then\r\n    raise exception ''MEMBER_MATCH_TYPE_NOT_ALLOWED'';\r\n  end if;\r\n\r\n  if p_score_mode not in (\r\n    ''POINTS'',\r\n    ''RESULT''\r\n  ) then\r\n    raise exception ''INVALID_SCORE_MODE'';\r\n  end if;\r\n\r\n  if p_played_at is null then\r\n    raise exception ''PLAYED_AT_REQUIRED'';\r\n  end if;\r\n\r\n  if p_team_a_score is null\r\n     or p_team_b_score is null then\r\n    raise exception ''SCORE_REQUIRED'';\r\n  end if;\r\n\r\n  if p_team_a_score < 0\r\n     or p_team_b_score < 0 then\r\n    raise exception ''NEGATIVE_SCORE_NOT_ALLOWED'';\r\n  end if;\r\n\r\n  if p_score_mode = ''POINTS''\r\n     and (\r\n       p_team_a_score +\r\n       p_team_b_score\r\n     ) <= 0 then\r\n    raise exception ''POINTS_SCORE_MUST_HAVE_RESULT'';\r\n  end if;\r\n\r\n  if p_score_mode = ''RESULT'' then\r\n    if p_team_a_score not in (0,1)\r\n       or p_team_b_score not in (0,1) then\r\n      raise exception ''RESULT_SCORE_MUST_BE_0_OR_1'';\r\n    end if;\r\n\r\n    if p_team_a_score = 0\r\n       and p_team_b_score = 0 then\r\n      raise exception ''RESULT_SCORE_MUST_HAVE_WINNER'';\r\n    end if;\r\n  end if;\r\n\r\n  if p_team_a_player_1 is null\r\n     or p_team_a_player_2 is null\r\n     or p_team_b_player_1 is null\r\n     or p_team_b_player_2 is null then\r\n    raise exception ''FOUR_PLAYERS_REQUIRED'';\r\n  end if;\r\n\r\n  select count(distinct x)\r\n  into v_distinct_count\r\n  from unnest(\r\n    array[\r\n      p_team_a_player_1,\r\n      p_team_a_player_2,\r\n      p_team_b_player_1,\r\n      p_team_b_player_2\r\n    ]::uuid[]\r\n  ) t(x);\r\n\r\n  if v_distinct_count <> 4 then\r\n    raise exception ''PLAYERS_MUST_BE_DISTINCT'';\r\n  end if;\r\n\r\n  if not (\r\n    v_my_player_id = p_team_a_player_1\r\n    or v_my_player_id = p_team_a_player_2\r\n    or v_my_player_id = p_team_b_player_1\r\n    or v_my_player_id = p_team_b_player_2\r\n  ) then\r\n    raise exception ''MEMBER_MUST_PARTICIPATE'';\r\n  end if;\r\n\r\n  select count(*)\r\n  into v_found_count\r\n  from public.players p\r\n  where p.id = any(\r\n    array[\r\n      p_team_a_player_1,\r\n      p_team_a_player_2,\r\n      p_team_b_player_1,\r\n      p_team_b_player_2\r\n    ]::uuid[]\r\n  );\r\n\r\n  if v_found_count <> 4 then\r\n    raise exception ''PLAYER_NOT_FOUND'';\r\n  end if;\r\n\r\n  select count(*)\r\n  into v_active_count\r\n  from public.players p\r\n  where p.id = any(\r\n    array[\r\n      p_team_a_player_1,\r\n      p_team_a_player_2,\r\n      p_team_b_player_1,\r\n      p_team_b_player_2\r\n    ]::uuid[]\r\n  )\r\n    and p.status = ''ACTIVE'';\r\n\r\n  if v_active_count <> 4 then\r\n    raise exception ''ALL_PLAYERS_MUST_BE_ACTIVE'';\r\n  end if;\r\n\r\n  update public.matches\r\n  set\r\n    played_at = p_played_at,\r\n    match_type = p_match_type,\r\n    score_mode = p_score_mode,\r\n    team_a_score = p_team_a_score,\r\n    team_b_score = p_team_b_score,\r\n    notes = nullif(btrim(p_notes), ''''),\r\n    updated_at = now()\r\n  where id = p_match_id;\r\n\r\n  delete from public.match_players\r\n  where match_id = p_match_id;\r\n\r\n  insert into public.match_players (\r\n    match_id,\r\n    player_id,\r\n    team,\r\n    partner_player_id,\r\n    created_at\r\n  )\r\n  values\r\n    (\r\n      p_match_id,\r\n      p_team_a_player_1,\r\n      ''A'',\r\n      p_team_a_player_2,\r\n      now()\r\n    ),\r\n    (\r\n      p_match_id,\r\n      p_team_a_player_2,\r\n      ''A'',\r\n      p_team_a_player_1,\r\n      now()\r\n    ),\r\n    (\r\n      p_match_id,\r\n      p_team_b_player_1,\r\n      ''B'',\r\n      p_team_b_player_2,\r\n      now()\r\n    ),\r\n    (\r\n      p_match_id,\r\n      p_team_b_player_2,\r\n      ''B'',\r\n      p_team_b_player_1,\r\n      now()\r\n    );\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    table_name,\r\n    record_id,\r\n    old_data,\r\n    new_data,\r\n    reason,\r\n    created_at\r\n  )\r\n  values (\r\n    v_actor,\r\n    ''UPDATE_MY_REJECTED_PENDING_MATCH'',\r\n    ''matches'',\r\n    p_match_id,\r\n\r\n    jsonb_build_object(\r\n      ''played_at'', v_match.played_at,\r\n      ''match_type'', v_match.match_type,\r\n      ''score_mode'', v_match.score_mode,\r\n      ''team_a_score'', v_match.team_a_score,\r\n      ''team_b_score'', v_match.team_b_score,\r\n      ''notes'', v_match.notes\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      ''played_at'', p_played_at,\r\n      ''match_type'', p_match_type,\r\n      ''score_mode'', p_score_mode,\r\n      ''team_a_score'', p_team_a_score,\r\n      ''team_b_score'', p_team_b_score,\r\n      ''team_a'', jsonb_build_array(\r\n        p_team_a_player_1,\r\n        p_team_a_player_2\r\n      ),\r\n      ''team_b'', jsonb_build_array(\r\n        p_team_b_player_1,\r\n        p_team_b_player_2\r\n      ),\r\n      ''notes'',\r\n        nullif(btrim(p_notes), ''''),\r\n      ''engine'',\r\n        ''MEMBER_REJECTED_MATCH_EDIT_P1_2B''\r\n    ),\r\n\r\n    ''Creator sửa trận sau khi đối thủ từ chối xác nhận'',\r\n    now()\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    ''success'', true,\r\n    ''match_id'', p_match_id,\r\n    ''status'', ''PENDING'',\r\n    ''rejected'', true,\r\n    ''updated'', true\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.void_match(p_match_id uuid, p_reason text, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n    v_user_id uuid;\r\n    v_role text;\r\n    v_is_active boolean;\r\n    v_can_approve_matches boolean;\r\n\r\n    v_match public.matches%rowtype;\r\n    v_rating_result jsonb;\r\n\r\n    v_contribution_count integer := 0;\r\n    v_contributions_adjusted integer := 0;\r\n\r\n    v_original_cash_count integer := 0;\r\n    v_refund_created_count integer := 0;\r\n    v_existing_refund_count integer := 0;\r\n\r\n    r_tx record;\r\n    v_refund_transaction_id uuid;\r\nbegin\r\n    perform pg_advisory_xact_lock(726184501);\r\n\r\n    if p_match_id is null then\r\n        raise exception ''match_id không được NULL'';\r\n    end if;\r\n\r\n    if p_reason is null\r\n       or btrim(p_reason) = '''' then\r\n        raise exception ''Lý do VOID không được để trống'';\r\n    end if;\r\n\r\n    if p_algorithm_version is null\r\n       or btrim(p_algorithm_version) = '''' then\r\n        raise exception ''algorithm_version không được để trống'';\r\n    end if;\r\n\r\n    v_user_id := auth.uid();\r\n\r\n    if v_user_id is null then\r\n        raise exception\r\n            ''Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ'';\r\n    end if;\r\n\r\n    select\r\n        role,\r\n        is_active,\r\n        can_approve_matches\r\n    into\r\n        v_role,\r\n        v_is_active,\r\n        v_can_approve_matches\r\n    from public.profiles\r\n    where id = v_user_id;\r\n\r\n    if not found then\r\n        raise exception ''Không tìm thấy hồ sơ người dùng'';\r\n    end if;\r\n\r\n    if coalesce(v_is_active, false) = false then\r\n        raise exception ''Tài khoản đã bị vô hiệu hóa'';\r\n    end if;\r\n\r\n    if upper(coalesce(v_role, '''')) <> ''ADMIN''\r\n       and coalesce(v_can_approve_matches, false) = false then\r\n        raise exception ''MATCH_APPROVAL_PERMISSION_REQUIRED'';\r\n    end if;\r\n\r\n    if not exists (\r\n        select 1\r\n        from public.rating_settings rs\r\n        where rs.algorithm_version = p_algorithm_version\r\n    ) then\r\n        raise exception\r\n            ''Không tồn tại Rating algorithm version: %'',\r\n            p_algorithm_version;\r\n    end if;\r\n\r\n    select *\r\n    into v_match\r\n    from public.matches\r\n    where id = p_match_id\r\n    for update;\r\n\r\n    if not found then\r\n        raise exception\r\n            ''Không tìm thấy trận đấu: %'',\r\n            p_match_id;\r\n    end if;\r\n\r\n    if v_match.status <> ''APPROVED'' then\r\n        raise exception\r\n            ''Không thể VOID trận %. Trạng thái hiện tại: %. Chỉ APPROVED mới được VOID'',\r\n            p_match_id,\r\n            v_match.status;\r\n    end if;\r\n\r\n    select count(*)\r\n    into v_contribution_count\r\n    from public.fund_contributions fc\r\n    where fc.match_id = p_match_id;\r\n\r\n    update public.fund_contributions\r\n    set status = ''DIEU_CHINH''\r\n    where match_id = p_match_id\r\n      and status <> ''DIEU_CHINH'';\r\n\r\n    get diagnostics\r\n        v_contributions_adjusted = row_count;\r\n\r\n    for r_tx in\r\n        select\r\n            ft.id,\r\n            ft.transaction_date,\r\n            ft.transaction_type,\r\n            ft.amount,\r\n            ft.description,\r\n            ft.player_id,\r\n            ft.match_id,\r\n            ft.payment_id\r\n        from public.fund_transactions ft\r\n        where ft.match_id = p_match_id\r\n          and ft.transaction_type in (\r\n              ''THU_QUY_THUA_TRAN'',\r\n              ''THU_QUY_HOA''\r\n          )\r\n        order by\r\n            ft.transaction_date,\r\n            ft.id\r\n    loop\r\n        v_original_cash_count :=\r\n            v_original_cash_count + 1;\r\n\r\n        if exists (\r\n            select 1\r\n            from public.fund_transactions rev\r\n            where rev.reversal_of_transaction_id = r_tx.id\r\n        ) then\r\n            v_existing_refund_count :=\r\n                v_existing_refund_count + 1;\r\n        else\r\n            insert into public.fund_transactions (\r\n                transaction_date,\r\n                transaction_type,\r\n                amount,\r\n                description,\r\n                player_id,\r\n                match_id,\r\n                tournament_id,\r\n                created_by,\r\n                created_at,\r\n                payment_id,\r\n                reversal_of_transaction_id\r\n            )\r\n            values (\r\n                now(),\r\n                ''HOAN_TIEN'',\r\n                r_tx.amount,\r\n                ''Hoàn tiền do VOID trận đấu'',\r\n                r_tx.player_id,\r\n                r_tx.match_id,\r\n                null,\r\n                v_user_id,\r\n                now(),\r\n                null,\r\n                r_tx.id\r\n            )\r\n            returning id\r\n            into v_refund_transaction_id;\r\n\r\n            v_refund_created_count :=\r\n                v_refund_created_count + 1;\r\n        end if;\r\n    end loop;\r\n\r\n    perform set_config(\r\n        ''app.match_workflow'',\r\n        ''VOID_MATCH'',\r\n        true\r\n    );\r\n\r\n    update public.matches\r\n    set\r\n        status = ''VOIDED'',\r\n        invalid_reason = btrim(p_reason),\r\n        updated_at = now()\r\n    where id = p_match_id;\r\n\r\n    perform set_config(\r\n        ''app.match_workflow'',\r\n        '''',\r\n        true\r\n    );\r\n\r\n    v_rating_result :=\r\n        public._rebuild_ratings_internal(\r\n            p_algorithm_version,\r\n            v_user_id\r\n        );\r\n\r\n    insert into public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    values (\r\n        v_user_id,\r\n        ''VOID_MATCH'',\r\n        ''matches'',\r\n        p_match_id,\r\n        jsonb_build_object(\r\n            ''status'', v_match.status,\r\n            ''invalid_reason'', v_match.invalid_reason\r\n        ),\r\n        jsonb_build_object(\r\n            ''status'', ''VOIDED'',\r\n            ''void_reason'', btrim(p_reason),\r\n            ''algorithm_version'', p_algorithm_version,\r\n            ''contribution_count'', v_contribution_count,\r\n            ''contributions_adjusted'', v_contributions_adjusted,\r\n            ''original_cash_transactions'', v_original_cash_count,\r\n            ''refunds_created'', v_refund_created_count,\r\n            ''existing_refunds'', v_existing_refund_count,\r\n            ''rating_result'', v_rating_result,\r\n            ''engine'', ''MATCH_VOID_V1''\r\n        ),\r\n        btrim(p_reason),\r\n        now()\r\n    );\r\n\r\n    return jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', p_match_id,\r\n        ''status_before'', v_match.status,\r\n        ''status_after'', ''VOIDED'',\r\n        ''reason'', btrim(p_reason),\r\n        ''algorithm_version'', p_algorithm_version,\r\n        ''contributions_found'', v_contribution_count,\r\n        ''contributions_adjusted'', v_contributions_adjusted,\r\n        ''original_cash_transactions'', v_original_cash_count,\r\n        ''refunds_created'', v_refund_created_count,\r\n        ''existing_refunds'', v_existing_refund_count,\r\n        ''rating'', v_rating_result\r\n    );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.approve_match(p_match_id uuid, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\ndeclare\r\n  v_user_id uuid;\r\n  v_role text;\r\n  v_is_active boolean;\r\n  v_can_approve_matches boolean;\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  v_user_id := auth.uid();\r\n\r\n  if v_user_id is null then\r\n    raise exception ''Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ'';\r\n  end if;\r\n\r\n  select\r\n    role,\r\n    is_active,\r\n    can_approve_matches\r\n  into\r\n    v_role,\r\n    v_is_active,\r\n    v_can_approve_matches\r\n  from public.profiles\r\n  where id = v_user_id;\r\n\r\n  if not found then\r\n    raise exception ''Không tìm thấy hồ sơ người dùng'';\r\n  end if;\r\n\r\n  if coalesce(v_is_active, false) = false then\r\n    raise exception ''Tài khoản đã bị vô hiệu hóa'';\r\n  end if;\r\n\r\n  if upper(coalesce(v_role, '''')) <> ''ADMIN''\r\n     and coalesce(v_can_approve_matches, false) = false then\r\n    raise exception ''MATCH_APPROVAL_PERMISSION_REQUIRED'';\r\n  end if;\r\n\r\n  return public._approve_match_internal(\r\n    p_match_id,\r\n    p_algorithm_version,\r\n    v_user_id,\r\n    null\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.approve_match_active(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\nbegin\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n  return public.approve_match(\r\n    p_match_id,\r\n    public._get_active_rating_version()\r\n  );\r\nend;\r\n'
;
CREATE OR REPLACE FUNCTION public.update_pending_match(p_match_id uuid, p_played_at timestamp with time zone, p_match_number integer, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_tournament_id uuid DEFAULT NULL::uuid, p_league_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS E'\r\nDECLARE\r\n    v_user_id uuid;\r\n    v_role text;\r\n    v_is_active boolean;\r\n\r\n    v_match public.matches%ROWTYPE;\r\n\r\n    v_tournament_status text;\r\n    v_league_status text;\r\n\r\n    v_tournament_changed boolean;\r\n    v_league_changed boolean;\r\nBEGIN\r\n    -- ACC07B business access gate\n    IF NOT public.current_user_business_access_active() THEN\n        RAISE EXCEPTION ''BUSINESS_ACCESS_REQUIRED'' USING ERRCODE = ''42501'';\n    END IF;\n    PERFORM pg_advisory_xact_lock(726184501);\r\n\r\n    IF p_match_id IS NULL THEN\r\n        RAISE EXCEPTION ''match_id không được NULL'';\r\n    END IF;\r\n\r\n    IF p_played_at IS NULL THEN\r\n        RAISE EXCEPTION ''played_at không được NULL'';\r\n    END IF;\r\n\r\n    IF p_match_type IS NULL\r\n       OR btrim(p_match_type) = '''' THEN\r\n        RAISE EXCEPTION ''match_type không được để trống'';\r\n    END IF;\r\n\r\n    IF p_score_mode IS NULL\r\n       OR btrim(p_score_mode) = '''' THEN\r\n        RAISE EXCEPTION ''score_mode không được để trống'';\r\n    END IF;\r\n\r\n    IF p_team_a_score IS NULL\r\n       OR p_team_b_score IS NULL THEN\r\n        RAISE EXCEPTION ''Tỷ số không được NULL'';\r\n    END IF;\r\n\r\n    IF p_team_a_score < 0\r\n       OR p_team_b_score < 0 THEN\r\n        RAISE EXCEPTION ''Tỷ số không được âm'';\r\n    END IF;\r\n\r\n    v_user_id := auth.uid();\r\n\r\n    IF v_user_id IS NULL THEN\r\n        RAISE EXCEPTION\r\n            ''Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ'';\r\n    END IF;\r\n\r\n    SELECT role, is_active\r\n    INTO v_role, v_is_active\r\n    FROM public.profiles\r\n    WHERE id = v_user_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION ''Không tìm thấy hồ sơ người dùng'';\r\n    END IF;\r\n\r\n    IF coalesce(v_is_active, false) = false THEN\r\n        RAISE EXCEPTION ''Tài khoản đã bị vô hiệu hóa'';\r\n    END IF;\r\n\r\n    IF v_role <> ''ADMIN'' THEN\r\n        RAISE EXCEPTION\r\n            ''Chỉ ADMIN mới được sửa trận PENDING'';\r\n    END IF;\r\n\r\n    IF p_match_type NOT IN (\r\n        ''TOURNAMENT'',\r\n        ''LEAGUE'',\r\n        ''CLUB_RATED'',\r\n        ''FRIENDLY_RATED'',\r\n        ''TRAINING''\r\n    ) THEN\r\n        RAISE EXCEPTION\r\n            ''match_type không được phép: %'',\r\n            p_match_type;\r\n    END IF;\r\n\r\n    IF p_score_mode NOT IN (''POINTS'', ''RESULT'') THEN\r\n        RAISE EXCEPTION\r\n            ''score_mode không hợp lệ: %'',\r\n            p_score_mode;\r\n    END IF;\r\n\r\n    IF p_score_mode = ''RESULT''\r\n       AND (\r\n            p_team_a_score NOT IN (0, 1)\r\n            OR p_team_b_score NOT IN (0, 1)\r\n       ) THEN\r\n        RAISE EXCEPTION\r\n            ''Trận RESULT chỉ chấp nhận score 0 hoặc 1'';\r\n    END IF;\r\n\r\n    SELECT *\r\n    INTO v_match\r\n    FROM public.matches\r\n    WHERE id = p_match_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION\r\n            ''Không tìm thấy trận đấu: %'',\r\n            p_match_id;\r\n    END IF;\r\n\r\n    IF v_match.status <> ''PENDING'' THEN\r\n        RAISE EXCEPTION\r\n            ''Chỉ được sửa trận PENDING. Trạng thái hiện tại: %'',\r\n            v_match.status;\r\n    END IF;\r\n\r\n    IF p_match_type = ''TOURNAMENT'' THEN\r\n\r\n        IF p_tournament_id IS NULL\r\n           OR p_league_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''TOURNAMENT_REQUIRES_TOURNAMENT_ID_ONLY'';\r\n        END IF;\r\n\r\n    ELSIF p_match_type = ''LEAGUE'' THEN\r\n\r\n        IF p_league_id IS NULL\r\n           OR p_tournament_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_REQUIRES_LEAGUE_ID_ONLY'';\r\n        END IF;\r\n\r\n    ELSE\r\n\r\n        IF p_tournament_id IS NOT NULL\r\n           OR p_league_id IS NOT NULL THEN\r\n            RAISE EXCEPTION\r\n                ''STANDARD_MATCH_CANNOT_HAVE_COMPETITION_ID'';\r\n        END IF;\r\n\r\n    END IF;\r\n\r\n    v_tournament_changed :=\r\n        p_tournament_id IS DISTINCT FROM v_match.tournament_id;\r\n\r\n    v_league_changed :=\r\n        p_league_id IS DISTINCT FROM v_match.league_id;\r\n\r\n    IF v_tournament_changed\r\n       AND p_tournament_id IS NOT NULL THEN\r\n\r\n        SELECT t.status\r\n        INTO v_tournament_status\r\n        FROM public.tournaments t\r\n        WHERE t.id = p_tournament_id\r\n        FOR SHARE;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION\r\n                ''Không tìm thấy giải đấu: %'',\r\n                p_tournament_id;\r\n        END IF;\r\n\r\n        IF v_tournament_status NOT IN (\r\n            ''DU_KIEN'',\r\n            ''MO_DANG_KY'',\r\n            ''DANG_DIEN_RA''\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                ''Không thể chuyển trận vào giải có trạng thái %'',\r\n                v_tournament_status;\r\n        END IF;\r\n    END IF;\r\n\r\n    IF v_league_changed\r\n       AND p_league_id IS NOT NULL THEN\r\n\r\n        SELECT l.status\r\n        INTO v_league_status\r\n        FROM public.leagues l\r\n        WHERE l.id = p_league_id\r\n        FOR SHARE;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_NOT_FOUND: %'',\r\n                p_league_id;\r\n        END IF;\r\n\r\n        IF v_league_status NOT IN (\r\n            ''DU_KIEN'',\r\n            ''DANG_DIEN_RA''\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                ''LEAGUE_STATUS_NOT_ATTACHABLE: %'',\r\n                v_league_status;\r\n        END IF;\r\n    END IF;\r\n\r\n    UPDATE public.matches\r\n    SET\r\n        played_at = p_played_at,\r\n        match_number = p_match_number,\r\n        match_type = p_match_type,\r\n        score_mode = p_score_mode,\r\n        team_a_score = p_team_a_score,\r\n        team_b_score = p_team_b_score,\r\n        tournament_id = p_tournament_id,\r\n        league_id = p_league_id,\r\n        notes = nullif(btrim(p_notes), ''''),\r\n        updated_at = now()\r\n    WHERE id = p_match_id;\r\n\r\n    INSERT INTO public.audit_logs (\r\n        user_id,\r\n        action,\r\n        table_name,\r\n        record_id,\r\n        old_data,\r\n        new_data,\r\n        reason,\r\n        created_at\r\n    )\r\n    VALUES (\r\n        v_user_id,\r\n        ''UPDATE_PENDING_MATCH'',\r\n        ''matches'',\r\n        p_match_id,\r\n\r\n        jsonb_build_object(\r\n            ''played_at'', v_match.played_at,\r\n            ''match_number'', v_match.match_number,\r\n            ''match_type'', v_match.match_type,\r\n            ''score_mode'', v_match.score_mode,\r\n            ''team_a_score'', v_match.team_a_score,\r\n            ''team_b_score'', v_match.team_b_score,\r\n            ''tournament_id'', v_match.tournament_id,\r\n            ''league_id'', v_match.league_id,\r\n            ''notes'', v_match.notes\r\n        ),\r\n\r\n        jsonb_build_object(\r\n            ''played_at'', p_played_at,\r\n            ''match_number'', p_match_number,\r\n            ''match_type'', p_match_type,\r\n            ''score_mode'', p_score_mode,\r\n            ''team_a_score'', p_team_a_score,\r\n            ''team_b_score'', p_team_b_score,\r\n            ''tournament_id'', p_tournament_id,\r\n            ''league_id'', p_league_id,\r\n            ''tournament_changed'', v_tournament_changed,\r\n            ''league_changed'', v_league_changed,\r\n            ''notes'', nullif(btrim(p_notes), ''''),\r\n            ''engine'', ''PENDING_MATCH_WRITE_P1''\r\n        ),\r\n\r\n        ''Cập nhật thông tin trận PENDING'',\r\n        now()\r\n    );\r\n\r\n    RETURN jsonb_build_object(\r\n        ''success'', true,\r\n        ''match_id'', p_match_id,\r\n        ''status'', ''PENDING'',\r\n        ''played_at'', p_played_at,\r\n        ''match_number'', p_match_number,\r\n        ''match_type'', p_match_type,\r\n        ''score_mode'', p_score_mode,\r\n        ''team_a_score'', p_team_a_score,\r\n        ''team_b_score'', p_team_b_score,\r\n        ''tournament_id'', p_tournament_id,\r\n        ''league_id'', p_league_id,\r\n        ''tournament_changed'', v_tournament_changed,\r\n        ''league_changed'', v_league_changed,\r\n        ''notes'', nullif(btrim(p_notes), '''')\r\n    );\r\nEND;\r\n'
;

