CREATE TRIGGER trg_guard_match_player_mutation BEFORE INSERT OR DELETE OR UPDATE ON public.match_players FOR EACH ROW EXECUTE FUNCTION guard_match_player_mutation();
CREATE TRIGGER trg_guard_match_mutation BEFORE INSERT OR DELETE OR UPDATE ON public.matches FOR EACH ROW EXECUTE FUNCTION guard_match_mutation();CREATE OR REPLACE FUNCTION public.current_user_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select exists (
        select 1
        from public.profiles p
        where p.id = auth.uid()
          and p.is_active = true
          and p.role = 'ADMIN'
    );
$function$
;
