CREATE TABLE rating_validation_b3b.intents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL,
  created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  roster jsonb NOT NULL, match_type text NOT NULL, score_mode text NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK(version>0), replaces_intent_id uuid UNIQUE REFERENCES rating_validation_b3b.intents,
  UNIQUE(created_by,request_id),
  CHECK(match_type IN ('CLUB_RATED','FRIENDLY_RATED','TRAINING')),
  CHECK(score_mode IN ('POINTS','RESULT'))
);
CREATE TABLE rating_validation_b3b.boundaries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,
  captured_at timestamptz NOT NULL, source_text text NOT NULL, fingerprint text NOT NULL,
  source_hash text NOT NULL, roster_hash text NOT NULL
);
CREATE TABLE rating_validation_b3b.seals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL UNIQUE REFERENCES rating_validation_b3b.intents,
  boundary_id uuid NOT NULL UNIQUE REFERENCES rating_validation_b3b.boundaries,
  sealed_at timestamptz NOT NULL DEFAULT clock_timestamp(), canonical_payload bytea NOT NULL,
  payload jsonb NOT NULL,
  payload_hash text GENERATED ALWAYS AS (encode(sha256(canonical_payload),'hex')) STORED,
  CHECK(convert_from(canonical_payload,'UTF8')::jsonb=payload)
);
CREATE TABLE rating_validation_b3b.submissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,
  request_id uuid NOT NULL, submitter uuid NOT NULL, version integer NOT NULL CHECK(version>0),
  match_id uuid NOT NULL, received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  body jsonb NOT NULL, body_hash text NOT NULL,
  UNIQUE(intent_id,version), UNIQUE(intent_id,request_id)
);
CREATE UNIQUE INDEX b3b_one_intent_per_match ON rating_validation_b3b.submissions(match_id) WHERE version=1;
-- Durable ingress/idempotency is operational, independent of optional research appends.
CREATE TABLE rating_validation_b3b.requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,
  request_id uuid NOT NULL, submitter uuid NOT NULL, version integer NOT NULL CHECK(version>0),
  match_id uuid NOT NULL, received_at timestamptz NOT NULL, body jsonb NOT NULL, match_number_at_binding integer,
  UNIQUE(intent_id,version), UNIQUE(intent_id,request_id)
);
CREATE UNIQUE INDEX b3b_request_match_identity ON rating_validation_b3b.requests(match_id) WHERE version=1;
CREATE TABLE rating_validation_b3b.events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES rating_validation_b3b.intents,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  kind text NOT NULL CHECK(kind IN ('VOID','MISSED','ABANDONED','ADJUDICATION','STARTED')), reason text NOT NULL
);
CREATE TABLE rating_validation_b3b.scores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL UNIQUE REFERENCES rating_validation_b3b.intents,
  submission_id uuid NOT NULL REFERENCES rating_validation_b3b.submissions,
  seal_id uuid NOT NULL REFERENCES rating_validation_b3b.seals,
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(), payload jsonb NOT NULL
);
CREATE INDEX b3b_boundary_intent ON rating_validation_b3b.boundaries(intent_id,captured_at);
CREATE INDEX b3b_event_intent ON rating_validation_b3b.events(intent_id,recorded_at);

CREATE FUNCTION rating_validation_b3b.hash_json(p jsonb) RETURNS text
LANGUAGE sql STABLE SET search_path=pg_catalog SET timezone='UTC' AS $$
 SELECT encode(sha256(convert_to(p::text,'UTF8')),'hex')
$$;
-- hash_json is not used in a generated expression. UTF8 encoding pinned by precondition.
CREATE FUNCTION rating_validation_b3b.immutable() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog SET timezone='UTC' AS $$
BEGIN RAISE EXCEPTION 'B3B_APPEND_ONLY' USING ERRCODE='42501'; END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['protocol','intents','boundaries','seals','submissions','requests','events','scores'] LOOP
  EXECUTE format('ALTER TABLE rating_validation_b3b.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE rating_validation_b3b.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE TRIGGER immutable_rows BEFORE UPDATE OR DELETE ON rating_validation_b3b.%I FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.immutable()',t);
  EXECUTE format('CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON rating_validation_b3b.%I FOR EACH STATEMENT EXECUTE FUNCTION rating_validation_b3b.immutable()',t);
 END LOOP;
END $$;

CREATE FUNCTION rating_validation_b3b.actor() RETURNS uuid LANGUAGE plpgsql
SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid:=auth.uid(); BEGIN
 IF a IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 IF NOT public.current_user_business_access_active() THEN RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN a;
END $$;
CREATE FUNCTION rating_validation_b3b.worker() RETURNS void LANGUAGE plpgsql
SET search_path=pg_catalog SET timezone='UTC' AS $$
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'WORKER_REQUIRED' USING ERRCODE='42501'; END IF;
END $$;
CREATE FUNCTION rating_validation_b3b.owner(p_intent uuid) RETURNS rating_validation_b3b.intents
LANGUAGE plpgsql SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid:=rating_validation_b3b.actor(); i rating_validation_b3b.intents;
BEGIN
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=p_intent FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTENT_NOT_FOUND'; END IF;
 IF i.created_by<>a AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=a AND role='ADMIN') THEN
  RAISE EXCEPTION 'INTENT_OWNER_REQUIRED' USING ERRCODE='42501';
 END IF;
 RETURN i;
END $$;
CREATE FUNCTION rating_validation_b3b.roster(a uuid[],b uuid[]) RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE result jsonb; BEGIN
 IF cardinality(a) IS DISTINCT FROM 2 OR cardinality(b) IS DISTINCT FROM 2
 OR (SELECT count(DISTINCT x) FROM unnest(a||b) x)<>4
 OR array_position(a||b,NULL) IS NOT NULL THEN RAISE EXCEPTION 'ROSTER_INVALID'; END IF;
 SELECT jsonb_build_object('A',(SELECT jsonb_agg(x ORDER BY x) FROM unnest(a) x),
                           'B',(SELECT jsonb_agg(x ORDER BY x) FROM unnest(b) x)) INTO result;
 RETURN result;
END $$;
CREATE FUNCTION rating_validation_b3b.eligible(i rating_validation_b3b.intents) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE pr public.profiles; ids uuid[]; BEGIN
 SELECT * INTO pr FROM public.profiles WHERE id=i.created_by FOR SHARE;
 IF NOT FOUND OR pr.is_active IS NOT TRUE OR pr.membership_status IS DISTINCT FROM 'APPROVED' OR pr.must_change_password IS TRUE THEN RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED'; END IF;
 SELECT array_agg(x::uuid) INTO ids FROM jsonb_array_elements_text((i.roster->'A')||(i.roster->'B')) x;
 PERFORM 1 FROM public.players WHERE id=ANY(ids) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.players WHERE id=ANY(ids) AND status='ACTIVE')<>4 THEN RAISE EXCEPTION 'ALL_PLAYERS_MUST_BE_ACTIVE'; END IF;
 IF pr.role<>'ADMIN' AND (pr.role<>'MEMBER' OR pr.player_id IS NULL OR NOT pr.player_id=ANY(ids) OR NOT EXISTS(SELECT 1 FROM public.players WHERE id=pr.player_id AND player_type='CLUB')) THEN RAISE EXCEPTION 'MEMBER_MUST_PARTICIPATE'; END IF;
END $$;
CREATE FUNCTION rating_validation_b3b.terminal(p uuid) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog SET timezone='UTC' AS $$
 SELECT EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=p AND kind<>'STARTED') OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=p AND body->>'prediction_identity_changed'='true')
$$;
CREATE FUNCTION rating_validation_b3b.source() RETURNS jsonb
LANGUAGE sql VOLATILE SET search_path=pg_catalog SET timezone='UTC' AS $$
SELECT jsonb_build_object(
'captured_at',clock_timestamp(),'timezone',current_setting('TimeZone'),
'players',(SELECT jsonb_agg(jsonb_build_object('id',id,'initial_rating',initial_rating,'current_rating',current_rating,'status',status,'player_type',player_type) ORDER BY id) FROM public.players),
'matches',(SELECT jsonb_agg(jsonb_build_object('id',m.id,'played_at',played_at,'played_date',played_at::date,'match_number',match_number,'match_type',m.match_type,'score_mode',score_mode,'team_a_score',team_a_score,'team_b_score',team_b_score) ORDER BY played_at,match_number,m.id) FROM public.matches m JOIN public.rating_match_weights w ON w.match_type=m.match_type WHERE m.status='APPROVED' AND w.weight>0),
'lineups',(SELECT jsonb_agg(jsonb_build_object('match_id',mp.match_id,'player_id',mp.player_id,'team',mp.team) ORDER BY mp.match_id,mp.team,mp.player_id) FROM public.match_players mp JOIN public.matches m ON m.id=mp.match_id JOIN public.rating_match_weights w ON w.match_type=m.match_type WHERE m.status='APPROVED' AND w.weight>0),
'events',(SELECT jsonb_agg(to_jsonb(e)-'created_at' ORDER BY match_id,player_id) FROM public.rating_events e),
'adjustments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'player_id',player_id,'amount',amount,'effective_at',effective_at,'created_at',created_at,'replay_order',replay_order,'correction_of_adjustment_id',correction_of_adjustment_id,'request_algorithm_version',request_algorithm_version) ORDER BY effective_at,replay_order,id) FROM public.rating_adjustments),'[]'::jsonb), 'adjustment_events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'adjustment_id',adjustment_id,'player_id',player_id,'algorithm_version',algorithm_version,'rating_before',rating_before,'requested_amount',requested_amount,'applied_delta',applied_delta,'rating_after',rating_after) ORDER BY adjustment_id,algorithm_version) FROM public.rating_adjustment_events),'[]'::jsonb),
'settings',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.rating_settings s),
'weights',(SELECT jsonb_agg(jsonb_build_object('match_type',w.match_type,'weight',w.weight) ORDER BY match_type) FROM public.rating_match_weights w),
'column_types',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('players','rating_events') AND a.attnum>0 AND NOT a.attisdropped AND (a.attname LIKE '%rating%' OR c.relname='rating_events')),
'function_hashes',(SELECT jsonb_object_agg(p.proname,md5(pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('_rebuild_ratings_internal','_approve_match_internal','_get_active_rating_version'))
) AS dataset
$$;
CREATE FUNCTION rating_validation_b3b.fingerprint(p_source jsonb) RETURNS text
LANGUAGE sql STABLE SET search_path=pg_catalog SET timezone='UTC' AS $$
 SELECT rating_validation_b3b.hash_json(jsonb_build_object('source',p_source-'captured_at',
 'ingress',(SELECT coalesce(jsonb_agg(jsonb_build_array(m.id,m.status,m.played_at,m.team_a_score,m.team_b_score,m.updated_at) ORDER BY m.id),'[]'::jsonb) FROM public.matches m),
 'lineups',(SELECT coalesce(jsonb_agg(jsonb_build_array(mp.match_id,mp.player_id,mp.team) ORDER BY mp.match_id,mp.team,mp.player_id),'[]'::jsonb) FROM public.match_players mp)))
$$;

CREATE FUNCTION public.create_rating_validation_intent(p_request_id uuid,p_team_a uuid[],p_team_b uuid[],p_match_type text DEFAULT 'CLUB_RATED',p_score_mode text DEFAULT 'POINTS',p_replaces_intent_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid; r jsonb; i rating_validation_b3b.intents; previous rating_validation_b3b.intents; pr public.profiles; n integer:=1; BEGIN
 PERFORM pg_advisory_xact_lock(726184501);
 a:=rating_validation_b3b.actor(); r:=rating_validation_b3b.roster(p_team_a,p_team_b);
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'REQUEST_ID_REQUIRED'; END IF;
 SELECT * INTO pr FROM public.profiles WHERE id=a;
 IF pr.role<>'ADMIN' THEN
  IF pr.role<>'MEMBER' OR pr.player_id IS NULL OR NOT pr.player_id=ANY(p_team_a||p_team_b)
  OR NOT EXISTS(SELECT 1 FROM public.players WHERE id=pr.player_id AND status='ACTIVE' AND player_type='CLUB')
  THEN RAISE EXCEPTION 'MEMBER_MUST_PARTICIPATE' USING ERRCODE='42501'; END IF;
 END IF;
 IF (SELECT count(*) FROM public.players WHERE id=ANY(p_team_a||p_team_b) AND status='ACTIVE')<>4 THEN RAISE EXCEPTION 'ALL_PLAYERS_MUST_BE_ACTIVE'; END IF;
 IF p_match_type IS NULL OR p_match_type NOT IN ('CLUB_RATED','FRIENDLY_RATED','TRAINING') OR p_score_mode IS NULL OR p_score_mode NOT IN ('POINTS','RESULT') THEN RAISE EXCEPTION 'INTENT_TYPE_INVALID'; END IF;
 IF p_replaces_intent_id IS NOT NULL THEN
  previous:=rating_validation_b3b.owner(p_replaces_intent_id);
  IF NOT rating_validation_b3b.terminal(previous.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=previous.id) THEN RAISE EXCEPTION 'NO_REINTENT_AFTER_RESULT'; END IF;
  n:=previous.version+1;
 END IF;
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE created_by=a AND request_id=p_request_id;
 IF FOUND THEN
  IF i.roster<>r OR i.match_type<>p_match_type OR i.score_mode<>p_score_mode OR i.replaces_intent_id IS DISTINCT FROM p_replaces_intent_id THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
 ELSE
  INSERT INTO rating_validation_b3b.intents(request_id,created_by,roster,match_type,score_mode,version,replaces_intent_id)
  VALUES(p_request_id,a,r,p_match_type,p_score_mode,n,p_replaces_intent_id) RETURNING * INTO i;
 END IF;
 RETURN jsonb_build_object('intent_id',i.id,'created_at',i.created_at,'rated',i.match_type<>'TRAINING','primary_population',i.match_type='CLUB_RATED' AND i.score_mode='POINTS');
END $$;

CREATE FUNCTION public.capture_rating_validation_snapshot(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; s jsonb; b rating_validation_b3b.boundaries; existing rating_validation_b3b.seals; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=p_intent_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTENT_NOT_FOUND'; END IF;
 IF i.match_type<>'CLUB_RATED' OR i.score_mode<>'POINTS' THEN RAISE EXCEPTION 'OUTSIDE_PRIMARY_POPULATION'; END IF;
 IF rating_validation_b3b.terminal(i.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RAISE EXCEPTION 'RESULT_KNOWN_OR_TERMINAL'; END IF;
 SELECT * INTO existing FROM rating_validation_b3b.seals WHERE intent_id=i.id;
 IF FOUND THEN RETURN jsonb_build_object('already_sealed',true,'seal_id',existing.id,'sealed_at',existing.sealed_at,'payload_hash',existing.payload_hash); END IF;
 IF EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED') THEN RAISE EXCEPTION 'STARTED_WITHOUT_SEAL'; END IF;
 PERFORM rating_validation_b3b.eligible(i);
 s:=rating_validation_b3b.source();
 INSERT INTO rating_validation_b3b.boundaries(intent_id,captured_at,source_text,fingerprint,source_hash,roster_hash)
 VALUES(i.id,(s->>'captured_at')::timestamptz,s::text,rating_validation_b3b.fingerprint(s),
 encode(sha256(convert_to(s::text,'UTF8')),'hex'),rating_validation_b3b.hash_json(i.roster)) RETURNING * INTO b;
 RETURN jsonb_build_object('boundary_id',b.id,'intent_id',i.id,'roster',i.roster,'captured_at',s->>'captured_at','source_text',b.source_text,'source_hash',b.source_hash);
END $$;

CREATE FUNCTION public.finalize_rating_validation_seal(p_boundary_id uuid,p_canonical_payload text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE b rating_validation_b3b.boundaries; i rating_validation_b3b.intents; p rating_validation_b3b.protocol;
 s rating_validation_b3b.seals; v jsonb:=p_canonical_payload::jsonb; current_source jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT * INTO b FROM rating_validation_b3b.boundaries WHERE id=p_boundary_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOUNDARY_NOT_FOUND'; END IF;
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=b.intent_id FOR UPDATE;
 SELECT * INTO p FROM rating_validation_b3b.protocol;
 IF (v->>'boundary_id')::uuid IS DISTINCT FROM b.id OR (v->>'intent_id')::uuid IS DISTINCT FROM i.id
 OR v->>'source_hash' IS DISTINCT FROM b.source_hash OR v->'roster' IS DISTINCT FROM i.roster
 OR v->>'manifest_sha256' IS DISTINCT FROM p.manifest_hash OR v->>'worker_sha256' IS DISTINCT FROM p.worker_hash
 OR v#>'{computed,frozen_parameters}' IS DISTINCT FROM p.manifest THEN RAISE EXCEPTION 'WORKER_CONTRACT_MISMATCH'; END IF;
 IF v#>'{computed,source_prefix}' IS DISTINCT FROM b.source_text::jsonb
 OR v#>>'{computed,forecast_created_at}' IS DISTINCT FROM b.source_text::jsonb->>'captured_at'
 THEN RAISE EXCEPTION 'WORKER_SOURCE_MISMATCH'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(v#>'{computed,forecasts}'))<>2
 OR (v#>>'{computed,forecasts,A}')::numeric NOT BETWEEN 0 AND 1
 OR (v#>>'{computed,forecasts,D}')::numeric NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'FORECAST_INVALID'; END IF;
 SELECT * INTO s FROM rating_validation_b3b.seals WHERE intent_id=i.id;
 IF FOUND THEN
  IF s.boundary_id<>b.id OR s.canonical_payload<>convert_to(p_canonical_payload,'UTF8') THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
  RETURN jsonb_build_object('seal_id',s.id,'sealed_at',s.sealed_at,'payload_hash',s.payload_hash,'idempotent',true);
 END IF;
 IF rating_validation_b3b.terminal(i.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RAISE EXCEPTION 'RESULT_KNOWN_OR_TERMINAL'; END IF;
 IF EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED') THEN RAISE EXCEPTION 'STARTED_WITHOUT_SEAL'; END IF;
 current_source:=rating_validation_b3b.source();
 IF rating_validation_b3b.fingerprint(current_source)<>b.fingerprint THEN RAISE EXCEPTION 'STALE_BOUNDARY'; END IF;
 PERFORM rating_validation_b3b.eligible(i);
 INSERT INTO rating_validation_b3b.seals(intent_id,boundary_id,canonical_payload,payload)
 VALUES(i.id,b.id,convert_to(p_canonical_payload,'UTF8'),v) RETURNING * INTO s;
 RETURN jsonb_build_object('seal_id',s.id,'sealed_at',s.sealed_at,'payload_hash',s.payload_hash,'idempotent',false);
END $$;

CREATE FUNCTION public.start_rating_validation_intent(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; existing rating_validation_b3b.events; BEGIN
 PERFORM pg_advisory_xact_lock(726184501); i:=rating_validation_b3b.owner(p_intent_id);
 SELECT * INTO existing FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED' ORDER BY recorded_at LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('started_at',existing.recorded_at,'sealed',EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id),'idempotent',true); END IF;
 IF rating_validation_b3b.terminal(i.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RAISE EXCEPTION 'START_NOT_ALLOWED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id) THEN
  INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'MISSED','Started before seal; core play/result may proceed');
 END IF;
 INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'STARTED','Server start receipt; no client timestamp') RETURNING * INTO existing;
 RETURN jsonb_build_object('started_at',existing.recorded_at,'sealed',EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id),'idempotent',false);
END $$;

CREATE FUNCTION public.bind_rating_validation_result(p_intent_id uuid,p_request_id uuid,p_played_at timestamptz,p_team_a_score integer,p_team_b_score integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; sub rating_validation_b3b.requests; a uuid; body jsonb;
 m jsonb; mid uuid; r text; received timestamptz:=clock_timestamp(); seal rating_validation_b3b.seals;
 pa uuid[]; pb uuid[]; BEGIN
 PERFORM pg_advisory_xact_lock(726184501); i:=rating_validation_b3b.owner(p_intent_id); a:=auth.uid();
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'REQUEST_ID_REQUIRED'; END IF;
 body:=jsonb_build_object('played_at',p_played_at,'team_a_score',p_team_a_score,'team_b_score',p_team_b_score,'roster',i.roster,'match_type',i.match_type,'score_mode',i.score_mode);
 SELECT * INTO sub FROM rating_validation_b3b.requests WHERE intent_id=i.id AND version=1;
 IF FOUND THEN
  IF sub.request_id<>p_request_id OR sub.body<>body OR sub.submitter<>a THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
  RETURN jsonb_build_object('match_id',sub.match_id,'first_seen_at',sub.received_at,'idempotent',true,
   'research_status',CASE WHEN NOT EXISTS(SELECT 1 FROM rating_validation_b3b.submissions WHERE intent_id=i.id AND version=1) THEN 'EVIDENCE_WRITE_FAILED'
   WHEN rating_validation_b3b.terminal(i.id) THEN 'MISSED PROSPECTIVE SEAL' ELSE 'RESULT_BOUND' END);
 END IF;
 -- DB receive time captured at function entry BEFORE any writer-lock wait, never from played_at.
 SELECT array_agg(x::uuid ORDER BY x) INTO pa FROM jsonb_array_elements_text(i.roster->'A') x;
 SELECT array_agg(x::uuid ORDER BY x) INTO pb FROM jsonb_array_elements_text(i.roster->'B') x;
 SELECT role INTO r FROM public.profiles WHERE id=a;
 IF r='ADMIN' THEN
  m:=public.create_pending_match(p_played_at,NULL,i.match_type,i.score_mode,p_team_a_score,p_team_b_score,NULL,NULL,NULL);
  mid:=(m->>'match_id')::uuid;
  PERFORM public.set_pending_match_players(mid,pa[1],pa[2],pb[1],pb[2]);
 ELSE
  m:=public.create_my_pending_match(p_played_at,i.match_type,i.score_mode,p_team_a_score,p_team_b_score,pa[1],pa[2],pb[1],pb[2],NULL);
  mid:=(m->>'match_id')::uuid;
 END IF;
 -- Mandatory operational receipt commits atomically with business Match, independent of telemetry.
 INSERT INTO rating_validation_b3b.requests(intent_id,request_id,submitter,version,match_id,received_at,body,match_number_at_binding)
 VALUES(i.id,p_request_id,a,1,mid,received,body,(SELECT match_number FROM public.matches WHERE id=mid));
 -- Research side effects isolated: their failure never rolls back legitimate creation.
 BEGIN
  INSERT INTO rating_validation_b3b.submissions(intent_id,request_id,submitter,version,match_id,received_at,body,body_hash)
  VALUES(i.id,p_request_id,a,1,mid,received,body,rating_validation_b3b.hash_json(body));
  SELECT * INTO seal FROM rating_validation_b3b.seals WHERE intent_id=i.id;
  IF NOT FOUND OR seal.sealed_at>=received OR p_played_at<=seal.sealed_at OR rating_validation_b3b.terminal(i.id) OR NOT EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED' AND recorded_at>=seal.sealed_at AND recorded_at<received) THEN
   INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'MISSED','No valid before-play committed seal');
  END IF;
 EXCEPTION WHEN OTHERS THEN
  -- If the evidence store itself is unavailable, return the committed business ID.
  -- Same-request retry resolves the mandatory operational receipt, never duplicates Match.
  RETURN jsonb_build_object('match_id',mid,'research_status','EVIDENCE_WRITE_FAILED','retry_safe',true);
 END;
 RETURN jsonb_build_object('match_id',mid,'first_seen_at',received,'research_status',
 CASE WHEN rating_validation_b3b.terminal(i.id) THEN 'MISSED PROSPECTIVE SEAL' ELSE 'RESULT_BOUND' END,'idempotent',false);
END $$;


CREATE FUNCTION public.void_rating_validation_intent(p_intent_id uuid,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; BEGIN
 PERFORM pg_advisory_xact_lock(726184501); i:=rating_validation_b3b.owner(p_intent_id);
 IF EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RAISE EXCEPTION 'RESULT_ALREADY_BOUND'; END IF;
 IF p_reason IS NULL OR btrim(p_reason)='' OR length(btrim(p_reason))>1000 THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF;
 IF NOT rating_validation_b3b.terminal(i.id) THEN
  INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'ABANDONED',btrim(p_reason));
 END IF;
 RETURN jsonb_build_object('intent_id',i.id,'status','VOID');
END $$;

CREATE FUNCTION rating_validation_b3b.business_approved(p_match uuid) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM public.matches m WHERE m.id=p_match AND m.status='APPROVED' AND
  (m.opponent_rejected_by IS NULL OR EXISTS(SELECT 1 FROM public.audit_logs al WHERE al.record_id=m.id AND al.table_name='matches' AND al.action='APPROVE_MATCH')))
$$;

CREATE FUNCTION public.score_rating_validation_forecast(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; s rating_validation_b3b.seals; sub rating_validation_b3b.submissions;
 sc rating_validation_b3b.scores; m public.matches; r jsonb; actual numeric; output jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=p_intent_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTENT_NOT_FOUND'; END IF;
 IF rating_validation_b3b.terminal(i.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id AND body->>'prediction_identity_changed'='true') THEN RETURN jsonb_build_object('status','EXCLUDED'); END IF;
 SELECT * INTO sub FROM rating_validation_b3b.submissions WHERE intent_id=i.id ORDER BY version DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','WAITING_RESULT'); END IF;
 IF sub.version<>(SELECT max(version) FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RETURN jsonb_build_object('status','EVIDENCE_WRITE_FAILED'); END IF;
 SELECT * INTO s FROM rating_validation_b3b.seals WHERE intent_id=i.id;
 IF NOT FOUND OR s.sealed_at>=sub.received_at THEN RETURN jsonb_build_object('status','MISSED'); END IF;
 SELECT * INTO m FROM public.matches WHERE id=sub.match_id FOR UPDATE;
 IF NOT FOUND OR m.status IN ('VOIDED','INVALID') THEN
  INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'ADJUDICATION','Business match missing, invalid or voided');
  RETURN jsonb_build_object('status','EXCLUDED');
 END IF;
 IF NOT rating_validation_b3b.business_approved(m.id) THEN RETURN jsonb_build_object('status','WAITING_APPROVAL'); END IF;
 SELECT jsonb_build_object('A',jsonb_agg(player_id ORDER BY player_id) FILTER(WHERE team='A'),
                           'B',jsonb_agg(player_id ORDER BY player_id) FILTER(WHERE team='B')) INTO r FROM public.match_players WHERE match_id=m.id;
 IF r IS DISTINCT FROM i.roster OR m.match_type<>i.match_type OR m.score_mode<>i.score_mode OR m.played_at IS DISTINCT FROM (sub.body->>'played_at')::timestamptz
 OR m.team_a_score IS DISTINCT FROM (sub.body->>'team_a_score')::integer OR m.team_b_score IS DISTINCT FROM (sub.body->>'team_b_score')::integer THEN
  INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(i.id,'ADJUDICATION','Business result differs from captured revision');
  RETURN jsonb_build_object('status','EXCLUDED');
 END IF;
 SELECT * INTO sc FROM rating_validation_b3b.scores WHERE intent_id=i.id;
 IF FOUND THEN RETURN sc.payload; END IF;
 actual:=m.team_a_score::numeric/(m.team_a_score+m.team_b_score);
 output:=jsonb_build_object('status','SCORED','seal_hash',s.payload_hash,'version',sub.version,
 'actual_share',actual,'mse_A',power((s.payload#>>'{computed,forecasts,A}')::numeric-actual,2),
 'mse_D',power((s.payload#>>'{computed,forecasts,D}')::numeric-actual,2),
 'classification',s.payload#>>'{computed,classification}');
 INSERT INTO rating_validation_b3b.scores(intent_id,submission_id,seal_id,payload) VALUES(i.id,sub.id,s.id,output);
 RETURN output;
END $$;

CREATE FUNCTION public.get_rating_validation_status(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid; i rating_validation_b3b.intents; result jsonb; BEGIN
 a:=rating_validation_b3b.actor();
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=a AND role='ADMIN') THEN RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=p_intent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTENT_NOT_FOUND'; END IF;
 SELECT jsonb_build_object('intent_id',i.id,'created_at',i.created_at,'rated',i.match_type<>'TRAINING',
 'status',CASE WHEN rating_validation_b3b.terminal(i.id) THEN 'VOID' WHEN EXISTS(SELECT 1 FROM rating_validation_b3b.submissions WHERE intent_id=i.id) THEN 'RESULT_BOUND'
 WHEN EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id) THEN 'SEALED' ELSE 'OPEN' END,
 'sealed',EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id),
 'scored',EXISTS(SELECT 1 FROM rating_validation_b3b.scores WHERE intent_id=i.id)) INTO result;
 RETURN result;
END $$;

CREATE FUNCTION public.get_my_rating_validation_intent(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid:=rating_validation_b3b.actor(); i rating_validation_b3b.intents; BEGIN
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=p_intent_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTENT_NOT_FOUND'; END IF;
 IF i.created_by<>a AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=a AND role='ADMIN') THEN RAISE EXCEPTION 'INTENT_OWNER_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('intent_id',i.id,'created_at',i.created_at,'sealed',EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=i.id),
 'started',EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED'),
 'missed_or_void',rating_validation_b3b.terminal(i.id));
END $$;

CREATE FUNCTION public.export_rating_validation_evidence() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
BEGIN
 PERFORM rating_validation_b3b.worker();
 RETURN jsonb_build_object('format','B3B_EVIDENCE_1','captured_at',clock_timestamp(),
 'manifest_hash',(SELECT manifest_hash FROM rating_validation_b3b.protocol),
 'worker_hash',(SELECT worker_hash FROM rating_validation_b3b.protocol),
 'rows',(SELECT coalesce(jsonb_agg(jsonb_build_object('intent_id',i.id,'primary_population',i.match_type='CLUB_RATED' AND i.score_mode='POINTS',
 'sealed',s.id IS NOT NULL,'sealed_at',s.sealed_at,'seal_hash',s.payload_hash,
 'match_id',req.match_id,'first_result_at',req.received_at,'scored',sc.id IS NOT NULL,
 'void',(EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind IN ('VOID','ABANDONED','ADJUDICATION')) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id AND body->>'prediction_identity_changed'='true')),
 'missed',req.id IS NOT NULL AND (s.id IS NULL OR EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='MISSED') OR NOT EXISTS(SELECT 1 FROM rating_validation_b3b.submissions WHERE intent_id=i.id AND version=1)),
 'classification',s.payload#>>'{computed,classification}',
 'business_valid',rating_validation_b3b.business_approved(m.id)
  AND m.team_a_score IS NOT DISTINCT FROM (latest.body->>'team_a_score')::integer
  AND m.team_b_score IS NOT DISTINCT FROM (latest.body->>'team_b_score')::integer
  AND m.played_at IS NOT DISTINCT FROM (latest.body->>'played_at')::timestamptz
  AND m.match_type=i.match_type AND m.score_mode=i.score_mode
  AND (SELECT jsonb_build_object('A',jsonb_agg(player_id ORDER BY player_id) FILTER(WHERE team='A'),'B',jsonb_agg(player_id ORDER BY player_id) FILTER(WHERE team='B')) FROM public.match_players WHERE match_id=m.id)=i.roster,
 'score',sc.payload) ORDER BY i.created_at,i.id),'[]'::jsonb)
 FROM rating_validation_b3b.intents i
 LEFT JOIN rating_validation_b3b.seals s ON s.intent_id=i.id
 LEFT JOIN rating_validation_b3b.requests req ON req.intent_id=i.id AND req.version=1
 LEFT JOIN LATERAL(SELECT * FROM rating_validation_b3b.requests WHERE intent_id=i.id ORDER BY version DESC LIMIT 1) latest ON true
 LEFT JOIN public.matches m ON m.id=req.match_id
 LEFT JOIN rating_validation_b3b.scores sc ON sc.intent_id=i.id));
END $$;

-- B3C closure section of the standalone B3B draft. Never applied to production.
CREATE TABLE rating_validation_b3b.edit_receipts (
 actor uuid NOT NULL, request_id uuid NOT NULL, match_id uuid NOT NULL,
 patch jsonb NOT NULL, response jsonb NOT NULL,
 received_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(actor,request_id)
);
ALTER TABLE rating_validation_b3b.edit_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE rating_validation_b3b.edit_receipts FORCE ROW LEVEL SECURITY;
CREATE TRIGGER immutable_rows BEFORE UPDATE OR DELETE ON rating_validation_b3b.edit_receipts FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.immutable();
CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON rating_validation_b3b.edit_receipts FOR EACH STATEMENT EXECUTE FUNCTION rating_validation_b3b.immutable();
-- Private transaction context, not linkage or history. No client grants/policies.
CREATE TABLE rating_validation_b3b.edit_context (
 pid integer NOT NULL, xid bigint NOT NULL, match_id uuid NOT NULL, actor uuid NOT NULL,
 PRIMARY KEY(pid,xid)
);
ALTER TABLE rating_validation_b3b.edit_context ENABLE ROW LEVEL SECURITY;
ALTER TABLE rating_validation_b3b.edit_context FORCE ROW LEVEL SECURITY;

CREATE FUNCTION rating_validation_b3b.match_access(p_match_id uuid,p_edit boolean)
RETURNS public.matches LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a uuid:=rating_validation_b3b.actor(); m public.matches; pr public.profiles; BEGIN
 IF p_match_id IS NULL THEN RAISE EXCEPTION 'MATCH_ID_REQUIRED'; END IF;
 SELECT * INTO pr FROM public.profiles WHERE id=a;
 SELECT * INTO m FROM public.matches WHERE id=p_match_id;
 IF NOT FOUND OR (pr.role='ADMIN' OR (pr.role='MEMBER' AND
  (m.created_by=a OR (NOT p_edit AND EXISTS(SELECT 1 FROM public.match_players mp
   WHERE mp.match_id=m.id AND (mp.player_id=pr.player_id OR mp.partner_player_id=pr.player_id)))))) IS NOT TRUE
 THEN RAISE EXCEPTION 'MATCH_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 RETURN m;
END $$;

CREATE FUNCTION public.get_rating_validation_intent_for_match(p_match_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE m public.matches; pr public.profiles; req rating_validation_b3b.requests;
 can_edit boolean; sealed boolean; terminal boolean; BEGIN
 m:=rating_validation_b3b.match_access(p_match_id,false);
 SELECT * INTO pr FROM public.profiles WHERE id=auth.uid();
 can_edit:=m.status='PENDING' AND (pr.role='ADMIN' OR (m.created_by=pr.id
  AND m.opponent_rejected_by IS NOT NULL AND EXISTS(SELECT 1 FROM public.players WHERE id=pr.player_id AND status='ACTIVE' AND player_type='CLUB')
  AND EXISTS(SELECT 1 FROM public.audit_logs WHERE record_id=m.id AND table_name='matches' AND action='CREATE_MY_PENDING_MATCH' AND user_id=pr.id)));
 SELECT * INTO req FROM rating_validation_b3b.requests WHERE match_id=m.id AND version=1;
 IF NOT FOUND THEN RETURN jsonb_build_object('match_id',m.id,'intent_id',NULL,'linked',false,
  'routing','LEGACY','can_edit',can_edit,'sealed',false,'result_bound',false,
  'score_only_resubmit_allowed',false,'roster_change_policy','LEGACY'); END IF;
 sealed:=EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=req.intent_id);
 terminal:=rating_validation_b3b.terminal(req.intent_id);
 RETURN jsonb_build_object('match_id',m.id,'intent_id',req.intent_id,'linked',true,
  'routing','SERVER_ROUTED','can_edit',can_edit,'sealed',sealed,'result_bound',true,
  'intent_status',CASE WHEN terminal THEN 'TERMINAL' ELSE 'RESULT_BOUND' END,
  'evidence_submission_present',EXISTS(SELECT 1 FROM rating_validation_b3b.submissions WHERE intent_id=req.intent_id AND version=1),
  'first_result_at',req.received_at,'score_only_resubmit_allowed',can_edit AND sealed AND NOT terminal,
  'roster_change_policy','INVALIDATE_NO_RESEAL_AFTER_RESULT');
END $$;

CREATE FUNCTION rating_validation_b3b.guard_edit_route() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE mid uuid; source_changed boolean:=true; BEGIN
 IF TG_TABLE_NAME='matches' THEN
  mid:=OLD.id;
  source_changed:=OLD.status='PENDING' AND NEW.status='PENDING' AND
   (ROW(NEW.played_at,NEW.match_number,NEW.match_type,NEW.score_mode,NEW.team_a_score,NEW.team_b_score,NEW.tournament_id,NEW.league_id,NEW.notes)
   IS DISTINCT FROM ROW(OLD.played_at,OLD.match_number,OLD.match_type,OLD.score_mode,OLD.team_a_score,OLD.team_b_score,OLD.tournament_id,OLD.league_id,OLD.notes)
   OR (OLD.opponent_rejected_by IS NOT NULL AND NEW.opponent_rejected_by IS NULL));
 ELSE
  mid:=CASE WHEN TG_OP='DELETE' THEN OLD.match_id ELSE NEW.match_id END;
  source_changed:=EXISTS(SELECT 1 FROM public.matches WHERE id=mid AND status='PENDING');
  IF TG_OP='UPDATE' AND OLD.match_id IS DISTINCT FROM NEW.match_id AND
    EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE match_id=OLD.match_id AND version=1)
  THEN RAISE EXCEPTION 'RATING_VALIDATION_ROUTING_REQUIRED'; END IF;
 END IF;
 IF source_changed AND EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE match_id=mid AND version=1)
 AND NOT EXISTS(SELECT 1 FROM rating_validation_b3b.edit_context WHERE pid=pg_backend_pid() AND xid=txid_current() AND match_id=mid AND actor=auth.uid())
 THEN RAISE EXCEPTION 'RATING_VALIDATION_ROUTING_REQUIRED' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
CREATE TRIGGER b3c_match_edit_route BEFORE UPDATE ON public.matches FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.guard_edit_route();
CREATE TRIGGER b3c_lineup_edit_route BEFORE INSERT OR UPDATE OR DELETE ON public.match_players FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.guard_edit_route();

CREATE FUNCTION public.edit_resubmit_rating_validation_match(p_match_id uuid,p_request_id uuid,p_patch jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE a uuid:=rating_validation_b3b.actor(); pr public.profiles; m public.matches;
 first_req rating_validation_b3b.requests; receipt rating_validation_b3b.edit_receipts;
 roster jsonb; original_roster jsonb; ta uuid[]; tb uuid[]; patch_body jsonb; result jsonb; delegate jsonb;
 at_ timestamptz; typ text; mode_ text; sa integer; sb integer; notes_ text; num integer; tour uuid; league uuid;
 linked boolean; identity_changed boolean; route text; n integer; received timestamptz:=clock_timestamp();
BEGIN
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'REQUEST_ID_REQUIRED'; END IF;
 IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' THEN RAISE EXCEPTION 'PATCH_OBJECT_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_patch) k WHERE k NOT IN
 ('played_at','team_a_score','team_b_score','team_a','team_b','match_type','score_mode','notes','match_number','tournament_id','league_id')) THEN RAISE EXCEPTION 'PATCH_FIELD_NOT_ALLOWED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_patch) kv WHERE kv.key NOT IN ('notes','match_number','tournament_id','league_id') AND kv.value='null'::jsonb) THEN RAISE EXCEPTION 'REQUIRED_FIELD_CANNOT_CLEAR'; END IF;
 IF p_patch ? 'notes' AND jsonb_typeof(p_patch->'notes') NOT IN ('string','null') THEN RAISE EXCEPTION 'NOTES_STRING_OR_NULL_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_patch) kv WHERE kv.key IN ('team_a_score','team_b_score','match_number') AND kv.value<>'null'::jsonb AND (jsonb_typeof(kv.value)<>'number' OR (kv.value::text)::numeric<>trunc((kv.value::text)::numeric))) THEN RAISE EXCEPTION 'INTEGER_FIELD_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(726184501);
 m:=rating_validation_b3b.match_access(p_match_id,true);
 SELECT * INTO m FROM public.matches WHERE id=m.id FOR UPDATE;
 SELECT * INTO pr FROM public.profiles WHERE id=a;
 SELECT * INTO receipt FROM rating_validation_b3b.edit_receipts WHERE actor=a AND request_id=p_request_id;
 IF FOUND THEN
  IF receipt.match_id<>m.id OR receipt.patch<>p_patch THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
  RETURN receipt.response||jsonb_build_object('idempotent',true);
 END IF;
 IF m.status<>'PENDING' THEN RAISE EXCEPTION 'MATCH_NOT_PENDING'; END IF;
 IF pr.role<>'ADMIN' AND m.opponent_rejected_by IS NULL THEN RAISE EXCEPTION 'MATCH_NOT_REJECTED'; END IF;
 IF pr.role<>'ADMIN' AND p_patch ?| ARRAY['match_number','tournament_id','league_id'] THEN RAISE EXCEPTION 'ADMIN_METADATA_REQUIRED' USING ERRCODE='42501'; END IF;
 SELECT * INTO first_req FROM rating_validation_b3b.requests WHERE match_id=m.id AND version=1;
 linked:=FOUND;
 IF linked AND EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=first_req.intent_id AND request_id=p_request_id) THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
 SELECT array_agg(player_id ORDER BY player_id) FILTER(WHERE team='A'),array_agg(player_id ORDER BY player_id) FILTER(WHERE team='B') INTO ta,tb FROM public.match_players WHERE match_id=m.id;
 IF p_patch ? 'team_a' THEN SELECT array_agg(x::uuid ORDER BY x::uuid) INTO ta FROM jsonb_array_elements_text(p_patch->'team_a') x; END IF;
 IF p_patch ? 'team_b' THEN SELECT array_agg(x::uuid ORDER BY x::uuid) INTO tb FROM jsonb_array_elements_text(p_patch->'team_b') x; END IF;
 roster:=rating_validation_b3b.roster(ta,tb);
 at_:=CASE WHEN p_patch ? 'played_at' THEN (p_patch->>'played_at')::timestamptz ELSE m.played_at END;
 typ:=CASE WHEN p_patch ? 'match_type' THEN p_patch->>'match_type' ELSE m.match_type END;
 mode_:=CASE WHEN p_patch ? 'score_mode' THEN p_patch->>'score_mode' ELSE m.score_mode END;
 sa:=CASE WHEN p_patch ? 'team_a_score' THEN (p_patch->>'team_a_score')::integer ELSE m.team_a_score END;
 sb:=CASE WHEN p_patch ? 'team_b_score' THEN (p_patch->>'team_b_score')::integer ELSE m.team_b_score END;
 notes_:=CASE WHEN p_patch ? 'notes' THEN nullif(btrim(p_patch->>'notes'),'') ELSE m.notes END;
 num:=CASE WHEN p_patch ? 'match_number' THEN (p_patch->>'match_number')::integer ELSE m.match_number END;
 tour:=CASE WHEN p_patch ? 'tournament_id' THEN (p_patch->>'tournament_id')::uuid ELSE m.tournament_id END;
 league:=CASE WHEN p_patch ? 'league_id' THEN (p_patch->>'league_id')::uuid ELSE m.league_id END;
 patch_body:=jsonb_build_object('played_at',at_,'team_a_score',sa,'team_b_score',sb,'roster',roster,'match_type',typ,'score_mode',mode_,'tournament_id',tour,'league_id',league,'match_number',num,'notes',notes_);
 INSERT INTO rating_validation_b3b.edit_context VALUES(pg_backend_pid(),txid_current(),m.id,a);
 IF pr.role='ADMIN' THEN
  delegate:=public.update_pending_match(m.id,at_,num,typ,mode_,sa,sb,tour,league,notes_);
  IF p_patch ?| ARRAY['team_a','team_b'] THEN PERFORM public.set_pending_match_players(m.id,ta[1],ta[2],tb[1],tb[2]); END IF;
 ELSE
  delegate:=public.update_my_rejected_pending_match(m.id,at_,typ,mode_,sa,sb,ta[1],ta[2],tb[1],tb[2],notes_);
  PERFORM public.resubmit_my_rejected_match(m.id);
 END IF;
 -- Legacy delegates normalize notes. Omission must preserve even imported raw text.
 IF NOT (p_patch ? 'notes') AND m.notes IS DISTINCT FROM (SELECT notes FROM public.matches WHERE id=m.id) THEN
  INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_data,new_data,reason,created_at)
  SELECT a,'PRESERVE_OMITTED_MATCH_NOTES','matches',m.id,jsonb_build_object('notes',notes),jsonb_build_object('notes',m.notes),
   'B3C JSON patch omitted notes; preserve original value',clock_timestamp() FROM public.matches WHERE id=m.id;
  UPDATE public.matches SET notes=m.notes WHERE id=m.id;
 END IF;
 DELETE FROM rating_validation_b3b.edit_context WHERE pid=pg_backend_pid() AND xid=txid_current();
 route:='LEGACY'; n:=NULL;
 IF linked THEN
  SELECT i.roster INTO original_roster FROM rating_validation_b3b.intents i WHERE i.id=first_req.intent_id;
  identity_changed:=roster<>original_roster OR at_ IS DISTINCT FROM (first_req.body->>'played_at')::timestamptz
    OR typ IS DISTINCT FROM first_req.body->>'match_type' OR mode_ IS DISTINCT FROM first_req.body->>'score_mode'
    OR num IS DISTINCT FROM first_req.match_number_at_binding OR tour IS NOT NULL OR league IS NOT NULL;
  patch_body:=patch_body||jsonb_build_object('prediction_identity_changed',identity_changed);
  SELECT max(version)+1 INTO n FROM rating_validation_b3b.requests WHERE intent_id=first_req.intent_id;
  INSERT INTO rating_validation_b3b.requests(intent_id,request_id,submitter,version,match_id,received_at,body)
  VALUES(first_req.intent_id,p_request_id,a,n,m.id,received,patch_body);
  route:=CASE WHEN identity_changed OR rating_validation_b3b.terminal(first_req.intent_id) THEN 'LINKED_INVALIDATED'
    WHEN NOT EXISTS(SELECT 1 FROM rating_validation_b3b.seals WHERE intent_id=first_req.intent_id) THEN 'LINKED_MISSED'
    WHEN sa IS DISTINCT FROM m.team_a_score OR sb IS DISTINCT FROM m.team_b_score THEN 'SEALED_SCORE_ONLY' ELSE 'SEALED_METADATA_ONLY' END;
  BEGIN
   INSERT INTO rating_validation_b3b.submissions(intent_id,request_id,submitter,version,match_id,received_at,body,body_hash)
   VALUES(first_req.intent_id,p_request_id,a,n,m.id,received,patch_body,rating_validation_b3b.hash_json(patch_body));
   IF identity_changed THEN INSERT INTO rating_validation_b3b.events(intent_id,kind,reason) VALUES(first_req.intent_id,'VOID','Predictive identity changed after first result; no reseal'); END IF;
  EXCEPTION WHEN OTHERS THEN
   -- Durable request survives, scorer detects missing/new mismatched evidence fail closed.
   route:='EVIDENCE_WRITE_FAILED';
  END;
 END IF;
 result:=jsonb_build_object('match_id',m.id,'intent_id',first_req.intent_id,'routing',route,'version',n,'idempotent',false,
  'action',CASE WHEN pr.role='ADMIN' THEN 'ADMIN_EDIT_PENDING' ELSE 'CREATOR_RESUBMIT' END,'received_at',received,'status','PENDING');
 INSERT INTO rating_validation_b3b.edit_receipts(actor,request_id,match_id,patch,response,received_at) VALUES(a,p_request_id,m.id,p_patch,result,received);
 RETURN result;
END $$;

-- Original seven-argument caller stays supported; no overload or ambiguous defaults.
CREATE FUNCTION public.resubmit_rating_validation_result(p_intent_id uuid,p_request_id uuid,p_played_at timestamptz,p_team_a_score integer,p_team_b_score integer,p_team_a uuid[],p_team_b uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE i rating_validation_b3b.intents; mid uuid; BEGIN
 PERFORM pg_advisory_xact_lock(726184501);
 i:=rating_validation_b3b.owner(p_intent_id);
 SELECT match_id INTO mid FROM rating_validation_b3b.requests WHERE intent_id=i.id AND version=1;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESULT_NOT_BOUND'; END IF;
 RETURN public.edit_resubmit_rating_validation_match(mid,p_request_id,jsonb_build_object('played_at',p_played_at,
  'team_a_score',p_team_a_score,'team_b_score',p_team_b_score,'team_a',p_team_a,'team_b',p_team_b));
END $$;
REVOKE ALL ON FUNCTION public.get_rating_validation_intent_for_match(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_rating_validation_intent_for_match(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.edit_resubmit_rating_validation_match(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.edit_resubmit_rating_validation_match(uuid,uuid,jsonb) TO authenticated;

REVOKE ALL ON ALL TABLES IN SCHEMA rating_validation_b3b FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA rating_validation_b3b FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.create_rating_validation_intent(uuid,uuid[],uuid[],text,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.create_rating_validation_intent(uuid,uuid[],uuid[],text,text,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.bind_rating_validation_result(uuid,uuid,timestamptz,integer,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.bind_rating_validation_result(uuid,uuid,timestamptz,integer,integer) TO authenticated;
REVOKE ALL ON FUNCTION public.resubmit_rating_validation_result(uuid,uuid,timestamptz,integer,integer,uuid[],uuid[]) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.resubmit_rating_validation_result(uuid,uuid,timestamptz,integer,integer,uuid[],uuid[]) TO authenticated;
REVOKE ALL ON FUNCTION public.void_rating_validation_intent(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.void_rating_validation_intent(uuid,text) TO authenticated;
REVOKE ALL ON FUNCTION public.get_rating_validation_status(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_rating_validation_status(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.capture_rating_validation_snapshot(uuid) FROM PUBLIC,anon,authenticated,service_role;
