e857347df1c9736569cdded34b3886df201f06de65dfbad0", "status": "RESEARCH ONLY - NOT PRODUCTION RECOMMENDATION"}'::jsonb THEN RAISE EXCEPTION 'BASELINE_MANIFEST_HASH_MISMATCH'; END IF;
 IF p.worker_hash IS DISTINCT FROM '947a8cbaadd76618e933337613b37eb35c9bf77c24b1c319354e462e9165fb56' THEN RAISE EXCEPTION 'WORKER_CONTRACT_MISMATCH'; END IF;
