ALTER FUNCTION public.capture_rating_validation_snapshot(uuid) SET SCHEMA rating_validation_b3b;
ALTER FUNCTION rating_validation_b3b.capture_rating_validation_snapshot(uuid) RENAME TO capture_snapshot_core;
ALTER FUNCTION public.finalize_rating_validation_seal(uuid,text) SET SCHEMA rating_validation_b3b;
ALTER FUNCTION rating_validation_b3b.finalize_rating_validation_seal(uuid,text) RENAME TO finalize_seal_core;
CREATE OR REPLACE FUNCTION rating_validation_b3b.finalize_seal_core(p_boundary_id uuid,p_canonical_payload text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE b rating_validation_b3b.boundaries; i rating_validation_b3b.intents; p rating_validation_b3b.protocol;
 s rating_validation_b3b.seals; v jsonb:=p_canonical_payload::jsonb; current_source jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT * INTO b FROM rating_validation_b3b.boundaries WHERE id=p_boundary_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOUNDARY_NOT_FOUND'; END IF;
 SELECT * INTO i FROM rating_validation_b3b.intents WHERE id=b.intent_id FOR UPDATE;
 SELECT singleton,manifest,manifest_hash,worker_hash INTO p FROM rating_validation_b3b.selected_protocol();
 IF (v->>'boundary_id')::uuid IS DISTINCT FROM b.id OR (v->>'intent_id')::uuid IS DISTINCT FROM i.id
 OR v->>'source_hash' IS DISTINCT FROM b.source_hash OR v->'roster' IS DISTINCT FROM i.roster
 OR v->>'manifest_sha256' IS DISTINCT FROM p.manifest_hash OR v->>'worker_sha256' IS DISTINCT FROM p.worker_hash
 OR v#>'{computed,frozen_parameters}' IS DISTINCT FROM p.manifest THEN RAISE EXCEPTION 'WORKER_CONTRACT_MISMATCH'; END IF;
 IF v#>'{computed,source_prefix}' IS DISTINCT FROM b.source_text::jsonb
 OR v#>>'{computed,forecast_created_at}' IS DISTINCT FROM b.source_text::jsonb->>'captured_at'
 THEN RAISE EXCEPTION 'WORKER_SOURCE_MISMATCH'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(v#>'{computed,forecasts}'))<>2
 OR (v#>>'{computed,forecasts,A}')::numeric NOT BETWEEN 0 AND 1
 OR (v#>>'{computed,forecasts,D}')::numeric NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'FORECAST_INVALID'; END IF;
 SELECT * INTO s FROM rating_validation_b3b.seals WHERE intent_id=i.id;
 IF FOUND THEN
  IF s.boundary_id<>b.id OR s.canonical_payload<>convert_to(p_canonical_payload,'UTF8') THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;
  RETURN jsonb_build_object('seal_id',s.id,'sealed_at',s.sealed_at,'payload_hash',s.payload_hash,'idempotent',true);
 END IF;
 IF rating_validation_b3b.terminal(i.id) OR EXISTS(SELECT 1 FROM rating_validation_b3b.requests WHERE intent_id=i.id) THEN RAISE EXCEPTION 'RESULT_KNOWN_OR_TERMINAL'; END IF;
 IF EXISTS(SELECT 1 FROM rating_validation_b3b.events WHERE intent_id=i.id AND kind='STARTED') THEN RAISE EXCEPTION 'STARTED_WITHOUT_SEAL'; END IF;
 current_source:=rating_validation_b3b.source();
 IF rating_validation_b3b.fingerprint(current_source)<>b.fingerprint THEN RAISE EXCEPTION 'STALE_BOUNDARY'; END IF;
 PERFORM rating_validation_b3b.eligible(i);
 INSERT INTO rating_validation_b3b.seals(intent_id,boundary_id,canonical_payload,payload)
 VALUES(i.id,b.id,convert_to(p_canonical_payload,'UTF8'),v) RETURNING * INTO s;
 RETURN jsonb_build_object('seal_id',s.id,'sealed_at',s.sealed_at,'payload_hash',s.payload_hash,'idempotent',false);
END $$;
REVOKE ALL ON FUNCTION rating_validation_b3b.capture_snapshot_core(uuid),rating_validation_b3b.finalize_seal_core(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.capture_rating_validation_snapshot(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE v jsonb; c jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT baseline_context INTO c FROM rating_validation_b3b.selected_protocol();
 IF c IS DISTINCT FROM '{"baseline": "analysis/rating-calibration01-a/dataset.json", "baseline_sha256": "e695f4ca2919429df058b467686d8c2345d4ccc09ab2d60663800785082fad07", "config": "analysis/rating-calibration01-b/checkpoint_config.json", "config_sha256": "4683e2656f52982c8f4916a905c72255ec4c5ebb6183e596c6cfdc4f5c65b9b5", "counts": {"lineups": 240, "matches": 60, "players": 25}, "environment": "production", "identity": "pick-production-baseline-v1", "manifest": "analysis/rating-calibration01-b/frozen_candidates.json", "manifest_sha256": "348d713d0e6d9a88bac960f009a683ae19aa1c7679f34a76fc28394ef8896ebf", "project_ref": "bflwaqlvnesuqoyikxar", "version": 1}'::jsonb THEN RAISE EXCEPTION 'BASELINE_CONTEXT_MISMATCH'; END IF;
 v:=rating_validation_b3b.capture_snapshot_core(p_intent_id);
 IF v->>'boundary_id' IS NOT NULL THEN
  INSERT INTO rating_validation_b3b.boundary_context VALUES((v->>'boundary_id')::uuid,c);
  RETURN v||jsonb_build_object('baseline_context',c);
 END IF;
 RETURN v;
END $$;
CREATE FUNCTION public.finalize_rating_validation_seal(p_boundary_id uuid,p_canonical_payload text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE c jsonb; bc jsonb; v jsonb:=p_canonical_payload::jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 SELECT baseline_context INTO c FROM rating_validation_b3b.selected_protocol();
 SELECT baseline_context INTO bc FROM rating_validation_b3b.boundary_context WHERE boundary_id=p_boundary_id;
 IF c IS DISTINCT FROM '{"baseline": "analysis/rating-calibration01-a/dataset.json", "baseline_sha256": "e695f4ca2919429df058b467686d8c2345d4ccc09ab2d60663800785082fad07", "config": "analysis/rating-calibration01-b/checkpoint_config.json", "config_sha256": "4683e2656f52982c8f4916a905c72255ec4c5ebb6183e596c6cfdc4f5c65b9b5", "counts": {"lineups": 240, "matches": 60, "players": 25}, "environment": "production", "identity": "pick-production-baseline-v1", "manifest": "analysis/rating-calibration01-b/frozen_candidates.json", "manifest_sha256": "348d713d0e6d9a88bac960f009a683ae19aa1c7679f34a76fc28394ef8896ebf", "project_ref": "bflwaqlvnesuqoyikxar", "version": 1}'::jsonb OR bc IS DISTINCT FROM c
 OR v#>'{computed,baseline_context}' IS DISTINCT FROM c
 OR v#>>'{computed,evidence_environment}' IS DISTINCT FROM c->>'environment'
 THEN RAISE EXCEPTION 'BASELINE_CONTEXT_MISMATCH'; END IF;
 RETURN rating_validation_b3b.finalize_seal_core(p_boundary_id,p_canonical_payload);
END $$;
REVOKE ALL ON FUNCTION public.capture_rating_validation_snapshot(uuid),public.finalize_rating_validation_seal(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.capture_rating_validation_snapshot(uuid),public.finalize_rating_validation_seal(uuid,text) TO service_role;
ALTER FUNCTION public.export_rating_validation_evidence() SET SCHEMA rating_validation_b3b;
ALTER FUNCTION rating_validation_b3b.export_rating_validation_evidence() RENAME TO export_evidence_core;
REVOKE ALL ON FUNCTION rating_validation_b3b.export_evidence_core() FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.export_rating_validation_evidence() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE v jsonb; p rating_validation_b3b.environment_protocol; history jsonb; BEGIN
 -- Keep the deployed service-only authorization, including legacy core checks.
 PERFORM rating_validation_b3b.worker();
 p:=rating_validation_b3b.selected_protocol();
 v:=rating_validation_b3b.export_evidence_core();
 SELECT coalesce(jsonb_agg(row_data.value||jsonb_build_object(
  'binding_status',CASE WHEN bc.boundary_id IS NULL THEN 'LEGACY_UNSCOPED' ELSE 'ENVIRONMENT_BOUND' END,
  'baseline_context',bc.baseline_context,
  'baseline_identity',bc.baseline_context->>'identity',
  'baseline_version',bc.baseline_context->'version',
  'manifest_hash',s.payload->>'manifest_sha256',
  'worker_hash',s.payload->>'worker_sha256') ORDER BY row_data.ordinality),'[]'::jsonb)
 INTO history FROM jsonb_array_elements(v->'rows') WITH ORDINALITY AS row_data(value,ordinality)
 LEFT JOIN rating_validation_b3b.seals s ON s.intent_id=(row_data.value->>'intent_id')::uuid
 LEFT JOIN rating_validation_b3b.boundary_context bc ON bc.boundary_id=s.boundary_id;
 -- Do not relabel historical row payloads or rewrite append-only evidence.
 RETURN v||jsonb_build_object('baseline_context',p.baseline_context,
  'baseline_identity',p.baseline_context->>'identity','baseline_version',p.baseline_context->'version',
  'manifest_hash',p.manifest_hash,'worker_hash',p.worker_hash,
  'baseline_dataset_hash',p.baseline_context->>'baseline_sha256',
  'config_hash',p.baseline_context->>'config_sha256',
  'baseline_counts',(p.baseline_context->'counts')||jsonb_build_object('rating_events',240),
  'rows',history);
END $$;
REVOKE ALL ON FUNCTION public.export_rating_validation_evidence() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.export_rating_validation_evidence() TO service_role;
COMMIT;

-- P1R5 immutable attestation migration candidate. APPROVAL/APPLY SEPARATE.
BEGIN;
SELECT pg_advisory_xact_lock(726184501);
DO $preflight$
BEGIN
 IF to_regprocedure('public.finalize_rating_validation_seal(uuid,text)') IS NULL
 OR to_regprocedure('rating_validation_b3b.finalize_seal_core(uuid,text)') IS NULL
 OR to_regprocedure('public.capture_rating_validation_snapshot(uuid)') IS NULL
 THEN RAISE EXCEPTION 'ATTESTATION_DEPENDENCY_MISSING'; END IF;
 IF to_regclass('rating_validation_b3b.native_intents') IS NOT NULL THEN RAISE EXCEPTION 'ATTESTATION_ALREADY_INSTALLED'; END IF;
 IF encode(sha256(convert_to((SELECT prosrc FROM pg_proc WHERE oid='public.finalize_rating_validation_seal(uuid,text)'::regprocedure),'UTF8')),'hex') <> '61104bca8334cfb79b3a30eccb104be99c60a56e896e64c281361f69c4225b1c'
 OR encode(sha256(convert_to((SELECT prosrc FROM pg_proc WHERE oid='rating_validation_b3b.finalize_seal_core(uuid,text)'::regprocedure),'UTF8')),'hex') <> '7c068241e2a4c6571ec8425dc863a6bf44e87d2576b4dc21f7683706f4722c24'
 THEN RAISE EXCEPTION 'ATTESTATION_CATALOG_DRIFT'; END IF;
 IF NOT EXISTS(SELECT FROM rating_validation_b3b.environment_protocol WHERE singleton AND worker_hash='947a8cbaadd76618e933337613b37eb35c9bf77c24b1c319354e462e9165fb56' AND manifest_hash='348d713d0e6d9a88bac960f009a683ae19aa1c7679f34a76fc28394ef8896ebf') THEN RAISE EXCEPTION 'LEGACY_PROTOCOL_BINDING_DRIFT'; END IF;
END $preflight$;

CREATE TABLE rating_validation_b3b.native_intents(
 intent_id uuid PRIMARY KEY REFERENCES rating_validation_b3b.intents(id),
 attestation_version integer NOT NULL CHECK(attestation_version=2),
 native_artifact_sha256 text NOT NULL CHECK(native_artifact_sha256='018674e02538e52d64ecf8fbfe1b0d0b86d5ef3786d81e0397531a6d7997513f'),
 registered_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
REVOKE ALL ON TABLE rating_validation_b3b.native_intents FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable_rows BEFORE UPDATE OR DELETE ON rating_validation_b3b.native_intents FOR EACH ROW EXECUTE FUNCTION rating_validation_b3b.immutable();
CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON rating_validation_b3b.native_intents FOR EACH STATEMENT EXECUTE FUNCTION rating_validation_b3b.immutable();

ALTER FUNCTION public.finalize_rating_validation_seal(uuid,text) SET SCHEMA rating_validation_b3b;
ALTER FUNCTION rating_validation_b3b.finalize_rating_validation_seal(uuid,text) RENAME TO finalize_legacy_v1;
REVOKE ALL ON FUNCTION rating_validation_b3b.finalize_legacy_v1(uuid,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION rating_validation_b3b.assert_attestation(p_boundary_id uuid,v jsonb,p_native boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $body$
DECLARE intent uuid; mode rating_validation_b3b.native_intents; a jsonb; BEGIN
 PERFORM rating_validation_b3b.worker();
 SELECT intent_id INTO intent FROM rating_validation_b3b.boundaries WHERE id=p_boundary_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'BOUNDARY_NOT_FOUND'; END IF;
 SELECT * INTO mode FROM rating_validation_b3b.native_intents WHERE intent_id=intent;
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ATTESTATION_OBJECT_REQUIRED'; END IF;
 IF v->>'worker_sha256' IS DISTINCT FROM '947a8cbaadd76618e933337613b37eb35c9bf77c24b1c319354e462e9165fb56'
 OR v#>>'{computed,source_code_sha256}' IS DISTINCT FROM '604737ed1a4d8cd64fe9e6ace278954c097c74e1dc9ddb2ccdd2c2b9f98935a0'
 OR v->>'manifest_sha256' IS DISTINCT FROM '348d713d0e6d9a88bac960f009a683ae19aa1c7679f34a76fc28394ef8896ebf'
 OR v#>>'{computed,seal_version}' IS DISTINCT FROM 'B3_LOCAL_1'
 THEN RAISE EXCEPTION 'LEGACY_REFERENCE_MISMATCH'; END IF;
 IF v ?| ARRAY['native_artifact_sha256','attestation_version','protocol_reference_sha256'] THEN RAISE EXCEPTION 'ATTESTATION_SHAPE_INVALID'; END IF;
 IF NOT p_native THEN
  IF mode.intent_id IS NOT NULL OR v ? 'attestation' THEN RAISE EXCEPTION 'NATIVE_FINALIZER_REQUIRED'; END IF;
  RETURN;
 END IF;
 IF mode.intent_id IS NULL THEN RAISE EXCEPTION 'NATIVE_CAPTURE_REQUIRED'; END IF;
 a:=v->'attestation';
 IF jsonb_typeof(a) IS DISTINCT FROM 'object' OR a IS DISTINCT FROM jsonb_build_object(
 'version',2,'protocol_version','B3_LOCAL_1',
 'protocol_reference_sha256','947a8cbaadd76618e933337613b37eb35c9bf77c24b1c319354e462e9165fb56',
 'reference_source_sha256','604737ed1a4d8cd64fe9e6ace278954c097c74e1dc9ddb2ccdd2c2b9f98935a0',
 'native_artifact_sha256','018674e02538e52d64ecf8fbfe1b0d0b86d5ef3786d81e0397531a6d7997513f')
 OR mode.native_artifact_sha256 IS DISTINCT FROM a->>'native_artifact_sha256'
 THEN RAISE EXCEPTION 'NATIVE_ATTESTATION_MISMATCH'; END IF;
END $body$;
REVOKE ALL ON FUNCTION rating_validation_b3b.assert_attestation(uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.finalize_rating_validation_seal(p_boundary_id uuid,p_canonical_payload text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $body$
BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 -- Preserve exact already-accepted historical legacy retries without reclassifying/re-hashing.
 -- Native-marked intents can never use this compatibility branch.
 IF EXISTS(SELECT FROM rating_validation_b3b.seals s JOIN rating_validation_b3b.boundaries b ON b.id=s.boundary_id
  WHERE b.id=p_boundary_id AND s.canonical_payload=convert_to(p_canonical_payload,'UTF8')
  AND NOT EXISTS(SELECT FROM rating_validation_b3b.native_intents n WHERE n.intent_id=s.intent_id))
 THEN RETURN rating_validation_b3b.finalize_legacy_v1(p_boundary_id,p_canonical_payload); END IF;
 PERFORM rating_validation_b3b.assert_attestation(p_boundary_id,p_canonical_payload::jsonb,false);
 RETURN rating_validation_b3b.finalize_legacy_v1(p_boundary_id,p_canonical_payload);
END $body$;

CREATE FUNCTION public.capture_native_rating_validation_snapshot(p_intent_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $body$
DECLARE result jsonb; BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 result:=public.capture_rating_validation_snapshot(p_intent_id);
 IF result->>'already_sealed'='true' THEN RETURN result; END IF;
 INSERT INTO rating_validation_b3b.native_intents(intent_id,attestation_version,native_artifact_sha256)
 VALUES(p_intent_id,2,'018674e02538e52d64ecf8fbfe1b0d0b86d5ef3786d81e0397531a6d7997513f') ON CONFLICT(intent_id) DO NOTHING;
 IF NOT EXISTS(SELECT FROM rating_validation_b3b.native_intents WHERE intent_id=p_intent_id AND native_artifact_sha256='018674e02538e52d64ecf8fbfe1b0d0b86d5ef3786d81e0397531a6d7997513f' AND attestation_version=2) THEN RAISE EXCEPTION 'NATIVE_IDENTITY_DRIFT'; END IF;
 RETURN result;
END $body$;

CREATE FUNCTION public.finalize_native_rating_validation_seal(p_boundary_id uuid,p_canonical_payload text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $body$
BEGIN
 PERFORM rating_validation_b3b.worker(); PERFORM pg_advisory_xact_lock(726184501);
 PERFORM rating_validation_b3b.assert_attestation(p_boundary_id,p_canonical_payload::jsonb,true);
 RETURN rating_validation_b3b.finalize_legacy_v1(p_boundary_id,p_canonical_payload);
END $body$;
REVOKE ALL ON FUNCTION public.finalize_rating_validation_seal(uuid,text),public.capture_native_rating_validation_snapshot(uuid),public.finalize_native_rating_validation_seal(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.finalize_rating_validation_seal(uuid,text),public.capture_native_rating_validation_snapshot(uuid),public.finalize_native_rating_validation_seal(uuid,text) TO service_role;
COMMIT;

